const IC_API_URL        = process.env.INSPIRECORTEX_API_URL || 'https://api.inspirecortex.com';  // Remote service with Qwen 3.5 LLM
const IC_API_KEY        = process.env.INSPIRECORTEX_API_KEY        || '';
// JWT-based auth (preferred over API key — use pre-generated long-lived token)
const IC_JWT            = process.env.INSPIRECORTEX_JWT            || '';
// Cloudflare Access Service Token (required when calling api.inspirecortex.com from production)
const IC_CF_CLIENT_ID   = process.env.INSPIRECORTEX_CF_CLIENT_ID   || '';
const IC_CF_CLIENT_SECRET = process.env.INSPIRECORTEX_CF_CLIENT_SECRET || '';

/** Returns auth headers for InspireCortex API calls */
function icHeaders(extra = {}) {
    const token = IC_JWT || IC_API_KEY;
    const h = { 'Authorization': `Bearer ${token}`, ...extra };
    if (IC_CF_CLIENT_ID)     h['CF-Access-Client-Id']     = IC_CF_CLIENT_ID;
    if (IC_CF_CLIENT_SECRET) h['CF-Access-Client-Secret'] = IC_CF_CLIENT_SECRET;
    return h;
}

/**
 * Call the InspireCortex LLM (Mistral-7B-Instruct on RTX 5090) for text generation.
 * Drop-in replacement for anthropic.messages.create — returns the assistant text string.
 * Falls back to null on any error so callers can degrade gracefully.
 *
 * @param {string}  systemPrompt  System/persona instructions
 * @param {string}  userContent   User turn content
 * @param {number}  maxTokens     Max tokens to generate (default 2048)
 * @param {number}  temperature   Sampling temperature (default 0.7)
 * @returns {Promise<string|null>}
 */
function callICLLM(systemPrompt, userContent, maxTokens = 2048, temperature = 0.7) {
    return new Promise((resolve) => {
        const body = JSON.stringify({
            messages:      [{ role: 'user', content: userContent }],
            system_prompt: systemPrompt || undefined,
            max_tokens:    maxTokens,
            temperature,
            stream:        false,
        });
        const url    = new URL(`${IC_API_URL}/v1/llm/chat`);
        const isHttps = url.protocol === 'https:';
        const lib    = isHttps ? require('https') : require('http');
        console.log('[ICLLM] →', url.href, 'body:', body.length, 'bytes');
        const req    = lib.request({
            hostname: url.hostname,
            port:     url.port || (isHttps ? 443 : 80),
            path:     url.pathname,
            method:   'POST',
            headers:  icHeaders({
                'Content-Type':   'application/json',
                'Content-Length': Buffer.byteLength(body),
                'Connection':     'close',   // SSH tunnels don't support keep-alive
            }),
            timeout:  120000,
            agent:    false,   // Disable connection pooling — new socket per request
        }, res => {
            console.log(`[ICLLM] HTTP ${res.statusCode}, headers:`, res.headers);
            const chunks = [];
            res.on('data', c => chunks.push(c));
            res.on('end', () => {
                const d = Buffer.concat(chunks).toString('utf8');
                console.log(`[ICLLM] Response body (${d.length} bytes):`, d.slice(0, 500));
                try {
                    const j = JSON.parse(d);
                    resolve(j.choices?.[0]?.message?.content?.trim() || null);
                } catch (e) {
                    console.warn('[ICLLM] Parse error:', e.message);
                    resolve(null);
                }
            });
        });
        req.on('error', e  => { console.warn('[ICLLM] Request error:', e.code || e.message || String(e)); resolve(null); });
        req.on('timeout', () => { req.destroy(); console.warn('[ICLLM] Request timed out (120s)'); resolve(null); });
        req.write(body);
        req.end();
    });
}

