/**
 * Build a quick on-demand image prompt via Mistral-7B.
 * Falls back to a simple template if Mistral is unavailable.
 */
async function buildICPromptForArticle(title, content, customOptions = []) {
    const excerpt = (content || '').replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim().slice(0, 1800);
    const customModifiers = customOptions
        .map(o => IC_CUSTOM_OPTION_PROMPTS[o])
        .filter(Boolean)
        .join(', ');

    const systemMsg = `You are a cinematic art director for a faith-based Christian website. Write ONE precise, photorealistic image generation prompt. MANDATORY SAFETY RULES: ALL people in the image must be fully clothed in modest, appropriate attire — never any nudity, bare skin, revealing clothing, underwear, or sexual content. The image must be uplifting, warm, and encouraging — never dark or despairing. Format: 16:9 cinematic landscape, DSLR quality, golden-hour natural lighting. No text, watermarks, or logos.${customModifiers ? ` Visual themes: ${customModifiers}.` : ''} Output ONLY the prompt text.`;

    const userMsg = `Article: "${title}"\n\n${excerpt}\n\nWrite one 3-sentence image prompt describing a hopeful, joyful scene that captures the essence of this article. Include subject, setting, and photographic specs.`;

    try {
        const resp = await new Promise((resolve, reject) => {
            const body = JSON.stringify({ model: 'mistral-7b-instruct', messages: [{ role: 'system', content: systemMsg }, { role: 'user', content: userMsg }], max_tokens: 400, temperature: 0.7 });
            const req = require('http').request({ hostname: 'localhost', port: 9001, path: '/v1/chat/completions', method: 'POST', headers: { 'Content-Type': 'application/json', 'Content-Length': Buffer.byteLength(body) } }, res => {
                let d = '';
                res.on('data', c => d += c);
                res.on('end', () => {
                    try { resolve(JSON.parse(d).choices?.[0]?.message?.content?.trim() || ''); }
                    catch (e) { resolve(''); }
                });
            });
            req.on('error', reject);
            req.write(body);
            req.end();
        });
        if (resp) return resp.slice(0, 1600);
    } catch (_) { /* fall through to template */ }

    // Template fallback
    const modifier = customModifiers ? ` ${customModifiers},` : '';
    return `A joyful, uplifting scene inspired by "${title}".${modifier} Photorealistic cinematic 16:9 landscape, golden-hour natural lighting, warm amber tones, shallow depth of field, 85mm lens f/2.0, DSLR quality. Negative: ${IC_STANDARD_NEGATIVE}`;
}

/**
 * Build a rich, category-aware image prompt for a jv_content_objects article.
 * Combines article title + body content + taxonomy category name to construct
 * a contextually precise, brand-compliant Mistral-7B prompt.
 * Falls back to a category-tailored template when Mistral is unavailable.
 *
 * @param {string} title          - Article title
 * @param {string} content        - Plain-text article body (HTML stripped)
 * @param {string} categoryName   - Taxonomy node name (e.g. "Encouragement")
 * @param {string} [logTag]       - Log prefix for structured output
 */
async function buildJVContentImagePrompt(title, content, categoryName, logTag = '[JVPrompt]') {
    const categoryKey   = (categoryName || '').toLowerCase().trim();
    const modifierKeys  = JV_CATEGORY_MODIFIERS[categoryKey] || ['inspirational', 'faith-theme', 'hopeful'];
    const customModStr  = modifierKeys.map(k => IC_CUSTOM_OPTION_PROMPTS[k]).filter(Boolean).join(', ');
    const excerpt       = (content || '').slice(0, 1800);

    const systemMsg = [
        'You are a cinematic art director for JubileeVerse, a faith-based Christian website.',
        'Your task: write ONE precise, photorealistic image-generation prompt for the article below.',
        '',
        'MANDATORY BRAND & SAFETY RULES:',
        '• All people must be fully clothed in modest, appropriate attire — no nudity, bare skin, or revealing clothing.',
        '• Mood must be uplifting, warm, hopeful, and encouraging — never dark, violent, or despairing.',
        `• Taxonomy category: "${categoryName}" — align all visual themes with this context.`,
        `• Category visual modifiers: ${customModStr}.`,
        '• Format: 16:9 cinematic landscape, DSLR quality, golden-hour natural lighting.',
        '• Pure visual representation - focus on photographic composition and lighting.',
        '',
        'Output ONLY the prompt text — no preamble, no labels, no quotes. Three sentences maximum.',
    ].join('\n');

    const userMsg = [
        `Article title: "${title}"`,
        excerpt ? `\nArticle content:\n${excerpt}\n` : '',
        'Describe a visually striking, emotionally resonant, faith-aligned scene that captures the essence of this article.',
        'Include: main subject, setting/environment, mood/lighting, and photographic style.',
    ].join('\n');

    try {
        const resp = await new Promise((resolve, reject) => {
            const body = JSON.stringify({
                model: 'mistral-7b-instruct',
                messages: [{ role: 'system', content: systemMsg }, { role: 'user', content: userMsg }],
                max_tokens: 450,
                temperature: 0.75,
            });
            const req = require('http').request({
                hostname: 'localhost', port: 9001, path: '/v1/chat/completions',
                method: 'POST',
                headers: { 'Content-Type': 'application/json', 'Content-Length': Buffer.byteLength(body) },
                timeout: 30000,
            }, res => {
                let d = '';
                res.on('data', c => d += c);
                res.on('end', () => {
                    try { resolve(JSON.parse(d).choices?.[0]?.message?.content?.trim() || ''); }
                    catch (e) { resolve(''); }
                });
            });
            req.on('error', reject);
            req.on('timeout', () => { req.destroy(); reject(new Error('Mistral-7B timed out')); });
            req.write(body);
            req.end();
        });
        if (resp) {
            console.log(`${logTag} Mistral-7B prompt OK (${resp.length} chars): ${resp.slice(0, 100)}…`);
            return resp.slice(0, 1600);
        }
    } catch (err) {
        console.warn(`${logTag} Mistral-7B unavailable (${err.message}) — using template`);
    }

    // Category-tailored template fallback (no external dependency)
    const modStr = customModStr ? ` ${customModStr},` : '';
    const cat    = categoryName ? ` in the "${categoryName}" category` : '';
    return `A joyful, uplifting faith-inspired scene for "${title}"${cat}.${modStr} Photorealistic cinematic 16:9 landscape, golden-hour natural lighting, warm amber tones, shallow depth of field, 85mm lens f/2.0, DSLR quality, Christian faith aesthetic. Negative: ${IC_STANDARD_NEGATIVE}`;
}

/**
 * IC LLM chat helper — calls Mistral-7B-Instruct at localhost:9001 (OpenAI-compatible).
 * Supports optional OpenAI-format tools for function calling.
 * Returns the full parsed response object (choices[0].message etc.).
 */
function callICLLMChat(messages, { maxTokens = 1024, temperature = 0.7, tools = null } = {}) {
    return new Promise((resolve, reject) => {
        const payload = { model: 'mistral-7b-instruct', messages, max_tokens: maxTokens, temperature };
        if (tools) payload.tools = tools;
        const body = JSON.stringify(payload);

        // Use remote InspireCortex API (Qwen 3.5 LLM)
        const url = new URL(`${IC_API_URL}/v1/chat/completions`);
        const isHttps = url.protocol === 'https:';
        const lib = isHttps ? require('https') : require('http');

        const req = lib.request({
            hostname: url.hostname,
            port: url.port || (isHttps ? 443 : 80),
            path: url.pathname,
            method: 'POST',
            headers: icHeaders({ 'Content-Type': 'application/json', 'Content-Length': Buffer.byteLength(body) }),
            timeout: 60000,
        }, res => {
            let d = '';
            res.on('data', c => d += c);
            res.on('end', () => {
                try { resolve(JSON.parse(d)); }
                catch (e) { reject(new Error(`IC LLM parse: ${d.slice(0, 200)}`)); }
            });
        });
        req.on('error', reject);
        req.on('timeout', () => { req.destroy(); reject(new Error('IC LLM timed out')); });
        req.write(body);
        req.end();
    });
}

/**
 * POST to IC /v1/images/generate.
 * Synchronous — blocks ~90s on server, returns { job_id, status, output_url, gpu_time_ms }.
 * Image can be downloaded via GET /v1/jobs/{job_id}/image.
 */
async function callMidjourneyGenerate(prompt, negativePrompt, redirectAttempts = 0) {
    if (redirectAttempts > 5) {
        throw new Error('Too many redirects');
    }

    return new Promise((resolve, reject) => {
        const body = JSON.stringify({
            prompt,
            negative_prompt: negativePrompt || undefined,
            model:           'juggernaut-xl',
            width:           1472,
            height:          832,
            steps:           30,
            guidance_scale:  7.0,
        });

        console.log(`[callMidjourneyGenerate] ========== IC API CALL ==========`);
        console.log(`[callMidjourneyGenerate] URL: ${IC_API_URL}/v1/images/generate`);
        console.log(`[callMidjourneyGenerate] IC_JWT configured: ${!!IC_JWT}`);
        console.log(`[callMidjourneyGenerate] IC_CF_CLIENT_ID configured: ${!!IC_CF_CLIENT_ID}`);
        console.log(`[callMidjourneyGenerate] IC_CF_CLIENT_SECRET configured: ${!!IC_CF_CLIENT_SECRET}`);

        const bodyObj = JSON.parse(body);
        console.log(`[callMidjourneyGenerate] Positive prompt:\n${bodyObj.prompt}\n`);
        console.log(`[callMidjourneyGenerate] Negative prompt:\n${bodyObj.negative_prompt}\n`);

        const url  = new URL(`${IC_API_URL}/v1/images/generate`);
        const headers = icHeaders({ 'Content-Type': 'application/json', 'Content-Length': Buffer.byteLength(body) });
        console.log(`[callMidjourneyGenerate] Headers being sent:`, Object.keys(headers).map(k => `${k}: ${headers[k] ? '***' : '(empty)'}`.slice(0, 100)));

        const opts = {
            hostname: url.hostname,
            port:     url.port || (url.protocol === 'https:' ? 443 : 80),
            path:     url.pathname + (url.search || ''),
            method:   'POST',
            headers:  headers,
            timeout:  15000,  // 15 second timeout
        };
        const transport = url.protocol === 'https:' ? require('https') : require('http');
        const req = transport.request(opts, res => {
            console.log(`[callMidjourneyGenerate] ✓ IC API responded with status: ${res.statusCode}`);

            // Handle redirects (301, 302, 303, 307, 308)
            if (res.statusCode >= 300 && res.statusCode < 400 && res.headers.location) {
                console.log(`[callMidjourneyGenerate] Following redirect to: ${res.headers.location}`);
                res.destroy();
                // Recursively follow redirect
                callMidjourneyGenerate(prompt, negativePrompt, redirectAttempts + 1)
                    .then(resolve)
                    .catch(reject);
                return;
            }

            let d = '';
            res.on('data', c => d += c);
            res.on('end', () => {
                try {
                    if (d.length === 0) {
                        reject(new Error(`Empty response from IC API (status ${res.statusCode})`));
                        return;
                    }
                    const parsed = JSON.parse(d);
                    console.log(`[callMidjourneyGenerate] Response:`, JSON.stringify(parsed).slice(0, 500));
                    if (res.statusCode >= 400) return reject(new Error(`IC API ${res.statusCode}: ${JSON.stringify(parsed).slice(0, 200)}`));
                    resolve(parsed);
                } catch (e) { reject(new Error(`Parse error: ${d.slice(0, 200)}`)); }
            });
        });
        req.on('error', (err) => {
            console.error(`[callMidjourneyGenerate] ✗ IC API error: ${err.message}`);
            reject(err);
        });
        req.on('timeout', () => {
            req.destroy();
            console.error(`[callMidjourneyGenerate] ✗ IC API timeout (15s)`);
            reject(new Error('IC API timeout'));
        });
        req.write(body);
        req.end();
    });
}

/**
 * Download a MidJourney variation image via /v1/midjourney/image/{minio_key}.
 */
function downloadMidjourneyImage(minioKey, destPath) {
    return new Promise((resolve, reject) => {
        const encodedKey = minioKey.split('/').map(encodeURIComponent).join('/');
        const url  = new URL(`${IC_API_URL}/v1/midjourney/image/${encodedKey}`);
        const transport = url.protocol === 'https:' ? require('https') : require('http');
        const req = transport.request({
            hostname: url.hostname,
            port:     url.port || (url.protocol === 'https:' ? 443 : 80),
            path:     url.pathname,
            method:   'GET',
            headers:  icHeaders(),
        }, res => {
            if (res.statusCode !== 200) {
                let d = '';
                res.on('data', c => d += c);
                res.on('end', () => reject(new Error(`MJ image download failed: HTTP ${res.statusCode}`)));
                return;
            }
            const chunks = [];
            res.on('data', c => chunks.push(c));
            res.on('end', () => {
                try {
                    require('fs').mkdirSync(require('path').dirname(destPath), { recursive: true });
                    require('fs').writeFileSync(destPath, Buffer.concat(chunks));
                    resolve();
                } catch (e) { reject(e); }
            });
        });
        req.on('error', reject);
        req.end();
    });
}

/**
 * GET /v1/jobs/{jobId}/status from InspireCortex.
 * Returns { status, output_urls, gpu_time_ms, ... }
 */
async function checkICJobStatus(jobId) {
    return new Promise((resolve, reject) => {
        const url  = new URL(`${IC_API_URL}/v1/jobs/${jobId}/status`);
        const opts = {
            hostname: url.hostname,
            port:     url.port || (url.protocol === 'https:' ? 443 : 80),
            path:     url.pathname,
            method:   'GET',
            headers:  icHeaders(),
        };
        const transport = url.protocol === 'https:' ? require('https') : require('http');
        const req = transport.request(opts, res => {
            let d = '';
            res.on('data', c => d += c);
            res.on('end', () => {
                try { resolve(JSON.parse(d)); }
                catch (e) { reject(new Error(`IC status parse error: ${d.slice(0, 200)}`)); }
            });
        });
        req.on('error', reject);
        req.end();
    });
}

/**
 * Download an image from a URL (CDN / MinIO) and save it to destPath.
 * For IC job images, use downloadICJobImage(jobId, destPath) instead.
 */
function downloadICImage(imageUrl, destPath) {
    return new Promise((resolve, reject) => {
        const transport = imageUrl.startsWith('https:') ? require('https') : require('http');
        transport.get(imageUrl, res => {
            if (res.statusCode !== 200) return reject(new Error(`Image download failed: HTTP ${res.statusCode}`));
            const chunks = [];
            res.on('data', c => chunks.push(c));
            res.on('end', () => {
                try {
                    const fs = require('fs');
                    fs.mkdirSync(require('path').dirname(destPath), { recursive: true });
                    fs.writeFileSync(destPath, Buffer.concat(chunks));
                    resolve();
                } catch (e) { reject(e); }
            });
        }).on('error', reject);
    });
}

/**
 * Download a completed IC job image via /v1/jobs/{jobId}/image gateway endpoint.
 * This works from any server — the gateway proxies MinIO internally.
 */
function downloadICJobImage(jobId, destPath) {
    return new Promise((resolve, reject) => {
        const url  = new URL(`${IC_API_URL}/v1/jobs/${jobId}/image`);
        const transport = url.protocol === 'https:' ? require('https') : require('http');
        const req = transport.request({
            hostname: url.hostname,
            port:     url.port || (url.protocol === 'https:' ? 443 : 80),
            path:     url.pathname,
            method:   'GET',
            headers:  icHeaders(),
        }, res => {
            if (res.statusCode !== 200) {
                let d = '';
                res.on('data', c => d += c);
                res.on('end', () => reject(new Error(`IC image download failed: HTTP ${res.statusCode} — ${d.slice(0, 100)}`)));
                return;
            }
            const chunks = [];
            res.on('data', c => chunks.push(c));
            res.on('end', () => {
                try {
                    const fs = require('fs');
                    fs.mkdirSync(require('path').dirname(destPath), { recursive: true });
                    fs.writeFileSync(destPath, Buffer.concat(chunks));
                    resolve();
                } catch (e) { reject(e); }
            });
        });
        req.on('error', reject);
        req.end();
    });
}

// =============================================================================
// DALL-E 3 IMAGE GENERATION (used by reviewer buttons — works from any server)
// =============================================================================

const OPENAI_API_KEY_PRIMARY  = process.env.OPENAI_API_KEY_PRIMARY  || '';
const OPENAI_API_KEY_BACKUP   = process.env.OPENAI_API_KEY_BACKUP   || '';
const OPENAI_API_KEY_FOR_IMAGES = OPENAI_API_KEY_PRIMARY || OPENAI_API_KEY_BACKUP;

const DALLE3_SAFETY_CLAUSE = 'All people must be fully clothed in modest appropriate attire. No nudity, no bare skin, no revealing clothing, no sexual content whatsoever.';

function callDALLE3(apiKey, prompt) {
    const safePrompt = `${prompt} ${DALLE3_SAFETY_CLAUSE}`.slice(0, 3900);
    const body = JSON.stringify({ model: 'dall-e-3', prompt: safePrompt, n: 1, size: '1792x1024', quality: 'standard', response_format: 'url' });
    return new Promise((resolve, reject) => {
        const req = require('https').request({
            hostname: 'api.openai.com', port: 443, path: '/v1/images/generations', method: 'POST',
            headers: { 'Content-Type': 'application/json', 'Content-Length': Buffer.byteLength(body), 'Authorization': `Bearer ${apiKey}` },
        }, res => {
            let d = '';
            res.on('data', c => d += c);
            res.on('end', () => {
                try {
                    const parsed = JSON.parse(d);
                    if (parsed.error) return reject(new Error(parsed.error.message));
                    const url = parsed.data?.[0]?.url;
                    if (!url) return reject(new Error('No URL in DALL-E response'));
                    resolve(url);
                } catch (e) { reject(new Error(`DALL-E parse: ${d.slice(0, 200)}`)); }
            });
        });
        req.on('error', reject);
        req.write(body);
        req.end();
    });
}

/**
 * Async DALL-E 3 image generation job. Tries primary key first, falls back to backup key on billing errors.
 * Fires off in background; updates _icJobTracker with status when done.
 */
async function runDALLE3Job(jobId, prompt) {
    const jobInfo = _icJobTracker.get(jobId);
    if (!jobInfo) return;

    try {
        let imageUrl;
        try {
            imageUrl = await callDALLE3(OPENAI_API_KEY_PRIMARY || OPENAI_API_KEY_BACKUP, prompt);
        } catch (primaryErr) {
            const isBillingError = primaryErr.message.includes('billing') || primaryErr.message.includes('limit') || primaryErr.message.includes('quota') || primaryErr.message.includes('insufficient');
            if (isBillingError && OPENAI_API_KEY_BACKUP && OPENAI_API_KEY_BACKUP !== OPENAI_API_KEY_PRIMARY) {
                console.warn(`[DALLE3] Primary key billing error — trying backup key`);
                imageUrl = await callDALLE3(OPENAI_API_KEY_BACKUP, prompt);
            } else {
                throw primaryErr;
            }
        }

        // Download image from OpenAI CDN
        await downloadICImage(imageUrl, jobInfo.destPath);

        // Update DB
        if (jobInfo.pool === 'inspirePool') {
            await inspirePool.query(
                `UPDATE articles SET hero_image_path = $1, hero_image_status = 'generated',
                 hero_image_provider = 'dalle3', hero_image_model = 'dall-e-3',
                 hero_image_generated_at = CURRENT_TIMESTAMP, updated_at = CURRENT_TIMESTAMP
                 WHERE id = $2`,
                [jobInfo.dbPath, jobInfo.articleId]
            );
        } else if (jobInfo.pool === 'jv_content') {
            await pgPool.query(
                `UPDATE jv_content_objects SET extension_data = jsonb_set(COALESCE(extension_data,'{}'),'{hero_image_path}',$1::jsonb), updated_at=NOW() WHERE id=$2`,
                [JSON.stringify(jobInfo.dbPath), jobInfo.articleId]
            );
        } else {
            await pgPool.query(
                `UPDATE current_events SET cached_image_path = $1, updated_at = CURRENT_TIMESTAMP WHERE id = $2`,
                [jobInfo.dbPath, jobInfo.articleId]
            );
        }

        _icJobTracker.set(jobId, { ...jobInfo, status: 'completed' });
        console.log(`[DALLE3] Job ${jobId} completed — ${jobInfo.dbPath}`);
    } catch (err) {
        console.error(`[DALLE3] Job ${jobId} failed:`, err.message);
        _icJobTracker.set(jobId, { ...(_icJobTracker.get(jobId) || {}), status: 'failed', error: err.message });
    }
}

// =============================================================================
// INSPIRECORTEX GPU JOB RUNNER (preferred over DALL-E 3 when JWT is configured)
// =============================================================================

/**
 * Async image generation job using the Jubilee MidJourney model via InspireCortex.
 * Synchronous call — server blocks ~45-90s while GPU generates 4 upscaled variations.
 * Downloads first variation via MinIO gateway, then updates DB.
 */
async function runICJob(jobId, prompt) {
    const jobInfo = _icJobTracker.get(jobId);
    if (!jobInfo) return;

    if (!IC_JWT && !IC_API_KEY) {
        console.warn(`[ICJob] No IC JWT/key configured — cannot generate image for job ${jobId}`);
        _icJobTracker.set(jobId, { ...(_icJobTracker.get(jobId) || {}), status: 'failed', error: 'No IC credentials configured' });
        return;
    }

    try {
        // Call IC image generation (synchronous, blocks until image is ready)
        // Strip any "Negative: ..." suffix from the main prompt — pass it separately as negative_prompt
        const negMatch = prompt.match(/\s*\bNegative:\s+([\s\S]*)$/i);
        const mjPrompt = prompt.replace(/\s*\bNegative:\s+[\s\S]*$/i, '').trim();
        const mjNegative = negMatch ? negMatch[1].trim() : undefined;

        // Safe fallback prompt used when the LLM-generated prompt triggers a content policy block
        const IC_SAFE_FALLBACK_PROMPT = 'A joyful Christian congregation gathered in warm golden light inside a beautiful church, people smiling and praying together, cinematic photorealistic 16:9 landscape, shallow depth of field, DSLR quality, uplifting and hopeful atmosphere';

        let mjResult;
        for (const [attemptNum, attemptPrompt] of [[1, mjPrompt], [2, IC_SAFE_FALLBACK_PROMPT]]) {
            try {
                console.log(`[ICJob] Calling IC image generation for job ${jobId} (attempt ${attemptNum})... prompt: ${attemptPrompt.slice(0, 80)}...`);
                mjResult = await callMidjourneyGenerate(attemptPrompt, attemptNum === 1 ? mjNegative : undefined);
                break;
            } catch (icErr) {
                const isContentPolicy = icErr.message.includes('content policy') || icErr.message.includes('blocked') || icErr.message.includes('inappropriate') || icErr.message.includes('400');
                if (attemptNum === 1 && isContentPolicy) {
                    console.warn(`[ICJob] Content policy block on prompt — retrying with safe fallback prompt`);
                } else {
                    throw icErr;
                }
            }
        }
        if (!mjResult?.job_id) throw new Error(`No job_id in IC image response: ${JSON.stringify(mjResult)}`);
        console.log(`[ICJob] IC image ready — job: ${mjResult.job_id} (gpu: ${mjResult.gpu_time_ms}ms)`);

        // Download image via gateway endpoint
        await downloadICJobImage(mjResult.job_id, jobInfo.destPath);

        // Update DB
        if (jobInfo.pool === 'inspirePool') {
            await inspirePool.query(
                `UPDATE articles SET hero_image_path = $1, hero_image_status = 'generated',
                 hero_image_provider = 'local_gpu', hero_image_model = 'jubilee-midjourney',
                 hero_image_generated_at = CURRENT_TIMESTAMP, updated_at = CURRENT_TIMESTAMP
                 WHERE id = $2`,
                [jobInfo.dbPath, jobInfo.articleId]
            );
        } else if (jobInfo.pool === 'jv_content') {
            await pgPool.query(
                `UPDATE jv_content_objects SET extension_data = jsonb_set(COALESCE(extension_data,'{}'),'{hero_image_path}',$1::jsonb), updated_at=NOW() WHERE id=$2`,
                [JSON.stringify(jobInfo.dbPath), jobInfo.articleId]
            );
        } else {
            await pgPool.query(
                `UPDATE current_events SET cached_image_path = $1, updated_at = CURRENT_TIMESTAMP WHERE id = $2`,
                [jobInfo.dbPath, jobInfo.articleId]
            );
        }

        _icJobTracker.set(jobId, { ...jobInfo, status: 'completed' });
        console.log(`[ICJob] Job ${jobId} completed — ${jobInfo.dbPath}`);
    } catch (err) {
        console.warn(`[ICJob] MidJourney failed (${err.message}) — falling back to Leonardo AI`);
        try {
            const LeonardoAPI = require('./lib/leonardo-api');
            const primaryKey = process.env.LEONARDO_API_KEY_PRIMARY;
            const backupKey  = process.env.LEONARDO_API_KEY_BACKUP;

            // Try primary Leonardo key first, then backup if token-exhausted
            let leonardoErr;
            for (const key of [primaryKey, backupKey].filter(Boolean)) {
                try {
                    const leonardo = new LeonardoAPI(key);
                    await leonardo.generateAndDownload(prompt, jobInfo.destPath);
                    leonardoErr = null;
                    break;
                } catch (keyErr) {
                    leonardoErr = keyErr;
                    const isTokenErr = keyErr.message.includes('not enough api tokens') || keyErr.message.includes('token');
                    if (isTokenErr && key === primaryKey && backupKey && backupKey !== primaryKey) {
                        console.warn(`[ICJob] Leonardo primary key exhausted — trying backup key`);
                    } else {
                        break; // non-token error or no backup, stop trying
                    }
                }
            }
            if (leonardoErr) throw leonardoErr;

            if (jobInfo.pool === 'inspirePool') {
                await inspirePool.query(
                    `UPDATE articles SET hero_image_path = $1, hero_image_status = 'generated',
                     hero_image_provider = 'leonardo', hero_image_model = 'leonardo-ai',
                     hero_image_generated_at = CURRENT_TIMESTAMP, updated_at = CURRENT_TIMESTAMP
                     WHERE id = $2`,
                    [jobInfo.dbPath, jobInfo.articleId]
                );
            } else if (jobInfo.pool === 'jv_content') {
                await pgPool.query(
                    `UPDATE jv_content_objects SET extension_data = jsonb_set(COALESCE(extension_data,'{}'),'{hero_image_path}',$1::jsonb), updated_at=NOW() WHERE id=$2`,
                    [JSON.stringify(jobInfo.dbPath), jobInfo.articleId]
                );
            } else {
                await pgPool.query(
                    `UPDATE current_events SET cached_image_path = $1, updated_at = CURRENT_TIMESTAMP WHERE id = $2`,
                    [jobInfo.dbPath, jobInfo.articleId]
                );
            }
            _icJobTracker.set(jobId, { ...jobInfo, status: 'completed' });
            console.log(`[ICJob] Leonardo AI fallback succeeded for job ${jobId} — ${jobInfo.dbPath}`);
        } catch (fallbackErr) {
            // Leonardo exhausted — try DALL-E 3 as last resort
            console.warn(`[ICJob] Leonardo failed (${fallbackErr.message}) — trying DALL-E 3 as last resort`);
            try {
                let imageUrl;
                try {
                    imageUrl = await callDALLE3(OPENAI_API_KEY_PRIMARY || OPENAI_API_KEY_BACKUP, prompt);
                } catch (d3Err) {
                    const isBilling = d3Err.message.includes('billing') || d3Err.message.includes('limit') || d3Err.message.includes('quota') || d3Err.message.includes('insufficient');
                    if (isBilling && OPENAI_API_KEY_BACKUP && OPENAI_API_KEY_BACKUP !== OPENAI_API_KEY_PRIMARY) {
                        console.warn(`[ICJob] DALL-E 3 primary key billing error — trying backup`);
                        imageUrl = await callDALLE3(OPENAI_API_KEY_BACKUP, prompt);
                    } else {
                        throw d3Err;
                    }
                }
                await downloadICImage(imageUrl, jobInfo.destPath);
                if (jobInfo.pool === 'inspirePool') {
                    await inspirePool.query(
                        `UPDATE articles SET hero_image_path = $1, hero_image_status = 'generated',
                         hero_image_provider = 'dalle3', hero_image_model = 'dall-e-3',
                         hero_image_generated_at = CURRENT_TIMESTAMP, updated_at = CURRENT_TIMESTAMP
                         WHERE id = $2`,
                        [jobInfo.dbPath, jobInfo.articleId]
                    );
                } else if (jobInfo.pool === 'jv_content') {
                    await pgPool.query(
                        `UPDATE jv_content_objects SET extension_data = jsonb_set(COALESCE(extension_data,'{}'),'{hero_image_path}',$1::jsonb), updated_at=NOW() WHERE id=$2`,
                        [JSON.stringify(jobInfo.dbPath), jobInfo.articleId]
                    );
                } else {
                    await pgPool.query(
                        `UPDATE current_events SET cached_image_path = $1, updated_at = CURRENT_TIMESTAMP WHERE id = $2`,
                        [jobInfo.dbPath, jobInfo.articleId]
                    );
                }
                _icJobTracker.set(jobId, { ...jobInfo, status: 'completed' });
                console.log(`[ICJob] DALL-E 3 last-resort succeeded for job ${jobId} — ${jobInfo.dbPath}`);
            } catch (lastErr) {
                console.error(`[ICJob] Job ${jobId} failed (MJ + Leonardo + DALL-E 3 all failed):`, lastErr.message);
                _icJobTracker.set(jobId, { ...(_icJobTracker.get(jobId) || {}), status: 'failed', error: lastErr.message });
            }
        }
    }
}

// =============================================================================
// LIVE SPORTS DATA CACHE
// =============================================================================

// TheSportsDB Free API (no key required for basic queries)
const SPORTS_API_BASE = 'https://www.thesportsdb.com/api/v1/json/3';

// League IDs for different sports
const LEAGUE_IDS = {
    EPL: '4328',      // English Premier League
    LALIGA: '4335',   // Spanish La Liga
    BUNDESLIGA: '4331', // German Bundesliga
    SERIEA: '4332',   // Italian Serie A
    NFL: '4391',      // NFL
    NBA: '4387',      // NBA
    MLB: '4424',      // MLB
    IPL: '4453',      // Indian Premier League (Cricket)
    // Note: Cricket international data is limited in free tier
};

// Cache for sports data (refreshes every 5 minutes)
let sportsCache = {
    data: null,
    lastUpdated: 0,
    CACHE_DURATION: 5 * 60 * 1000 // 5 minutes
};

async function fetchJson(url) {
    return new Promise((resolve, reject) => {
        const protocol = url.startsWith('https') ? https : http;
        const req = protocol.get(url, { timeout: 10000 }, (res) => {
            let data = '';
            res.on('data', chunk => data += chunk);
            res.on('end', () => {
                try {
                    resolve(JSON.parse(data));
                } catch (e) {
                    reject(e);
                }
            });
        });
        req.on('error', reject);
        req.on('timeout', () => { req.destroy(); reject(new Error('Timeout')); });
    });
}

async function fetchSportsData() {
    const now = Date.now();
    if (sportsCache.data && (now - sportsCache.lastUpdated) < sportsCache.CACHE_DURATION) {
        return sportsCache.data;
    }

    try {
        // Fetch past events from Premier League (most reliable free data)
        const [eplPast, eplNext] = await Promise.all([
            fetchJson(`${SPORTS_API_BASE}/eventspastleague.php?id=${LEAGUE_IDS.EPL}`).catch(() => ({ events: null })),
            fetchJson(`${SPORTS_API_BASE}/eventsnextleague.php?id=${LEAGUE_IDS.EPL}`).catch(() => ({ events: null }))
        ]);

        const formatMatch = (event, type) => {
            if (!event) return null;
            const isResult = type === 'result';
            return {
                type,
                team1: {
                    name: event.strHomeTeam,
                    short: event.strHomeTeam?.substring(0, 3).toUpperCase() || 'TBD',
                    flag: '⚽',
                    score: isResult ? (event.intHomeScore || '0') : undefined,
                    badge: event.strHomeTeamBadge
                },
                team2: {
                    name: event.strAwayTeam,
                    short: event.strAwayTeam?.substring(0, 3).toUpperCase() || 'TBD',
                    flag: '⚽',
                    score: isResult ? (event.intAwayScore || '0') : undefined,
                    badge: event.strAwayTeamBadge
                },
                status: isResult ? (event.strStatus || 'Final') : undefined,
                result: isResult ? `${event.intHomeScore}-${event.intAwayScore}` : undefined,
                date: event.dateEvent ? new Date(event.dateEvent).toLocaleDateString('en-US', { month: 'short', day: 'numeric' }) : 'TBD',
                time: event.strTime ? event.strTime.substring(0, 5) : 'TBD',
                venue: event.strVenue || 'TBD',
                league: event.strLeague
            };
        };

        const pastMatches = (eplPast.events || []).slice(0, 5).map(e => formatMatch(e, 'result')).filter(Boolean);
        const upcomingMatches = (eplNext.events || []).slice(0, 3).map(e => formatMatch(e, 'upcoming')).filter(Boolean);

        // Structure data by region
        const sportsData = {
            US: {
                league: 'Premier League',
                icon: '⚽',
                link: 'Football',
                matches: [...pastMatches.slice(0, 2), ...upcomingMatches.slice(0, 1)],
                lastUpdated: new Date().toISOString()
            },
            GB: {
                league: 'Premier League',
                icon: '⚽',
                link: 'Football',
                matches: [...pastMatches.slice(0, 2), ...upcomingMatches.slice(0, 1)],
                lastUpdated: new Date().toISOString()
            },
            IN: {
                league: 'Premier League',
                icon: '⚽',
                link: 'Football',
                matches: [...pastMatches.slice(0, 2), ...upcomingMatches.slice(0, 1)],
                lastUpdated: new Date().toISOString()
            },
            DEFAULT: {
                league: 'Premier League',
                icon: '⚽',
                link: 'Football',
                matches: [...pastMatches.slice(0, 2), ...upcomingMatches.slice(0, 1)],
                lastUpdated: new Date().toISOString()
            }
        };

        sportsCache.data = sportsData;
        sportsCache.lastUpdated = now;
        console.log('[Sports] Cache updated at', new Date().toISOString());
        return sportsData;
    } catch (err) {
        console.error('[Sports] Error fetching data:', err.message);
        // Return cached data if available, or fallback
        if (sportsCache.data) return sportsCache.data;
        return null;
    }
}

// Trust proxy for proper client IP detection
app.set('trust proxy', 1);

// =============================================================================
// MIDDLEWARE
// =============================================================================

// Phase 10: Security headers
const helmet = require('helmet');
app.use(helmet({
    contentSecurityPolicy: {
        directives: {
            defaultSrc: ["'self'"],
            scriptSrc:  ["'self'", "'unsafe-inline'", "cdn.jsdelivr.net", "cdnjs.cloudflare.com"],
            styleSrc:   ["'self'", "'unsafe-inline'", "fonts.googleapis.com"],
            imgSrc:     ["'self'", "data:", "https:", "blob:"],
            connectSrc: ["'self'"],
            fontSrc:    ["'self'", "fonts.gstatic.com"],
            objectSrc:  ["'none'"],
        }
    },
    hsts: { maxAge: 31536000, includeSubDomains: true },
}));

const ALLOWED_ORIGINS = process.env.ALLOWED_ORIGINS
    ? process.env.ALLOWED_ORIGINS.split(',').map(s => s.trim())
    : ['http://localhost:5173', 'http://localhost:3107'];
app.use(cors({
    origin: (origin, cb) => {
        if (!origin || origin === 'null' || ALLOWED_ORIGINS.includes(origin)) return cb(null, true);
        cb(null, false); // Reject without throwing — avoids 500 for cross-origin browser requests
    },
    credentials: true,
}));
// The article translator posts the whole article body as `fallback_content`,
// because for a published bundle or a CDN news item that text is the only copy
// the backend can see. A long-form piece passes the 100 kb default, and the
// parser then rejected it with 413 before the route ever ran — so translation
// worked on short articles and failed on exactly the long ones most worth
// translating. The larger cap is scoped to that one route rather than raised
// globally, which would widen the request-body surface of every endpoint.
const LARGE_BODY_PATHS = [/^\/api\/articles\/[^/]+\/translate$/];
const defaultJsonParser = express.json();
const largeJsonParser = express.json({ limit: '2mb' });
app.use((req, res, next) => {
    const parser = LARGE_BODY_PATHS.some((p) => p.test(req.path)) ? largeJsonParser : defaultJsonParser;
    return parser(req, res, next);
});
app.use(express.urlencoded({ extended: true }));

// Logging
if (NODE_ENV !== 'test') {
    app.use(morgan(NODE_ENV === 'production' ? 'combined' : 'dev'));
}

// Phase 10: Correlation IDs — every request gets a unique UUID
app.use((req, res, next) => {
    req.id = require('uuid').v4();
    res.setHeader('X-Request-Id', req.id);
    next();
});

// Phase 1: Attach Qdrant Collection to requests
app.use((req, res, next) => {
    try {
        req.qdrant = getQdrant();
    } catch (e) {
        // Qdrant not yet initialized — that's OK, it's async
    }
    next();
});

// ── Robustness: global request timeout (30 s) ─────────────────────────────────
// Prevents any hung DB query or external call from freezing a connection forever.
// API requests get 30 s; static file requests are excluded (they respond instantly).
//
// A few routes legitimately outlive that. Image regeneration renders three
// candidates on the GPU, scores each one, and asks a vision model to rank them,
// escalating to a fresh set if none pass — a normal success takes one to three
// minutes. At the shared 30 s it always timed out, and because the work carried
// on and answered afterwards it took the process down with ERR_HTTP_HEADERS_SENT.
// Matched in order; the first hit wins. Patterns rather than exact paths so a
// parameterised route can be listed at all — /api/articles/:id/translate could
// never match a literal key, so it silently ran on the shared 30 s.
//
// Translation calls an LLM and is routinely slower than that: a long article,
// or a batch of UI strings in a language with no cache entries yet, comfortably
// passes 30 s. The timeout answered 503 while the work carried on, so the
// reader saw "Translation unavailable" and the handler then wrote to a response
// that was already sent.
//
// Speech synthesis is slower than it looks: a 3,300-character paragraph measured
// 22.5 s, which left barely seven seconds of headroom under the shared 30 s. A
// timeout there is not a slow paragraph, it is a dead one — the reader gets 503,
// and Read Aloud has only one way to report that.
const LONG_RUNNING_PATHS = [
    [/^\/api\/admin\/regenerate-image$/, 300_000],
    [/^\/api\/articles\/[^/]+\/translate$/, 180_000],
    [/^\/api\/translate-batch$/, 120_000],
    [/^\/api\/tts$/, 120_000],
];

app.use((req, res, next) => {
    if (req.path.startsWith('/backoffice/assets/') || req.path.startsWith('/images/') || req.path.startsWith('/fonts/')) {
        return next(); // static assets — no timeout needed
    }
    const matched = LONG_RUNNING_PATHS.find(([pattern]) => pattern.test(req.path));
    const limit = matched ? matched[1] : 30_000;
    const timeout = setTimeout(() => {
        if (!res.headersSent) {
            console.error(`[Timeout] ${req.method} ${req.path} exceeded ${Math.round(limit / 1000)} s — responding 503`);
            res.status(503).json({ error: 'Request timed out. Please try again.' });
        }
    }, limit);
    res.on('finish', () => clearTimeout(timeout));
    res.on('close',  () => clearTimeout(timeout));
    next();
});

// Part 3 Section 11: CSRF protection — enforce X-CSRF-Token for state-changing requests when session cookie is present
const csrfGuard = require('./lib/csrf-guard');
// The exempt list and the rule live in lib/csrf-guard.js. This middleware is
// mounted at '/api/', and Express hands a mounted handler a `req.path` relative
// to that mount — '/tts', not '/api/tts' — so the list was compared against a
// path that could never match it and every "exempt" endpoint was guarded
// anyway. The guard only bites when a session COOKIE is present, which in
// practice means only signed-in readers on the deployed site, so it answered
// 200 in development and 403 in production.
function requireCsrf(req, res, next) {
    const decision = csrfGuard.csrfDecision({
        method: req.method,
        baseUrl: req.baseUrl,
        path: req.path,
        cookies: _parseCookies(req),
        csrfHeader: req.headers['x-csrf-token'],
        sessionCookieName: _getSessionCookieName(),
    });
    if (decision.allow) return next();
    return res.status(decision.status).json({ error: decision.error });
}
// Apply CSRF check to all /api/ routes; exclude /idp/ and /auth/ (those use redirects / form POSTs)
app.use('/api/', requireCsrf);

// Favicon — redirect /favicon.svg (and /favicon.ico) to the brand logo. It lives
// under /images because that is the only asset prefix the frontend guard below
// (and the Next rewrites) forward to this process.
app.get('/favicon.svg', (_req, res) => res.redirect(301, '/images/brand-logo.png'));
app.get('/favicon.ico', (_req, res) => res.redirect(301, '/images/brand-logo.png'));

// -----------------------------------------------------------------------------
// FRONTEND OWNERSHIP — Next.js is the sole frontend origin.
// The browser only ever talks to the Next.js app; next.config.mjs (dev) and the
// production reverse proxy forward a fixed allow-list of paths to this Express
// process. Everything else is the legacy public/*.html site, now fully
// superseded by Next.js, and must NOT be served from here — not even on a direct
// hit to the Express port. This guard enforces that: only backend paths pass;
// all legacy frontend routes 404.
//
// The prefix list mirrors the next.config.mjs rewrites (/api, /auth, /images,
// /backoffice, /status, /health, /welcome.mp4) plus /internal — the
// server-to-server content-sync endpoint (UAT→prod), which is never proxied
// through the browser. Favicon requests are already handled by the redirects
// above, so they never reach this guard.
// -----------------------------------------------------------------------------
const BACKEND_ONLY_PREFIXES = ['/api', '/auth', '/images', '/backoffice', '/status', '/health', '/internal'];
const BACKEND_ONLY_EXACT = ['/welcome.mp4'];
app.use((req, res, next) => {
    const p = req.path;
    if (BACKEND_ONLY_EXACT.includes(p)) return next();
    if (BACKEND_ONLY_PREFIXES.some((prefix) => p === prefix || p.startsWith(prefix + '/'))) return next();
    return res.status(404).json({
        error: 'Not found. The JubileeVerse frontend is served by the Next.js app; this server exposes the API and backend assets only.',
    });
});

// Static files — NO CACHE (dev mode: all assets served fresh every request)
app.use(express.static(path.join(__dirname, 'public'), {
    etag:         false,
    lastModified: false,
    setHeaders: (res) => {
        res.setHeader('Cache-Control', 'no-cache, no-store, must-revalidate');
        res.setHeader('Pragma', 'no-cache');
        res.setHeader('Expires', '0');
    }
}));

// =============================================================================
// RATE LIMITING (Phase 10)
// =============================================================================

const rateLimit = require('express-rate-limit');

// There is deliberately NO per-IP limiter on /api/auth/login any more.
//
// It used to allow 10 attempts per 15 minutes per IP. Two things made that hurt:
// everyone behind one NAT address (a household, an office, a church hall) shared a
// single budget, and the sign-up screen's entry step now posts to this same route
// with `preview: true`, so sign-up and sign-in drew from that one bucket together.
// Real people were being locked out of a site they had every right to enter.
//
// Removing it was an explicit product decision, made with the exposure stated:
// password guessing against this endpoint is now throttled only by backOfficeLimiter
// below (600/min across all of /api/), which is far too loose to stop credential
// stuffing. The endpoint verifies credentials at the shared Identity Authority, so
// what is unprotected here is the Jubilee ID itself, not merely a JubileeVerse
// account.
//
// If that trade is ever revisited, the cheap fix is not a smaller number — it is
// `skipSuccessfulRequests: true`, so only FAILED attempts count. A person signing in
// correctly then never accumulates anything, while an attacker, who produces nothing
// but failures, still runs into the wall. That keeps the protection and costs
// legitimate users nothing.
// Account deletion re-verifies a password, so it is a credential-guessing surface,
// and it keeps its own limiter. It never shared one with /api/auth/login even when
// that route had a limiter of its own: a common bucket meant a few mistyped sign-ins
// could block a legitimate deletion, and a few deletion attempts could lock someone
// out of signing in. Now that sign-in has no limiter at all, this is the last budget
// standing on a password-checking route, which is another reason not to fold it in.
//
// This endpoint is strictly harder
// to attack than login — it needs a valid session token AND the correct password AND
// the account's own email typed out — so a tighter budget buys little. It costs a
// lot, though: an earlier 5/hour setting locked out any user who mistyped their
// password a few times, and made the contract suite (which needs ~11 attempts)
// impossible to run to completion, so the destructive half never executed and
// "all tests passed" meant nothing.
const accountDeleteLimiter = rateLimit({
    windowMs: 15 * 60 * 1000,
    max: 20,
    standardHeaders: true,
    legacyHeaders: false,
    message: { error: 'Too many account deletion attempts. Please try again in a few minutes.' },
    skip: () => NODE_ENV === 'test',
});
const backOfficeLimiter = rateLimit({
    windowMs: 60_000,
    max: 600,  // back-office tool: small number of admins making many API calls on page load
    standardHeaders: true,
    legacyHeaders: false,
    // Exclude session-check endpoint — rate-limiting it causes redirect loops
    skip: (req) => NODE_ENV === 'test' || req.path === '/auth/me',
});
app.use('/api/', backOfficeLimiter);

// =============================================================================
// METRICS (Phase 10)
// =============================================================================

const _metrics = {
    requests_total: 0,
    requests_by_status: {},
    errors_total: 0,
    latency_buckets: [],
    startedAt: Date.now(),
};
app.use((req, res, next) => {
    const start = Date.now();
    res.on('finish', () => {
        const ms = Date.now() - start;
        _metrics.requests_total++;
        const code = String(res.statusCode);
        _metrics.requests_by_status[code] = (_metrics.requests_by_status[code] || 0) + 1;
        if (res.statusCode >= 500) _metrics.errors_total++;
        if (_metrics.latency_buckets.length >= 1000) _metrics.latency_buckets.shift();
        _metrics.latency_buckets.push(ms);
    });
    next();
});

