// GET /api/metrics — JSON + Prometheus text format (privileged only)
app.get('/api/metrics', async (req, res) => {
    const actor = await requirePrivileged(req, res); if (!actor) return;
    const sorted = [..._metrics.latency_buckets].sort((a, b) => a - b);
    const p = (pct) => sorted.length ? sorted[Math.floor(sorted.length * pct / 100)] || 0 : 0;
    const { rows: [dbStats] } = await pgPool.query(
        `SELECT count(*) FILTER (WHERE status='published') AS published_count,
                count(*) FILTER (WHERE created_at > NOW() - INTERVAL '24 hours') AS created_24h
         FROM jv_content_objects WHERE object_type != 'site'`
    ).catch(() => ({ rows: [{}] }));
    const uptime = Math.floor((Date.now() - _metrics.startedAt) / 1000);
    const memUsage = process.memoryUsage();
    const wantsPrometheus = req.headers.accept && req.headers.accept.includes('text/plain');
    if (wantsPrometheus) {
        res.set('Content-Type', 'text/plain; version=0.0.4');
        return res.send([
            `# HELP jubileeverse_requests_total Total HTTP requests`,
            `# TYPE jubileeverse_requests_total counter`,
            `jubileeverse_requests_total ${_metrics.requests_total}`,
            `# HELP jubileeverse_errors_total Total HTTP 5xx errors`,
            `jubileeverse_errors_total ${_metrics.errors_total}`,
            `# HELP jubileeverse_latency_p95_ms p95 response latency`,
            `jubileeverse_latency_p95_ms ${p(95)}`,
            `# HELP jubileeverse_uptime_seconds Server uptime`,
            `jubileeverse_uptime_seconds ${uptime}`,
            `jubileeverse_content_published ${dbStats?.published_count || 0}`,
            `jubileeverse_content_created_24h ${dbStats?.created_24h || 0}`,
            `jubileeverse_memory_rss_bytes ${memUsage.rss}`,
        ].join('\n'));
    }
    res.json({
        uptime_seconds: uptime,
        requests: { total: _metrics.requests_total, by_status: _metrics.requests_by_status },
        errors_total: _metrics.errors_total,
        latency: { p50: p(50), p95: p(95), p99: p(99) },
        memory: { rss: memUsage.rss, heap_used: memUsage.heapUsed, heap_total: memUsage.heapTotal },
        content: { published_count: dbStats?.published_count || 0, created_24h: dbStats?.created_24h || 0 },
    });
});

