function hasPermission(role, permission) {
    return Boolean((PERMISSIONS[permission] || []).includes(role));
}

/**
 * maskPromptExtension — strip sensitive prompt instructions from extension_data
 * for users who do not have prompt:manage (admin-only).
 * Applies only to objects where object_type === 'prompt_recipe'.
 */
function maskPromptExtension(obj, role) {
    if (!obj || obj.object_type !== 'prompt_recipe') return obj;
    if (hasPermission(role, 'prompt:manage')) return obj;
    const { system_prompt, user_template, output_schema, ...safe } = obj.extension_data || {};
    return { ...obj, extension_data: safe };
}

// ── Phase 5: WebSocket broadcast (assigned at server start — forward ref) ────────────────────
let broadcastToUser = () => {};  // replaced when WebSocket server is created

// ── Phase 5: Notification helper ─────────────────────────────────────────────────────────────
async function createNotification(pool, { recipient_id, type, title, body, object_type, object_id }) {
    if (!recipient_id) return;
    try {
        const { rows } = await pool.query(
            `INSERT INTO jv_notifications (recipient_id, type, title, body, object_type, object_id)
             VALUES ($1,$2,$3,$4,$5,$6) RETURNING *`,
            [recipient_id, type, title, body || null, object_type || null, object_id || null]
        );
        broadcastToUser(recipient_id, { type: 'notification', notification: rows[0] });
        sendEmail(recipient_id, title, `<p>${body || ''}</p><p><a href="/backoffice/">Open Back Office</a></p>`);
    } catch (e) { console.error('[createNotification]', e.message); }
}

// ── Phase 5: RBAC helpers ─────────────────────────────────────────────────────────────────────
function hasRolePermission(role, permission) {
    return !!(ROLE_PERMISSIONS_MAP[role]?.has(permission));
}
async function hasTaxonomyPermission(userEmail, permission, taxonomyNodeId) {
    const { rows: node } = await pgPool.query(
        `SELECT materialized_path FROM categories WHERE id = $1`, [taxonomyNodeId]
    );
    if (!node.length) return false;
    const ancestorIds = (node[0].materialized_path || '').split('/').filter(Boolean).map(Number);
    const ids = [...ancestorIds, taxonomyNodeId];
    const { rows } = await pgPool.query(
        `SELECT 1 FROM jv_user_taxonomy_permissions
          WHERE user_email=$1 AND taxonomy_node_id=ANY($2) AND permission=$3 LIMIT 1`,
        [userEmail, ids, permission]
    );
    return rows.length > 0;
}
async function checkPermissionAsync(actor, permission, context = {}) {
    if (hasRolePermission(actor.role, permission)) return true;
    if (context.taxonomyNodeId) {
        return hasTaxonomyPermission(actor.email || actor.sub, permission, context.taxonomyNodeId);
    }
    return false;
}
// Factory: requireRole(req, res, 'publisher', 'admin') — returns payload or null
async function requireRole(req, res, ...roles) {
    // Cookie-based session takes priority (Sections 10-11)
    const cookies = _parseCookies(req);
    if (cookies[_getSessionCookieName()]) {
        const sessionPayload = await requireSession(req, res);
        if (!sessionPayload) return null;
        if (!roles.includes(sessionPayload.role)) {
            res.status(403).json({ error: `Required role: ${roles.join(' or ')}` }); return null;
        }
        return sessionPayload;
    }
    // Bearer token fallback
    const raw = (req.headers.authorization || '').replace('Bearer ', '').trim();
    if (!raw) { res.status(401).json({ error: 'Authorization token required' }); return null; }
    const payload = authVerifyJWT(raw);
    if (!payload) { res.status(401).json({ error: 'Invalid or expired token' }); return null; }
    if (!roles.includes(payload.role)) {
        res.status(403).json({ error: `Required role: ${roles.join(' or ')}` }); return null;
    }
    // _checkAccountStatus is async — without the await this tests a Promise, which is
    // always truthy, so a disabled/locked/session-revoked admin sailed through every
    // /api/admin/* route on the Bearer path (and the rejection then wrote a second
    // response, throwing ERR_HTTP_HEADERS_SENT). requirePrivileged has always awaited it.
    if (!await _checkAccountStatus(payload, res)) return null;
    return payload;
}

// ── Phase 5: Workflow state machine ───────────────────────────────────────────────────────────
const WORKFLOW_TRANSITIONS = {
    'draft:review':        { roles: ['editor','admin','site_owner'], validate: () => null },
    'review:draft':        {
        roles: ['reviewer','admin','site_owner'],
        validate: (body) => body.reason?.trim() ? null : 'reason is required when returning to draft',
    },
    'review:approved':     { roles: ['reviewer','admin','site_owner'], validate: () => null },
    'approved:scheduled':  {
        roles: ['publisher','admin','site_owner'],
        validate: (body) => {
            if (!body.scheduled_at) return 'scheduled_at is required';
            if (new Date(body.scheduled_at) <= new Date()) return 'scheduled_at must be in the future';
            return null;
        },
    },
    'approved:published':  { roles: ['publisher','admin','site_owner'], validate: () => null },
    'scheduled:published': { roles: ['publisher','admin','site_owner','system'], validate: () => null },
    'published:archived':  { roles: ['publisher','admin','site_owner'], validate: () => null },
    'archived:draft':      { roles: ['editor','admin','site_owner'], validate: () => null },
};

// DELETE /api/current-events/:id — Reviewer-only: remove an article from the portal
app.delete('/api/current-events/:id', async (req, res) => {
    const payload = requireReviewer(req, res);
    if (!payload) return;

    const articleId = parseInt(req.params.id, 10);
    if (!articleId || isNaN(articleId)) return res.status(400).json({ error: 'Invalid article ID' });

    try {
        // Fetch article before deletion for audit log
        const before = await pgPool.query(`SELECT id, headline, full_article FROM current_events WHERE id = $1`, [articleId]);
        if (!before.rowCount) return res.status(404).json({ error: 'Article not found' });
        const article = before.rows[0];

        await pgPool.query(`DELETE FROM current_events WHERE id = $1`, [articleId]);

        // Audit log
        logReviewerActivity({
            email: payload.email,
            action: 'delete',
            summary: `Article Was Deleted by Reviewer`,
            articleId: article.id,
            articleHeadline: article.headline,
            beforeTitle: article.headline,
            beforeContent: article.full_article,
        });

        // Regenerate today's portal layout so the deleted article is no longer shown
        const dateStr = getPstDateString();
        try {
            await generatePortalLayout(dateStr);
            console.log(`[ReviewerDelete] Article ${articleId} deleted; portal layout regenerated for ${dateStr}.`);
        } catch (e) {
            console.error('[ReviewerDelete] Portal regen error (non-fatal):', e.message);
        }

        res.json({ success: true, deleted: { id: article.id, headline: article.headline } });
    } catch (err) {
        console.error('[ReviewerDelete] Error:', err.message);
        res.status(500).json({ error: 'Failed to delete article', message: err.message });
    }
});

// POST /api/admin/regenerate-image — Admin-only: re-render a published article's
// hero image through the news pipeline's renderer, screen it, and republish it.
//
// For the CDN-published articles the site actually serves — daily news and the
// five category bundles — rather than the PostgreSQL rows the reviewer routes
// below cover. The body names an article; prompts are rebuilt server-side from
// that article's own title, summary, category and text, so this cannot be used
// to render arbitrary prompts on the GPU.
app.post('/api/admin/regenerate-image', async (req, res) => {
    const actor = await requireRole(req, res, 'admin');
    if (!actor) return;

    const { kind, slug, categorySlug, date } = req.body || {};
    const ImageRegen = require('./lib/image-regen');

    try {
        const result = await ImageRegen.regenerateArticleImage({ kind, slug, categorySlug, date });
        console.log(`[AdminRegen] ${actor.email} regenerated ${kind}/${slug}`);
        // The work outlives the connection often enough to matter: the client
        // may have given up, or a proxy dropped it. The image is published
        // either way — say so in the log and let the response go.
        if (res.headersSent) return;
        res.json({ success: true, ...result });
    } catch (err) {
        // A regeneration failure is routine — a busy GPU, a safety hold, an
        // article that has since been unpublished. Report it as such rather
        // than as a server fault, and never leak a stack to the browser.
        const status = err.status || 500;
        if (status >= 500) console.error('[AdminRegen] Error:', err.message);
        // Answering twice throws inside this catch, where nothing can catch it,
        // and an unhandled rejection ends the process. Never respond blind.
        if (res.headersSent) return;
        res.status(status).json({ error: err.kind || 'error', message: err.message });
    }
});

// POST /api/current-events/:id/regenerate-image — Reviewer-only: regenerate article image via DALL-E 3
app.post('/api/current-events/:id/regenerate-image', async (req, res) => {
    const payload = requireReviewer(req, res);
    if (!payload) return;

    const articleId = parseInt(req.params.id, 10);
    if (!articleId) return res.status(400).json({ error: 'Invalid article id' });

    try {
        const result = await pgPool.query(
            `SELECT id, headline, excerpt, full_article, topic FROM current_events WHERE id = $1`,
            [articleId]
        );
        if (!result.rows.length) return res.status(404).json({ error: 'Article not found' });

        const article  = result.rows[0];
        const content  = [article.headline, article.excerpt, article.full_article].filter(Boolean).join('\n\n');
        const prompt   = await buildICPromptForArticle(article.headline, content);
        const jobId    = require('crypto').randomUUID();
        const topic    = (article.topic || 'general').toLowerCase().replace(/[^a-z0-9]+/g, '-');
        const destPath = require('path').join(__dirname, 'public', 'images', 'jubileeverse.com', topic, `${articleId}.jpg`);
        const dbPath   = `/images/jubileeverse.com/${topic}/${articleId}.jpg`;

        _icJobTracker.set(jobId, { articleId, type: 'current-event', dbPath, destPath, pool: 'pgPool', status: 'pending' });
        runICJob(jobId, prompt); // fire-and-forget (uses IC GPU, falls back to DALL-E 3)

        console.log(`[ReviewerRegen] IC job ${jobId} started for current-event ${articleId}`);
        res.json({ success: true, jobId, articleId, queued: true, position: 0 });
    } catch (err) {
        console.error('[ReviewerRegen] Error:', err.message);
        res.status(500).json({ error: 'Image regeneration failed', message: err.message });
    }
});

// PATCH /api/articles/:id — Reviewer-only: update Jubilee Inspire article title and/or content
app.patch('/api/articles/:id', async (req, res) => {
    const payload = requireReviewer(req, res);
    if (!payload) return;

    const articleId = parseInt(req.params.id, 10);
    if (!articleId) return res.status(400).json({ error: 'Invalid article id' });

    const { title, content } = req.body || {};
    if (!title && !content) return res.status(400).json({ error: 'title or content required' });

    try {
        const before = await inspirePool.query(
            `SELECT id, title, content FROM articles WHERE id = $1`, [articleId]
        );
        if (!before.rows.length) return res.status(404).json({ error: 'Article not found' });
        const orig = before.rows[0];

        const updates = [];
        const params = [];
        if (title !== undefined) {
            updates.push(`title = $${params.length + 1}`);
            params.push(title);
            // Auto-update slug when title changes
            const newSlug = generateSlug(title);
            updates.push(`slug = $${params.length + 1}`);
            params.push(newSlug);
        }
        if (content !== undefined) { updates.push(`content = $${params.length + 1}`); params.push(content); }
        params.push(articleId);
        await inspirePool.query(`UPDATE articles SET ${updates.join(', ')} WHERE id = $${params.length}`, params);

        if (title !== undefined && title !== orig.title) {
            logReviewerActivity({ email: payload.email, action: 'edit_title', summary: 'Reviewer edited Inspire article title', articleId, articleHeadline: title, beforeTitle: orig.title, afterTitle: title });
        }
        if (content !== undefined && content !== orig.content) {
            logReviewerActivity({ email: payload.email, action: 'edit_content', summary: 'Reviewer edited Inspire article content', articleId, articleHeadline: title || orig.title, beforeContent: (orig.content || '').slice(0, 500), afterContent: (content || '').slice(0, 500) });
        }
        res.json({ success: true, articleId });
    } catch (err) {
        console.error('[ReviewerPatchInspire] Error:', err.message);
        res.status(500).json({ error: 'Failed to update article', message: err.message });
    }
});

// POST /api/articles/:id/regenerate-image — Reviewer-only: regenerate a Jubilee Inspire article image via DALL-E 3
app.post('/api/articles/:id/regenerate-image', async (req, res) => {
    const payload = requireReviewer(req, res);
    if (!payload) return;

    const articleId = parseInt(req.params.id, 10);
    if (!articleId) return res.status(400).json({ error: 'Invalid article id' });

    try {
        const result = await inspirePool.query(
            `SELECT a.id, a.title, a.content, a.hero_image_path, c.name AS category_name
             FROM articles a LEFT JOIN categories c ON a.category_id = c.id
             WHERE a.id = $1`,
            [articleId]
        );
        if (!result.rows.length) return res.status(404).json({ error: 'Article not found' });

        const article  = result.rows[0];
        const catSlug  = (article.category_name || 'general').toLowerCase().replace(/[^a-z0-9]+/g, '-');
        const destPath = require('path').join(__dirname, 'public', 'images', 'jubileeinspire.com', catSlug, `${articleId}.jpg`);
        const dbPath   = `/images/jubileeinspire.com/${catSlug}/${articleId}.jpg`;
        const prompt   = await buildICPromptForArticle(article.title, article.content);
        const jobId    = require('crypto').randomUUID();

        _icJobTracker.set(jobId, { articleId, type: 'inspire', dbPath, destPath, pool: 'inspirePool', status: 'pending' });
        runICJob(jobId, prompt); // fire-and-forget (uses IC GPU, falls back to DALL-E 3)

        console.log(`[ReviewerRegenInspire] IC job ${jobId} started for article ${articleId}`);
        res.json({ success: true, jobId, articleId, queued: true, position: 0 });
    } catch (err) {
        console.error('[ReviewerRegenInspire] Error:', err.message);
        res.status(500).json({ error: 'Failed to start image regeneration', message: err.message });
    }
});

// POST /api/jv-articles/batch-generate — Reviewer-only: generate images for articles missing them in a taxonomy node
app.post('/api/jv-articles/batch-generate', async (req, res) => {
    const actor = await requirePrivileged(req, res); if (!actor) return;
    if (!hasPermission(actor.role, 'image:generate')) return res.status(403).json({ error: 'Forbidden' });

    const { taxonomy_node_id, limit = 20 } = req.body;
    if (!taxonomy_node_id) return res.status(400).json({ error: 'taxonomy_node_id required' });

    try {
        // Collect descendant node IDs (recursive)
        const nodeResult = await pgPool.query(
            `WITH RECURSIVE subtree AS (
                 SELECT id FROM jv_taxonomy WHERE id = $1
                 UNION ALL
                 SELECT t.id FROM jv_taxonomy t INNER JOIN subtree s ON t.parent_id = s.id
             ) SELECT id FROM subtree`,
            [taxonomy_node_id]
        );
        const nodeIds = nodeResult.rows.map(r => r.id);

        // Find articles without hero_image_path in this taxonomy (up to limit)
        const { rows: articles } = await pgPool.query(
            `SELECT DISTINCT o.id, o.title
             FROM jv_content_objects o
             JOIN jv_content_taxonomy_map ctm ON ctm.uuid_object_id = o.id
             WHERE ctm.taxonomy_node_id = ANY($1)
               AND o.object_type IN ('article','blog_post','page','news_item','devotional')
               AND (o.extension_data->>'hero_image_path' IS NULL OR o.extension_data->>'hero_image_path' = '')
             ORDER BY o.title
             LIMIT $2`,
            [nodeIds, parseInt(limit, 10)]
        );

        const jobs = [];
        for (const article of articles) {
            const tag      = `[BatchGenJV:${article.id.slice(0, 8)}]`;
            const slug     = article.id.replace(/-/g, '').slice(0, 12);
            const filename = `jv-${slug}.jpg`;
            const destPath = require('path').join(__dirname, 'public', 'images', 'jubileeinspire.com', 'encouragement', filename);
            const dbPath   = `/images/jubileeinspire.com/encouragement/${filename}`;

            // Fetch content body + primary taxonomy node name for this article
            let bodyText = '', categoryName = '';
            try {
                const detail = await pgPool.query(
                    `SELECT o.summary, o.extension_data,
                            (SELECT t.name FROM jv_content_taxonomy_map ctm
                             JOIN jv_taxonomy t ON t.id = ctm.taxonomy_node_id
                             WHERE ctm.uuid_object_id = o.id LIMIT 1) AS taxonomy_node_name
                     FROM jv_content_objects o WHERE o.id = $1`,
                    [article.id]
                );
                if (detail.rows.length) {
                    const row = detail.rows[0];
                    const ext = row.extension_data || {};
                    const raw = (ext.body_html || ext.body_markdown || '').replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim();
                    bodyText     = [row.summary, raw].filter(Boolean).join('\n\n').slice(0, 2000);
                    categoryName = row.taxonomy_node_name || '';
                }
            } catch (detailErr) {
                console.warn(`${tag} Could not fetch content detail: ${detailErr.message}`);
            }

            const prompt = await buildJVContentImagePrompt(article.title, bodyText, categoryName, tag);
            const jobId  = require('crypto').randomUUID();

            _icJobTracker.set(jobId, {
                articleId: article.id, type: 'jv_content', pool: 'jv_content',
                dbPath, destPath, status: 'pending',
                meta: { title: article.title, category: categoryName },
            });
            runICJob(jobId, prompt);
            jobs.push({ articleId: article.id, title: article.title, jobId, imagePath: dbPath });
            console.log(`${tag} Queued IC job ${jobId} — category: "${categoryName}", prompt: ${prompt.slice(0, 80)}…`);
        }

        res.json({ success: true, queued: jobs.length, jobs });
    } catch (err) {
        console.error('[BatchGenJV] Error:', err.message);
        res.status(500).json({ error: 'Batch generation failed', message: err.message });
    }
});

// POST /api/jv-articles/:id/regenerate-image — Reviewer-only: regenerate hero image for a jv_content_objects article
// Routes to the new MidJourney image generation pipeline (same as /api/v1/images/generate) to ensure
// proper negative prompts and no text rendering. This replaces the old IC job system.
app.post('/api/jv-articles/:id/regenerate-image', async (req, res) => {
    const actor = await requirePrivileged(req, res); if (!actor) return;
    if (!hasPermission(actor.role, 'image:generate')) return res.status(403).json({ error: 'Forbidden' });

    const articleId = req.params.id; // UUID
    const tag = `[JVRegen:${articleId.slice(0, 8)}]`;

    try {
        // Fetch full article content + primary taxonomy node name in one query
        const result = await pgPool.query(
            `SELECT o.id, o.title, o.summary, o.object_type, o.extension_data,
                    (SELECT t.name FROM jv_content_taxonomy_map ctm
                     JOIN jv_taxonomy t ON t.id = ctm.taxonomy_node_id
                     WHERE ctm.uuid_object_id = o.id LIMIT 1) AS taxonomy_node_name
             FROM jv_content_objects o
             WHERE o.id = $1`,
            [articleId]
        );
        if (!result.rows.length) return res.status(404).json({ error: 'Article not found' });

        const article      = result.rows[0];
        const ext          = article.extension_data || {};
        const rawBody      = (ext.body_html || ext.body_markdown || '').replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim();
        const bodyText     = [article.summary, rawBody].filter(Boolean).join('\n\n').slice(0, 2500);
        const categoryName = article.taxonomy_node_name || '';

        console.log(`${tag} Starting MidJourney regen — title: "${(article.title || '').slice(0, 60)}", category: "${categoryName}", content: ${bodyText.length} chars`);

        // Use new MidJourney pipeline with proper anti-text constraints
        // Stage 1: Analyze article for visual dimensions
        let analysis;
        try {
            analysis = await _analyzeArticleForVisuals(article.title, bodyText, categoryName);
        } catch (err) {
            console.warn(`${tag} LLM analysis failed: ${err.message}, using fallback`);
            analysis = null;  // Will use simpler prompt generation
        }

        // Stage 2: Build cinematic prompt with NO TEXT
        const prompt = await _buildMidjourneyPrompt(
            analysis,
            article.title,
            categoryName,
            global._imageGenerationHistory?.recentPrompts || [],
            global._imageGenerationHistory?.demographicHistory || []
        );
        const negativePrompt = _buildMidjourneyNegativePrompt();

        const jobId = require('crypto').randomUUID();

        // Insert job record (compatible with new pipeline)
        const { rows: [job] } = await pgPool.query(
            `INSERT INTO image_generation_jobs
               (id, content_object_id, site_id, prompt_context, style_constraints, aspect_ratio,
                gpu_job_status, image_status, created_at, updated_at)
             VALUES ($1, $2, $3, $4, $5, $6, 'submitted', 'generating', NOW(), NOW())
             RETURNING *`,
            [jobId, articleId, null, prompt,
             JSON.stringify(analysis || {}), '16:9']
        );

        console.log(`${tag} MidJourney job created: ${jobId} with proper negative prompts`);

        // Submit to Jubilee MidJourney API asynchronously (same pattern as /api/v1/images/generate)
        (async () => {
            try {
                // MOCK MODE: Skip IC API and just create a test image
                if (process.env.IMAGE_REGEN_MOCK === 'true') {
                    console.log(`${tag} ⚠️  MOCK MODE: Skipping IC API call`);

                    // Simulate 2-second delay
                    console.log(`${tag} Waiting 2 seconds...`);
                    await new Promise(resolve => setTimeout(resolve, 2000));
                    console.log(`${tag} Delay complete`);

                    // Copy a test image
                    const slug = articleId.replace(/-/g, '').slice(0, 12);
                    const filename = `jv-regenerated-${slug}-${Date.now()}.jpg`;
                    const publicPath = `/images/generated/${filename}`;
                    const destPath = path.join(__dirname, 'public', 'images', 'generated', filename);

                    console.log(`${tag} Creating image: ${destPath}`);

                    // Ensure directory exists
                    const imagesDir = path.dirname(destPath);
                    if (!fs.existsSync(imagesDir)) {
                        console.log(`${tag} Creating images directory: ${imagesDir}`);
                        fs.mkdirSync(imagesDir, { recursive: true });
                    }

                    // Copy test image
                    const templateImage = path.join(__dirname, 'public', 'images', 'generated', 'test-1.jpg');
                    console.log(`${tag} Template image: ${templateImage}`);
                    console.log(`${tag} Template exists: ${fs.existsSync(templateImage)}`);

                    if (fs.existsSync(templateImage)) {
                        fs.copyFileSync(templateImage, destPath);
                        console.log(`${tag} ✓ Image file copied`);
                    } else {
                        // Fallback: create placeholder
                        fs.writeFileSync(destPath, Buffer.from([0xff, 0xd8, 0xff, 0xe0]));
                        console.log(`${tag} ✓ Placeholder image created`);
                    }

                    // Verify file was created
                    const fileExists = fs.existsSync(destPath);
                    const fileSize = fileExists ? fs.statSync(destPath).size : 0;
                    console.log(`${tag} Image file created: ${fileExists}, size: ${fileSize} bytes`);

                    // Update job record
                    console.log(`${tag} Updating image_generation_jobs...`);
                    const jobResult = await pgPool.query(
                        `UPDATE image_generation_jobs SET
                           gpu_job_status='completed', image_url=$2,
                           image_status='in_review', updated_at=NOW()
                         WHERE id=$1
                         RETURNING id, gpu_job_status, image_url`,
                        [jobId, publicPath]
                    );
                    console.log(`${tag} Job updated:`, jobResult.rows[0]);

                    // Also update the article's hero_image_path to the new image (this is what the UI displays)
                    console.log(`${tag} Updating article hero_image_path...`);
                    const articleResult = await pgPool.query(
                        `UPDATE jv_content_objects SET
                           extension_data = jsonb_set(extension_data, '{hero_image_path}', $2),
                           updated_at=NOW()
                         WHERE id=$1
                         RETURNING id, extension_data->>'hero_image_path' as hero_image_path`,
                        [articleId, JSON.stringify(publicPath)]
                    );
                    console.log(`${tag} Article updated:`, articleResult.rows[0]);

                    console.log(`${tag} ✓ Mock regeneration complete: ${publicPath}`);
                    logAuditEvent(pgPool, {
                        event_type: 'image.generation_completed',
                        actor_id: actor.email,
                        target_type: 'jv_content_objects',
                        target_id: articleId,
                        details: { job_id: jobId, image_path: publicPath, method: 'jv-article-regenerate-mock' },
                        ip_address: req.ip,
                        user_agent: req.get('user-agent')
                    });
                    return;
                }

                const mjResult = await callMidjourneyGenerate(prompt, negativePrompt);
                console.log(`${tag} MidJourney response received: job_id=${mjResult?.job_id}`);

                if (!mjResult?.job_id) {
                    throw new Error(`Invalid MidJourney response: missing job_id`);
                }

                // Poll job status and download image
                let jobStatus;
                let attempts = 0;
                const maxAttempts = 60;

                while (attempts < maxAttempts) {
                    try {
                        jobStatus = await checkICJobStatus(mjResult.job_id);

                        if (jobStatus?.status === 'completed' && jobStatus?.output_urls?.length > 0) {
                            const imageUrl = jobStatus.output_urls[0];
                            const slug = articleId.replace(/-/g, '').slice(0, 12);
                            const filename = `jv-regenerated-${slug}-${Date.now()}.jpg`;
                            const publicPath = `/images/generated/${filename}`;
                            const destPath = require('path').join(__dirname, 'public', 'images', 'generated', filename);

                            console.log(`${tag} Image ready, downloading...`);
                            await downloadICImage(imageUrl, destPath);

                            // Update job record with image path
                            await pgPool.query(
                                `UPDATE image_generation_jobs SET
                                   gpu_job_status='completed', gpu_response=$2, image_url=$3,
                                   image_status='in_review', updated_at=NOW()
                                 WHERE id=$1`,
                                [jobId, JSON.stringify(jobStatus), publicPath]
                            );

                            // Also update the article's hero_image_path to the new image (this is what the UI displays)
                            await pgPool.query(
                                `UPDATE jv_content_objects SET
                                   extension_data = jsonb_set(extension_data, '{hero_image_path}', $2),
                                   updated_at=NOW()
                                 WHERE id=$1`,
                                [articleId, JSON.stringify(publicPath)]
                            );

                            console.log(`${tag} ✓ Regeneration complete: ${publicPath}`);
                            logAuditEvent(pgPool, {
                                event_type: 'image.generation_completed',
                                actor_id: actor.email,
                                target_type: 'jv_content_objects',
                                target_id: articleId,
                                details: { job_id: jobId, image_path: publicPath, method: 'jv-article-regenerate' },
                                ip_address: req.ip,
                                user_agent: req.get('user-agent')
                            });
                            return;
                        } else if (jobStatus?.status === 'failed' || jobStatus?.status === 'error') {
                            throw new Error(`MidJourney job failed: ${jobStatus?.status}`);
                        }
                    } catch (statusErr) {
                        console.warn(`${tag} Status check error (attempt ${attempts + 1}): ${statusErr.message}`);
                    }

                    attempts++;
                    if (attempts < maxAttempts) {
                        await new Promise(resolve => setTimeout(resolve, 5000));
                    }
                }

                throw new Error(`MidJourney job did not complete within 5 minutes`);

            } catch (mjErr) {
                console.warn(`${tag} ✗ MidJourney regeneration failed: ${mjErr.message}`);
                await pgPool.query(
                    `UPDATE image_generation_jobs SET gpu_job_status='failed', image_status='pending', updated_at=NOW() WHERE id=$1`,
                    [jobId]
                );
                logAuditEvent(pgPool, {
                    event_type: 'image.generation_failed',
                    actor_id: actor.email,
                    target_type: 'jv_content_objects',
                    target_id: articleId,
                    details: { job_id: jobId, error: mjErr.message },
                    ip_address: req.ip,
                    user_agent: req.get('user-agent')
                });
            }
        })();

        // Return jobId so client can poll for completion
        // imagePath will be updated once mock/IC generation completes
        res.json({ success: true, jobId, articleId, queued: true });
    } catch (err) {
        console.error(`${tag} Error: ${err.message}`, err.stack?.split('\n').slice(0, 3).join(' | '));
        res.status(500).json({ error: 'Failed to start image regeneration', message: err.message });
    }
});

