// POST /api/admin/retroactive-approval-scan — Reviewer-only: scan existing articles and reject non-compliant ones
// Query param: ?limit=50 (max 200 per run to avoid rate limits)
app.post('/api/admin/retroactive-approval-scan', async (req, res) => {
    const payload = requireReviewer(req, res);
    if (!payload) return;

    const limit = Math.min(parseInt(req.query.limit) || 50, 200);
    try {
        // Fetch articles not yet fully AI-reviewed
        // (approved = TRUE and approval_reason is null or old scan reason)
        const rows = await pgPool.query(`
            SELECT id, headline, excerpt, full_article, image_url, cached_image_path
            FROM current_events
            WHERE approved = TRUE
              AND (approval_reason IS NULL OR approval_reason = 'Approved by retroactive scan')
            ORDER BY id DESC
            LIMIT $1
        `, [limit]);

        if (!rows.rowCount) {
            return res.json({ success: true, scanned: 0, rejected: 0, message: 'All existing articles already scanned.' });
        }

        let scanned = 0, rejected = 0;
        const rejectLog = [];

        for (const article of rows.rows) {
            // Layer 1: Pattern-based refusal check (free, fast)
            if (isRefusalContent(article.full_article)) {
                await pgPool.query(
                    `UPDATE current_events SET approved = FALSE, approval_reason = 'Refusal content detected' WHERE id = $1`,
                    [article.id]
                );
                logReviewerActivity({
                    email: payload.email,
                    action: 'auto_reject',
                    summary: 'Existing article rejected — refusal content detected',
                    articleId: article.id,
                    articleHeadline: article.headline,
                    beforeTitle: article.headline,
                    afterTitle: 'REJECTED: Refusal content detected',
                });
                rejected++;
                rejectLog.push({ id: article.id, headline: article.headline, reason: 'Refusal content detected' });
                scanned++;
                await new Promise(r => setTimeout(r, 100));
                continue;
            }

            // Layer 2: AI full-text review of generated article
            const fullReview = await reviewGeneratedArticle(article.headline || '', article.full_article || '');
            scanned++;

            // Layer 3: Faith-values check on headline + image (existing ingest check)
            const imageUrl = article.cached_image_path
                ? `${req.protocol}://${req.get('host')}${article.cached_image_path}`
                : article.image_url || null;
            const faithCheck = await approveArticleForPublication(
                article.headline || '', article.excerpt || '', imageUrl
            );

            const finalApproved = fullReview.approved && faithCheck.approved;
            const finalReason   = !fullReview.approved ? fullReview.reason : (!faithCheck.approved ? faithCheck.reason : (fullReview.reason || 'AI reviewed'));

            if (!finalApproved) {
                await pgPool.query(
                    `UPDATE current_events SET approved = FALSE, approval_reason = $1 WHERE id = $2`,
                    [finalReason, article.id]
                );
                logReviewerActivity({
                    email: payload.email,
                    action: 'auto_reject',
                    summary: `Existing article rejected by retroactive scan`,
                    articleId: article.id,
                    articleHeadline: article.headline,
                    beforeTitle: article.headline,
                    afterTitle: `REJECTED: ${finalReason}`,
                });
                rejected++;
                rejectLog.push({ id: article.id, headline: article.headline, reason: finalReason });
                console.log(`[RetroScan] REJECTED id=${article.id}: "${(article.headline || '').slice(0, 60)}" — ${finalReason}`);
            } else {
                await pgPool.query(
                    `UPDATE current_events SET approval_reason = $1 WHERE id = $2`,
                    ['AI reviewed and approved', article.id]
                );
            }

            // Delay between articles to stay within API rate limits
            await new Promise(r => setTimeout(r, 400));
        }

        // If any articles were rejected, regenerate today's portal layout to remove them
        if (rejected > 0) {
            try { await generatePortalLayout(getPstDateString()); } catch (_) {}
        }

        res.json({ success: true, scanned, rejected, rejectedArticles: rejectLog });
    } catch (err) {
        console.error('[RetroScan] Error:', err.message);
        res.status(500).json({ error: 'Scan failed', message: err.message });
    }
});

