// INSPIRE FAMILY PERSONA ROUTER
// =============================================================================
// POST /api/persona/invoke — call any Inspire Family persona with a prompt
// POST /api/persona/status — list persona readiness and assigned models
// =============================================================================

const PersonaRouter = require('./lib/persona-router');
const _personaRouter = new PersonaRouter();

// GET /api/persona/status — returns readiness of all personas
app.get('/api/persona/status', async (req, res) => {
    res.json(_personaRouter.status());
});

// POST /api/persona/invoke — invoke a named persona with a user prompt
// Body: { persona: 'jubilee'|'melody'|..., prompt: '...', tier?, maxTokens? }
//       OR { recipe_slug: '...', object_type: '...', ... } → delegates to GenerationService
app.post('/api/persona/invoke', async (req, res) => {
    const { persona, prompt, tier, maxTokens, recipe_slug } = req.body || {};
    // Phase 6: if recipe_slug present, delegate to GenerationService
    if (recipe_slug) {
        const actor = await requirePrivileged(req, res); if (!actor) return;
        try {
            const { object_type, taxonomy_node_id, language, author_id, source_object_id,
                    custom_instructions, confirmed } = req.body;
            const { contentObject, logId, safetyFlags } = await _generationService.generateContent({
                recipeSlug: recipe_slug, objectType: object_type || 'article',
                taxonomyNodeId: taxonomy_node_id || null, language: language || 'en-US',
                authorId: author_id || null, sourceObjectId: source_object_id || null,
                customInstructions: custom_instructions || null, confirmed: !!confirmed,
                actorId: actor.email, req,
            });
            // Return in legacy-compatible shape
            return res.status(201).json({
                persona: recipe_slug, tier: 'generation', model: 'generation-service',
                text: contentObject.extension_data?.body_html ||
                      contentObject.extension_data?.prayer_text ||
                      contentObject.extension_data?.script_text || '',
                content_object: contentObject,
                log_id: logId, safety_flags: safetyFlags,
            });
        } catch (err) {
            const status = err.statusCode || 500;
            return res.status(status).json({ error: err.message });
        }
    }
    if (!persona || !prompt) {
        return res.status(400).json({ error: 'persona and prompt are required' });
    }
    try {
        const result = await _personaRouter.invoke(persona, prompt, { tier, maxTokens });
        res.json(result);
    } catch (err) {
        console.error(`[PersonaRouter] ${persona} error:`, err.message);
        res.status(500).json({ error: err.message });
    }
});

// =============================================================================
// AI GENERATION ENGINE (Phase 6)
// =============================================================================

// POST /api/generate — generate AI content from a recipe
// Body: { recipe_slug, object_type, taxonomy_node_id?, language?, author_id?,
//         source_object_id?, custom_instructions?, confirmed?, override_reason? }
app.post('/api/generate', async (req, res) => {
    const actor = await requirePrivileged(req, res); if (!actor) return;
    const { recipe_slug, object_type, taxonomy_node_id, language,
            author_id, source_object_id, custom_instructions, confirmed,
            override_reason } = req.body || {};
    if (!recipe_slug || !object_type) {
        return res.status(400).json({ error: 'recipe_slug and object_type are required' });
    }
    const canCreate = await checkPermissionAsync(actor, 'create_content', { taxonomyNodeId: taxonomy_node_id });
    if (!canCreate) return res.status(403).json({ error: 'Insufficient permission: create_content' });
    // Author override audit: fire-and-forget if author differs from node's preferred_authors
    if (author_id && taxonomy_node_id) {
        pgPool.query(`SELECT config FROM jv_taxonomy WHERE id=$1`, [taxonomy_node_id])
            .then(({ rows: [node] }) => {
                const preferred = node?.config?.preferred_authors || [];
                if (preferred.length > 0 && !preferred.includes(author_id)) {
                    logAuditEvent(pgPool, {
                        event_type: 'author.override', actor_id: actor.email,
                        target_type: 'jv_content_objects', target_id: author_id,
                        details: { taxonomy_node_id, override_reason: override_reason || null,
                                   preferred_authors: preferred },
                        ip_address: req.ip, user_agent: req.get('user-agent'),
                    });
                }
            }).catch(() => {});
    }
    try {
        const { contentObject, logId, safetyFlags } = await _generationService.generateContent({
            recipeSlug: recipe_slug, objectType: object_type,
            taxonomyNodeId: taxonomy_node_id || null, language: language || 'en-US',
            authorId: author_id || null, sourceObjectId: source_object_id || null,
            customInstructions: custom_instructions || null, confirmed: !!confirmed,
            actorId: actor.email, req,
        });
        res.status(201).json({ content_object: contentObject, log_id: logId, safety_flags: safetyFlags });
    } catch (err) {
        const status = err.statusCode || 500;
        console.error('[GenerationService] error:', err.message);
        res.status(status).json({ error: err.message });
    }
});

