// GET /api/generate/logs — paginated generation log (admin/site_owner only)
app.get('/api/generate/logs', async (req, res) => {
    const actor = await requirePrivileged(req, res); if (!actor) return;
    if (!['admin','site_owner'].includes(actor.role)) {
        return res.status(403).json({ error: 'admin or site_owner role required' });
    }
    try {
        const limit  = Math.min(parseInt(req.query.limit  || '50',  10), 200);
        const offset = parseInt(req.query.offset || '0',  10);
        const statusFilter = req.query.status || null;
        const conditions = statusFilter ? `WHERE status=$3` : '';
        const params = statusFilter ? [limit, offset, statusFilter] : [limit, offset];
        const { rows } = await pgPool.query(
            `SELECT id, actor_id, recipe_slug, object_type, taxonomy_node_id, status,
                    result_object_id, safety_flags, input_tokens, output_tokens,
                    duration_ms, requested_at, completed_at, error_message
             FROM jv_ai_generation_logs
             ${conditions}
             ORDER BY requested_at DESC LIMIT $1 OFFSET $2`,
            params
        );
        const { rows: [{ count }] } = await pgPool.query(
            `SELECT COUNT(*)::int AS count FROM jv_ai_generation_logs ${conditions}`,
            statusFilter ? [statusFilter] : []
        );
        res.json({ items: rows, total: count, limit, offset });
    } catch (err) {
        res.status(500).json({ error: err.message });
    }
});

