// GET /api/authors/usage — usage report (admin/site_owner only) — must be before /:id
app.get('/api/authors/usage', async (req, res) => {
    const actor = await requirePrivileged(req, res); if (!actor) return;
    if (!['admin','site_owner'].includes(actor.role))
        return res.status(403).json({ error: 'admin or site_owner required' });
    try {
        const { rows } = await pgPool.query(`
            SELECT cam.author_id,
                   p.title AS author_name,
                   ctm.taxonomy_node_id,
                   t.name  AS node_name,
                   t.slug  AS node_slug,
                   COUNT(*)::int AS content_count,
                   COUNT(CASE WHEN co.meta_data->>'ai_generated'='true' THEN 1 END)::int AS ai_generated_count,
                   MAX(co.created_at) AS last_used_at
            FROM jv_content_author_map cam
            JOIN jv_content_objects co ON co.id=cam.content_object_id
            LEFT JOIN jv_content_objects p ON p.id=cam.author_id AND p.object_type='author'
            LEFT JOIN jv_content_taxonomy_map ctm ON ctm.object_id::uuid=co.id
            LEFT JOIN jv_taxonomy t ON t.id=ctm.taxonomy_node_id
            GROUP BY cam.author_id, p.title, ctm.taxonomy_node_id, t.name, t.slug
            ORDER BY content_count DESC LIMIT 200`);
        res.json({ report: rows });
    } catch (err) {
        res.status(500).json({ error: err.message });
    }
});

