// PUT /api/authors/:id — update author profile (author:edit permission)
app.put('/api/authors/:id', async (req, res) => {
    const actor = await requirePrivileged(req, res); if (!actor) return;
    if (!hasPermission(actor.role, 'author:edit')) return res.status(403).json({ error: 'author:edit permission required' });
    const { title, summary, status, extension_data } = req.body || {};
    const sets = []; const vals = [req.params.id];
    if (title          !== undefined) { vals.push(title);                          sets.push(`title=$${vals.length}`); }
    if (summary        !== undefined) { vals.push(summary);                        sets.push(`summary=$${vals.length}`); }
    if (status         !== undefined) { vals.push(status);                         sets.push(`status=$${vals.length}`); }
    if (extension_data !== undefined) { vals.push(JSON.stringify(extension_data)); sets.push(`extension_data=$${vals.length}`); }
    if (sets.length === 0) return res.status(400).json({ error: 'No fields to update' });
    vals.push(actor.email);
    sets.push(`updated_by=$${vals.length}`, `updated_at=NOW()`);
    try {
        const { rows: [co] } = await pgPool.query(
            `UPDATE jv_content_objects SET ${sets.join(',')} WHERE id=$1::uuid AND object_type='author' RETURNING *`,
            vals);
        if (!co) return res.status(404).json({ error: 'Author not found' });
        await createRevision(pgPool, co.id, co, 'Author profile updated', actor.email);
        logAuditEvent(pgPool, { event_type: 'author.updated', actor_id: actor.email,
            target_type: 'jv_content_objects', target_id: co.id,
            details: { fields: Object.keys(req.body) }, ip_address: req.ip, user_agent: req.get('user-agent') });
        res.json(co);
    } catch (err) {
        res.status(500).json({ error: err.message });
    }
});

