// POST /api/authors/:id/bios — create a new bio
app.post('/api/authors/:id/bios', async (req, res) => {
    const actor = await requirePrivileged(req, res); if (!actor) return;
    if (!hasPermission(actor.role, 'author:edit')) return res.status(403).json({ error: 'author:edit permission required' });
    const { channel, bio_text = '', bio_short, language = 'en-US', is_primary = false } = req.body || {};
    if (!channel) return res.status(400).json({ error: 'channel is required' });
    const wc = bio_text.trim().split(/\s+/).filter(Boolean).length;
    try {
        // If marking as primary, clear existing primary for this author
        if (is_primary) {
            await pgPool.query(
                `UPDATE jv_author_bios SET is_primary=false WHERE author_id=$1::uuid`,
                [req.params.id]);
        }
        const { rows: [bio] } = await pgPool.query(
            `INSERT INTO jv_author_bios(author_id, channel, bio_text, bio_short, word_count, language, is_primary, updated_by)
             VALUES ($1::uuid,$2,$3,$4,$5,$6,$7,$8) RETURNING *`,
            [req.params.id, channel, bio_text, bio_short || null, wc, language, is_primary, actor.email]);
        logAuditEvent(pgPool, { event_type: 'author.bio_created', actor_id: actor.email,
            target_type: 'jv_author_bios', target_id: bio.id,
            details: { author_id: req.params.id, channel, language }, ip_address: req.ip, user_agent: req.get('user-agent') });
        res.status(201).json(bio);
    } catch (err) {
        if (err.code === '23505') return res.status(409).json({ error: 'Bio already exists for this channel and language' });
        res.status(500).json({ error: err.message });
    }
});

// PUT /api/authors/:id/bios/:bioId — update a bio (increments version, creates revision)
app.put('/api/authors/:id/bios/:bioId', async (req, res) => {
    const actor = await requirePrivileged(req, res); if (!actor) return;
    if (!hasPermission(actor.role, 'author:edit')) return res.status(403).json({ error: 'author:edit permission required' });
    const { bio_text, bio_short, language, is_primary, channel } = req.body || {};
    try {
        const { rows: [existing] } = await pgPool.query(
            `SELECT * FROM jv_author_bios WHERE id=$1::uuid AND author_id=$2::uuid`,
            [req.params.bioId, req.params.id]);
        if (!existing) return res.status(404).json({ error: 'Bio not found' });
        // Snapshot old version
        await pgPool.query(
            `INSERT INTO jv_author_bio_revisions(bio_id, version, snapshot, changed_by)
             VALUES ($1::uuid, $2, $3, $4)`,
            [existing.id, existing.version, JSON.stringify(existing), actor.email]);
        // If marking as primary, clear existing primary for this author
        if (is_primary === true) {
            await pgPool.query(
                `UPDATE jv_author_bios SET is_primary=false WHERE author_id=$1::uuid AND id != $2::uuid`,
                [req.params.id, existing.id]);
        }
        const sets = []; const vals = [existing.id];
        if (bio_text  !== undefined) { const wc = bio_text.trim().split(/\s+/).filter(Boolean).length; vals.push(bio_text); sets.push(`bio_text=$${vals.length}`); vals.push(wc); sets.push(`word_count=$${vals.length}`); }
        if (bio_short !== undefined) { vals.push(bio_short); sets.push(`bio_short=$${vals.length}`); }
        if (language  !== undefined) { vals.push(language);  sets.push(`language=$${vals.length}`); }
        if (is_primary !== undefined){ vals.push(is_primary); sets.push(`is_primary=$${vals.length}`); }
        if (channel   !== undefined) { vals.push(channel);   sets.push(`channel=$${vals.length}`); }
        vals.push(actor.email, existing.version + 1);
        sets.push(`updated_by=$${vals.length - 1}`, `version=$${vals.length}`, `updated_at=NOW()`);
        const { rows: [bio] } = await pgPool.query(
            `UPDATE jv_author_bios SET ${sets.join(',')} WHERE id=$1::uuid RETURNING *`, vals);
        logAuditEvent(pgPool, { event_type: 'author.bio_updated', actor_id: actor.email,
            target_type: 'jv_author_bios', target_id: bio.id,
            details: { author_id: req.params.id, channel: bio.channel, version: bio.version },
            ip_address: req.ip, user_agent: req.get('user-agent') });
        res.json(bio);
    } catch (err) {
        if (err.code === '23505') return res.status(409).json({ error: 'Channel+language combination already exists' });
        res.status(500).json({ error: err.message });
    }
});

