// GET /api/sites/publishing-report — must be before /api/sites/:id
app.get('/api/sites/publishing-report', async (req, res) => {
    const actor = await requirePrivileged(req, res); if (!actor) return;
    if (!['admin', 'site_owner'].includes(actor.role))
        return res.status(403).json({ error: 'admin or site_owner required' });
    try {
        const { rows } = await pgPool.query(`
            SELECT
                s.id AS site_id, s.title AS site_title,
                s.extension_data->>'domain' AS domain,
                COUNT(CASE WHEN (t->>'status')='published' THEN 1 END)::int AS published_count,
                COUNT(CASE WHEN (t->>'status')='pending' THEN 1 END)::int AS pending_count,
                MAX(t->>'published_at') AS last_published_at
            FROM jv_content_objects s,
                 jv_content_objects co,
                 jsonb_array_elements(co.publish_targets) AS t
            WHERE s.object_type='site'
              AND co.object_type != 'site'
              AND (t->>'site_id') = s.id::text
            GROUP BY s.id, s.title, s.extension_data->>'domain'
            ORDER BY published_count DESC
        `);
        res.json({ report: rows });
    } catch (err) {
        res.status(500).json({ error: err.message });
    }
});

