// D9 — Sitemap + RSS (register BEFORE other /api/v1/ routes)
app.get('/api/v1/sitemap/:filename', async (req, res) => {
    const key = await requireApiKey(req, res); if (!key) return;
    const domain = req.params.filename.replace(/\.xml$/, '');
    try {
        const { rows: [row] } = await pgPool.query(
            `SELECT xml_content FROM jv_sitemaps WHERE site_domain=$1`, [domain]
        );
        if (!row) {
            const xml = await generateSitemapXml(pgPool, domain);
            if (!xml) return res.status(404).json({ error: 'Site not found' });
            await pgPool.query(
                `INSERT INTO jv_sitemaps (site_domain, xml_content) VALUES ($1,$2)
                 ON CONFLICT (site_domain) DO UPDATE SET xml_content=$2, generated_at=NOW()`,
                [domain, xml]
            );
            res.set('Content-Type', 'application/xml');
            setCacheHeaders(res, 3600, 86400);
            return res.send(xml);
        }
        res.set('Content-Type', 'application/xml');
        setCacheHeaders(res, 3600, 86400);
        res.send(row.xml_content);
    } catch (e) {
        console.error('[GET /api/v1/sitemap]', e.message);
        res.status(500).json({ error: e.message });
    }
});

