// =============================================================================
// PROMPT RECIPE TEST GENERATE (Part 2 Section 5) — ephemeral, no content object saved
// =============================================================================

app.post('/api/v1/prompt-recipes/test', async (req, res) => {
    const actor = await requirePrivileged(req, res);
    if (!actor) return;
    if (actor.role !== 'admin') return res.status(403).json({ error: 'Admin only' });
    const { system_prompt = '', user_template = '', variables = {}, model = 'claude-haiku-4-5-20251001', max_tokens = 500 } = req.body;
    function sub(tpl, vars) { return tpl.replace(/\{\{(\w+)\}\}/g, (_, k) => vars[k] !== undefined ? vars[k] : `{{${k}}}`); }
    const t0 = Date.now();
    try {
        const response = await anthropic.messages.create({
            model,
            max_tokens: Math.min(Number(max_tokens) || 500, 4096),
            system: sub(system_prompt, variables),
            messages: [{ role: 'user', content: sub(user_template, variables) }],
        });
        res.json({
            output:        response.content[0]?.text ?? '',
            model:         response.model,
            input_tokens:  response.usage?.input_tokens ?? 0,
            output_tokens: response.usage?.output_tokens ?? 0,
            duration_ms:   Date.now() - t0,
        });
    } catch (e) { res.status(500).json({ error: e.message }); }
});

