// Middleware: all /api/v1/prompt-tree/* require prompt:manage (admin-only)
app.use('/api/v1/prompt-tree', (req, res, next) => {
    const token = (req.headers.authorization || '').replace('Bearer ', '');
    const payload = authVerifyJWT(token);
    if (!payload) return res.status(401).json({ error: 'Unauthorized' });
    if (payload.role !== 'admin') return res.status(403).json({ error: 'prompt:manage permission required' });
    req._promptUser = payload;
    next();
});

// GET /api/v1/prompt-tree — full nested tree
app.get('/api/v1/prompt-tree', async (req, res) => {
    try {
        const { rows } = await pgPool.query(
            `SELECT * FROM prompt_nav_nodes WHERE is_active = true ORDER BY depth, sort_order, title`
        );
        const map = {};
        rows.forEach(r => { map[r.id] = { ...r, children: [] }; });
        const roots = [];
        rows.forEach(r => {
            if (r.parent_id && map[r.parent_id]) map[r.parent_id].children.push(map[r.id]);
            else roots.push(map[r.id]);
        });
        res.json({ nodes: roots });
    } catch (e) { res.status(500).json({ error: e.message }); }
});

// GET /api/v1/prompt-tree/assignments?prompt_id=:uuid — assignments for a prompt
app.get('/api/v1/prompt-tree/assignments', async (req, res) => {
    try {
        const { prompt_id } = req.query;
        if (!prompt_id) return res.status(400).json({ error: 'prompt_id required' });
        const { rows } = await pgPool.query(
            `SELECT a.id, a.prompt_nav_node_id, a.is_primary, a.assigned_at,
                    n.title AS node_title, n.materialized_path
             FROM prompt_nav_node_prompts a
             JOIN prompt_nav_nodes n ON n.id = a.prompt_nav_node_id
             WHERE a.prompt_id = $1 AND n.is_active = true
             ORDER BY a.assigned_at`,
            [prompt_id]
        );
        res.json({ assignments: rows });
    } catch (e) { res.status(500).json({ error: e.message }); }
});

// POST /api/v1/prompt-tree/assignments — assign prompt to node
app.post('/api/v1/prompt-tree/assignments', async (req, res) => {
    try {
        const actor = req._promptUser;
        const { prompt_id, node_id, is_primary = false } = req.body;
        if (!prompt_id || !node_id) return res.status(400).json({ error: 'prompt_id and node_id required' });
        const { rows } = await pgPool.query(
            `INSERT INTO prompt_nav_node_prompts (prompt_id, prompt_nav_node_id, is_primary, assigned_by)
             VALUES ($1, $2, $3, $4)
             ON CONFLICT (prompt_id, prompt_nav_node_id) DO UPDATE SET is_primary = EXCLUDED.is_primary
             RETURNING id, prompt_nav_node_id, is_primary, assigned_at`,
            [prompt_id, node_id, is_primary, actor.id]
        );
        const { rows: nodeRows } = await pgPool.query(
            `SELECT title, materialized_path FROM prompt_nav_nodes WHERE id = $1`, [node_id]
        );
        const assignment = { ...rows[0], node_title: nodeRows[0]?.title, materialized_path: nodeRows[0]?.materialized_path };
        logAuditEvent(pgPool, { event_type: 'prompt_tree.modified', actor_id: actor.email,
            target_type: 'prompt_nav_node_prompts', target_id: rows[0].id,
            details: { action: 'assigned', prompt_id, node_id }, ip_address: req.ip, user_agent: req.get('user-agent') });
        res.status(201).json({ assignment });
    } catch (e) { res.status(500).json({ error: e.message }); }
});

