// GET /api/v1/automation-jobs?node_id=&status_group=pending|completed&limit=50&offset=0
app.get('/api/v1/automation-jobs', async (req, res) => {
    try {
        const actor = req._jobActor;
        const { node_id, status_group = 'pending', limit = 50, offset = 0 } = req.query;
        const pendingStatuses   = ['queued', 'running', 'paused', 'retrying'];
        const completedStatuses = ['completed', 'failed', 'cancelled'];
        const statuses = status_group === 'completed' ? completedStatuses : pendingStatuses;

        // Section 12: parameterized ownership filter — rebuilds positionally
        const vals = [statuses];

        // Owner filter: non-privileged users see only own jobs
        let ownerFilter = '';
        if (!hasPermission(actor.role, 'automation:view_all_jobs')) {
            vals.push(actor.email);
            ownerFilter = `AND j.requested_by = $${vals.length}`;
        }

        // Node filter: scope to node + descendants
        let nodeFilter = '';
        if (node_id) {
            vals.push(node_id);
            nodeFilter = `AND j.automation_node_id IN (
                SELECT id FROM automation_nav_nodes WHERE is_active = true
                AND (id = $${vals.length}
                     OR materialized_path = $${vals.length}
                     OR materialized_path LIKE $${vals.length} || '/%'
                     OR materialized_path LIKE '%/' || $${vals.length}
                     OR materialized_path LIKE '%/' || $${vals.length} || '/%')
            )`;
        }

        const orderBy = status_group === 'completed'
            ? 'ORDER BY j.completed_at DESC NULLS LAST'
            : 'ORDER BY j.priority ASC, j.created_at ASC';

        const limitVal  = Math.min(Number(limit)  || 50,  200);
        const offsetVal = Number(offset) || 0;
        vals.push(limitVal, offsetVal);
        const limitParam  = `$${vals.length - 1}`;
        const offsetParam = `$${vals.length}`;

        const { rows } = await pgPool.query(
            `SELECT j.*,
                    n.title AS automation_node_title,
                    p.title AS prompt_name
             FROM jv_automation_jobs j
             LEFT JOIN automation_nav_nodes n ON n.id = j.automation_node_id
             LEFT JOIN jv_content_objects   p ON p.id = j.prompt_recipe_id
             WHERE j.status = ANY($1) ${ownerFilter} ${nodeFilter}
             ${orderBy}
             LIMIT ${limitParam} OFFSET ${offsetParam}`,
            vals
        );
        const countVals = vals.slice(0, vals.length - 2);
        const { rows: [{ count }] } = await pgPool.query(
            `SELECT COUNT(*) FROM jv_automation_jobs j
             WHERE j.status = ANY($1) ${ownerFilter} ${nodeFilter}`,
            countVals
        );
        res.json({ jobs: rows, total: Number(count), limit: limitVal, offset: offsetVal });
    } catch (e) { res.status(500).json({ error: e.message }); }
});

