// GET /api/v1/automation-job-templates?node_id=&active_only=true&limit=50&offset=0
app.get('/api/v1/automation-job-templates', async (req, res) => {
    try {
        const { node_id, active_only = 'true', limit = 50, offset = 0 } = req.query;
        const vals = [];
        const conditions = [];
        if (active_only === 'true') { vals.push(true); conditions.push(`t.is_active = $${vals.length}`); }
        if (node_id) { vals.push(node_id); conditions.push(`t.automation_nav_node_id = $${vals.length}`); }
        const where = conditions.length ? 'WHERE ' + conditions.join(' AND ') : '';
        const limitVal = Math.min(Number(limit) || 50, 200);
        const offsetVal = Number(offset) || 0;
        const { rows } = await pgPool.query(
            `SELECT t.*, n.title AS node_title, p.title AS prompt_name
             FROM jv_automation_job_templates t
             LEFT JOIN automation_nav_nodes n ON n.id = t.automation_nav_node_id
             LEFT JOIN jv_content_objects  p ON p.id = t.prompt_id
             ${where}
             ORDER BY t.created_at DESC
             LIMIT $${vals.length + 1} OFFSET $${vals.length + 2}`,
            [...vals, limitVal, offsetVal]
        );
        const { rows: [{ count }] } = await pgPool.query(
            `SELECT COUNT(*) FROM jv_automation_job_templates t ${where}`, vals
        );
        res.json({ templates: rows, total: Number(count), limit: limitVal, offset: offsetVal });
    } catch (e) { res.status(500).json({ error: e.message }); }
});

