// PUT /api/v1/automation-job-templates/:id — admin only
app.put('/api/v1/automation-job-templates/:id', async (req, res) => {
    try {
        const actor = req._templateActor;
        if (!hasPermission(actor.role, 'automation:manage_templates')) return res.status(403).json({ error: 'automation:manage_templates permission required' });
        const { id } = req.params;
        const {
            template_name, automation_nav_node_id, target_content_type, prompt_id,
            default_parameters, default_quantity, default_priority, description, is_active,
        } = req.body || {};
        const sets = [], vals = [];
        const addField = (col, val) => { sets.push(`${col} = $${vals.length + 1}`); vals.push(val); };
        if (template_name !== undefined)          addField('template_name', template_name);
        if (automation_nav_node_id !== undefined) addField('automation_nav_node_id', automation_nav_node_id || null);
        if (target_content_type !== undefined)    addField('target_content_type', target_content_type);
        if (prompt_id !== undefined)              addField('prompt_id', prompt_id || null);
        if (default_parameters !== undefined)     addField('default_parameters', JSON.stringify(default_parameters));
        if (default_quantity !== undefined)       addField('default_quantity', default_quantity);
        if (default_priority !== undefined)       addField('default_priority', default_priority);
        if (description !== undefined)            addField('description', description);
        if (is_active !== undefined)              addField('is_active', is_active);
        if (!sets.length) return res.status(400).json({ error: 'No fields to update' });
        sets.push('updated_by = $' + (vals.length + 1)); vals.push(actor.email);
        sets.push('updated_at = NOW()');
        vals.push(id);
        const { rows } = await pgPool.query(
            `UPDATE jv_automation_job_templates SET ${sets.join(', ')}
             WHERE id = $${vals.length} RETURNING *`, vals
        );
        if (!rows.length) return res.status(404).json({ error: 'Template not found' });
        res.json({ template: rows[0] });
    } catch (e) { res.status(500).json({ error: e.message }); }
});

