// POST /api/v1/automation-job-templates/:id/apply — create one job per taxonomy_node_id
// Body: { taxonomy_node_ids: number[], overrides?: Partial<job fields>, job_name?: string }
app.post('/api/v1/automation-job-templates/:id/apply', async (req, res) => {
    try {
        const actor = req._templateActor;
        const { rows: [tmpl] } = await pgPool.query(
            `SELECT * FROM jv_automation_job_templates WHERE id = $1`, [req.params.id]
        );
        if (!tmpl) return res.status(404).json({ error: 'Template not found' });
        if (!tmpl.is_active) return res.status(400).json({ error: 'Template is inactive' });
        const { taxonomy_node_ids = [], overrides = {}, job_name } = req.body || {};
        const nodeList = Array.isArray(taxonomy_node_ids) && taxonomy_node_ids.length > 0
            ? taxonomy_node_ids
            : [null];
        const createdJobs = [];
        for (const nodeId of nodeList) {
            const name = job_name
                ? (nodeList.length > 1 ? `${job_name} (node ${nodeId})` : job_name)
                : `${tmpl.template_name}${nodeId ? ` — node ${nodeId}` : ''}`;
            const { rows } = await pgPool.query(
                `INSERT INTO jv_automation_jobs
                   (name, automation_node_id, target_taxonomy_node_id, target_content_type,
                    prompt_recipe_id, priority, requested_by, identity_type,
                    max_retries, parameters, quantity)
                 VALUES ($1,$2,$3,$4,$5,$6,$7,'system',$8,$9,$10) RETURNING *`,
                [
                    name,
                    tmpl.automation_nav_node_id,
                    nodeId || overrides.target_taxonomy_node_id || null,
                    overrides.target_content_type || tmpl.target_content_type,
                    tmpl.prompt_id || null,
                    overrides.priority || tmpl.default_priority,
                    actor.email,
                    overrides.max_retries || 3,
                    JSON.stringify({ ...tmpl.default_parameters, ...(overrides.parameters || {}) }),
                    overrides.quantity || tmpl.default_quantity,
                ]
            );
            createdJobs.push(rows[0]);
        }
        logAuditEvent(pgPool, { event_type: 'automation_template.applied', actor_id: actor.email,
            target_type: 'jv_automation_job_templates', target_id: tmpl.id,
            details: { jobs_created: createdJobs.length }, ip_address: req.ip, user_agent: req.get('user-agent') });
        res.status(201).json({ jobs: createdJobs, count: createdJobs.length });
    } catch (e) { res.status(500).json({ error: e.message }); }
});

// ── Automation Dashboard API (Section 10) ────────────────────────────────────
// GET /api/v1/automation-dashboard
// Query: time_window=7d|24h|30d, user_filter=, content_type=, taxonomy_node_id=,
//        identity_filter=system|user, activity_offset=0
app.get('/api/v1/automation-dashboard', async (req, res) => {
    const actor = await requirePrivileged(req, res); if (!actor) return;
    try {
        const {
            time_window = '7d', user_filter, content_type,
            taxonomy_node_id, identity_filter, activity_offset = 0,
        } = req.query;

        // ── Job filter conditions (shared by summary cards + filter options) ─
        const jobVals = [];
        const jobConds = [];
        if (user_filter)     { jobVals.push(user_filter);           jobConds.push(`requested_by = $${jobVals.length}`); }
        if (content_type)    { jobVals.push(content_type);          jobConds.push(`target_content_type = $${jobVals.length}`); }
        if (taxonomy_node_id){ jobVals.push(Number(taxonomy_node_id)); jobConds.push(`target_taxonomy_node_id = $${jobVals.length}`); }
        if (identity_filter) { jobVals.push(identity_filter);       jobConds.push(`identity_type = $${jobVals.length}`); }
        const jobWhere = jobConds.length ? 'WHERE ' + jobConds.join(' AND ') : '';

        // ── Activity feed filter conditions ───────────────────────────────────
        const actVals = ['automation_%'];
        const actConds = ['event_type LIKE $1'];
        // Time window applied to audit log entries
        actVals.push(time_window);
        actConds.push(
            `created_at >= NOW() - CASE WHEN $${actVals.length} = '24h' THEN INTERVAL '24 hours'
                                        WHEN $${actVals.length} = '30d' THEN INTERVAL '30 days'
                                        ELSE INTERVAL '7 days' END`
        );
        if (user_filter)  { actVals.push(user_filter); actConds.push(`actor_id = $${actVals.length}`); }
        const actWhere = 'WHERE ' + actConds.join(' AND ');

        const actLimitVal  = 50;
        const actOffsetVal = Math.max(0, Number(activity_offset) || 0);

        // ── Time window param for summary (completed_at / created_at cutoff) ──
        // We add it as a separate param to the job query
        const summaryVals = [...jobVals, time_window];
        const twIdx = summaryVals.length;
        const twExpr = `CASE WHEN $${twIdx} = '24h' THEN INTERVAL '24 hours'
                             WHEN $${twIdx} = '30d' THEN INTERVAL '30 days'
                             ELSE INTERVAL '7 days' END`;

        const [summaryRes, activityRes, actCountRes, filterRes] = await Promise.all([
            pgPool.query(
                `SELECT
                    COUNT(*) FILTER (WHERE status IN ('queued','paused'))                             AS pending,
                    COUNT(*) FILTER (WHERE status = 'running')                                       AS running,
                    COUNT(*) FILTER (WHERE status = 'failed'    AND completed_at >= NOW() - ${twExpr}) AS failed_period,
                    COUNT(*) FILTER (WHERE status = 'completed' AND completed_at >= NOW() - ${twExpr}) AS completed_period
                 FROM jv_automation_jobs ${jobWhere}`,
                summaryVals
            ),
            pgPool.query(
                `SELECT al.id, al.event_type, al.actor_id, al.target_id, al.details, al.created_at,
                        j.name AS job_name, j.target_content_type, j.identity_type, j.identity_id
                 FROM jv_audit_log al
                 LEFT JOIN jv_automation_jobs j ON j.id::text = al.target_id AND al.target_type = 'jv_automation_jobs'
                 ${actWhere}
                 ORDER BY al.created_at DESC
                 LIMIT $${actVals.length + 1} OFFSET $${actVals.length + 2}`,
                [...actVals, actLimitVal, actOffsetVal]
            ),
            pgPool.query(
                `SELECT COUNT(*) FROM jv_audit_log al ${actWhere}`, actVals
            ),
            pgPool.query(
                `SELECT
                    COALESCE(ARRAY_AGG(DISTINCT requested_by ORDER BY requested_by) FILTER (WHERE requested_by IS NOT NULL), '{}') AS users,
                    COALESCE(ARRAY_AGG(DISTINCT target_content_type ORDER BY target_content_type) FILTER (WHERE target_content_type IS NOT NULL), '{}') AS content_types
                 FROM jv_automation_jobs`
            ),
        ]);

        const s = summaryRes.rows[0];
        res.json({
            summary: {
                pending:          Number(s.pending),
                running:          Number(s.running),
                failed_period:    Number(s.failed_period),
                completed_period: Number(s.completed_period),
                time_window,
            },
            activity:       activityRes.rows,
            total:          Number(actCountRes.rows[0].count),
            filter_options: {
                users:         filterRes.rows[0]?.users         ?? [],
                content_types: filterRes.rows[0]?.content_types ?? [],
            },
        });
    } catch (e) { res.status(500).json({ error: e.message }); }
});

// ── OAuth / API-key Execution Identity (Section 11) ─────────────────────────
const { encrypt: encryptToken, decrypt: decryptToken, mask: maskToken } = require('./lib/oauth-encryption');

// Supported OAuth providers config (extend as needed)
const OAUTH_PROVIDERS = {
    anthropic: {
        name:         'Anthropic',
        token_type:   'api_key',   // Anthropic uses API keys, not OAuth
        auth_url:     null,
        token_url:    null,
        scopes:       [],
    },
    openai: {
        name:         'OpenAI',
        token_type:   'api_key',
        auth_url:     null,
        token_url:    null,
        scopes:       [],
    },
};

// GET /api/v1/oauth-tokens/providers — list supported providers
app.get('/api/v1/oauth-tokens/providers', async (req, res) => {
    const actor = await requirePrivileged(req, res); if (!actor) return;
    res.json({
        providers: Object.entries(OAUTH_PROVIDERS).map(([id, cfg]) => ({
            id,
            name:       cfg.name,
            token_type: cfg.token_type,
            supports_oauth: Boolean(cfg.auth_url),
        })),
    });
});

// GET /api/v1/oauth-tokens — list caller's tokens (masked, never plaintext)
// Admin (oauth:view_all) can see all users' tokens; others see only their own.
app.get('/api/v1/oauth-tokens', async (req, res) => {
    const actor = await requirePrivileged(req, res); if (!actor) return;
    try {
        let query, queryVals;
        if (hasPermission(actor.role, 'oauth:view_all')) {
            query = `SELECT id, user_email, provider, token_type, expires_at, scopes,
                            is_active, last_used_at, created_at, updated_at
                     FROM user_oauth_tokens
                     WHERE is_active = true
                     ORDER BY user_email, provider, created_at DESC`;
            queryVals = [];
        } else {
            query = `SELECT id, user_email, provider, token_type, expires_at, scopes,
                            is_active, last_used_at, created_at, updated_at
                     FROM user_oauth_tokens
                     WHERE user_email = $1 AND is_active = true
                     ORDER BY provider, created_at DESC`;
            queryVals = [actor.email];
        }
        const { rows } = await pgPool.query(query, queryVals);
        // Return masked token indicator without exposing access_token
        res.json({ tokens: rows.map(r => ({ ...r, access_token_masked: true })) });
    } catch (e) { res.status(500).json({ error: e.message }); }
});

// POST /api/v1/oauth-tokens/validate-api-key — store an encrypted API key
// Body: { provider: 'anthropic', api_key: 'sk-ant-...' }
app.post('/api/v1/oauth-tokens/validate-api-key', async (req, res) => {
    const actor = await requirePrivileged(req, res); if (!actor) return;
    try {
        const { provider = 'anthropic', api_key } = req.body || {};
        if (!api_key) return res.status(400).json({ error: 'api_key is required' });
        if (!OAUTH_PROVIDERS[provider]) return res.status(400).json({ error: `Unknown provider: ${provider}` });

        // Quick validation: test the key
        let valid = false;
        let validationError = null;
        try {
            const Anthropic = require('@anthropic-ai/sdk');
            const testClient = new Anthropic({ apiKey: api_key });
            await testClient.messages.create({
                model:      'claude-haiku-4-5-20251001',
                max_tokens: 8,
                messages:   [{ role: 'user', content: 'ping' }],
            });
            valid = true;
        } catch (err) {
            validationError = err?.message || 'API key validation failed';
        }

        if (!valid) {
            return res.status(422).json({ error: `Invalid API key: ${validationError}` });
        }

        const encrypted = encryptToken(api_key);
        const masked    = maskToken(api_key);

        // Upsert: deactivate old token for same provider, insert new one
        await pgPool.query(
            `UPDATE user_oauth_tokens SET is_active = false, updated_at = NOW()
             WHERE user_email = $1 AND provider = $2 AND is_active = true`,
            [actor.email, provider]
        );
        const { rows } = await pgPool.query(
            `INSERT INTO user_oauth_tokens
               (user_email, provider, token_type, access_token)
             VALUES ($1, $2, 'api_key', $3)
             RETURNING id, user_email, provider, token_type, is_active, created_at`,
            [actor.email, provider, encrypted]
        );

        logAuditEvent(pgPool, {
            event_type:  'oauth_token.stored',
            actor_id:    actor.email,
            target_type: 'user_oauth_tokens',
            target_id:   rows[0].id,
            details:     { provider, token_type: 'api_key', masked },
            ip_address:  req.ip,
            user_agent:  req.get('user-agent'),
        });

        res.status(201).json({ token: rows[0], masked });
    } catch (e) { res.status(500).json({ error: e.message }); }
});

// DELETE /api/v1/oauth-tokens/:id — revoke a token
app.delete('/api/v1/oauth-tokens/:id', async (req, res) => {
    const actor = await requirePrivileged(req, res); if (!actor) return;
    try {
        const { rows } = await pgPool.query(
            `UPDATE user_oauth_tokens
             SET is_active = false, updated_at = NOW()
             WHERE id = $1 AND user_email = $2 AND is_active = true
             RETURNING id, provider`,
            [req.params.id, actor.email]
        );
        if (!rows.length) return res.status(404).json({ error: 'Token not found or already revoked' });

        logAuditEvent(pgPool, {
            event_type:  'oauth_token.revoked',
            actor_id:    actor.email,
            target_type: 'user_oauth_tokens',
            target_id:   req.params.id,
            details:     { provider: rows[0].provider },
            ip_address:  req.ip,
            user_agent:  req.get('user-agent'),
        });

        res.json({ success: true });
    } catch (e) { res.status(500).json({ error: e.message }); }
});

// GET /api/v1/oauth-tokens/:id/refresh — refresh an OAuth token (no-op for api_key type)
app.get('/api/v1/oauth-tokens/:id/refresh', async (req, res) => {
    const actor = await requirePrivileged(req, res); if (!actor) return;
    try {
        const { rows: [token] } = await pgPool.query(
            `SELECT * FROM user_oauth_tokens WHERE id = $1 AND user_email = $2 AND is_active = true`,
            [req.params.id, actor.email]
        );
        if (!token) return res.status(404).json({ error: 'Token not found' });
        if (token.token_type === 'api_key') {
            return res.json({ message: 'API key tokens do not need refresh', token_id: token.id });
        }
        // OAuth refresh (for future oauth-type tokens)
        if (!token.refresh_token) return res.status(400).json({ error: 'No refresh token stored' });
        const cfg = OAUTH_PROVIDERS[token.provider];
        if (!cfg?.token_url) return res.status(400).json({ error: 'Provider does not support token refresh' });
        // Placeholder: actual OAuth refresh would call cfg.token_url here
        res.status(501).json({ error: 'OAuth token refresh not implemented for this provider' });
    } catch (e) { res.status(500).json({ error: e.message }); }
});

// GET /api/v1/oauth/authorize/:provider — PKCE OAuth flow init
// Returns { auth_url, state, code_verifier } for popup-based flow
app.get('/api/v1/oauth/authorize/:provider', async (req, res) => {
    const actor = await requirePrivileged(req, res); if (!actor) return;
    const cfg = OAUTH_PROVIDERS[req.params.provider];
    if (!cfg) return res.status(404).json({ error: 'Unknown provider' });
    if (!cfg.auth_url) {
        return res.status(400).json({
            error: `Provider "${req.params.provider}" uses API key authentication, not OAuth`,
        });
    }
    // PKCE code verifier + challenge (for future OAuth providers that support it)
    const codeVerifier  = require('crypto').randomBytes(32).toString('base64url');
    const codeChallenge = require('crypto')
        .createHash('sha256').update(codeVerifier).digest('base64url');
    const state = require('crypto').randomBytes(16).toString('hex');
    const authUrl = new URL(cfg.auth_url);
    authUrl.searchParams.set('response_type',  'code');
    authUrl.searchParams.set('client_id',      process.env[`OAUTH_${req.params.provider.toUpperCase()}_CLIENT_ID`] || '');
    authUrl.searchParams.set('redirect_uri',   `${process.env.APP_BASE_URL || ''}/api/v1/oauth/callback`);
    authUrl.searchParams.set('scope',          cfg.scopes.join(' '));
    authUrl.searchParams.set('state',          state);
    authUrl.searchParams.set('code_challenge',        codeChallenge);
    authUrl.searchParams.set('code_challenge_method', 'S256');
    res.json({ auth_url: authUrl.toString(), state, code_verifier: codeVerifier });
});

// GET /api/v1/oauth/callback — exchange authorization code for token
app.get('/api/v1/oauth/callback', async (req, res) => {
    // In popup flow: code exchange would happen here.
    // For now returns 501; real implementation would verify state, exchange code,
    // encrypt and persist tokens, then postMessage to opener and close popup.
    res.status(501).json({ error: 'OAuth callback not implemented for current providers' });
});

// D1 — GET /api/v1/content — paginated published content list
app.get('/api/v1/content', async (req, res) => {
    const key = await requireApiKey(req, res); if (!key) return;
    const { site_domain, object_type, taxonomy_node_id, limit = 20, offset = 0 } = req.query;
    const cacheKey = JSON.stringify(req.query);
    const cached = _apiCache.content.get(cacheKey);
    if (cached) { setCacheHeaders(res, 60, 300); return res.json(cached); }
    try {
        const vals = ['published']; const conditions = [`co.status=$1`, `co.object_type != 'site'`];
        if (object_type) { vals.push(object_type); conditions.push(`co.object_type=$${vals.length}`); }
        if (site_domain) {
            const { rows: [site] } = await pgPool.query(
                `SELECT id FROM jv_content_objects WHERE object_type='site' AND extension_data->>'domain'=$1`,
                [site_domain]
            );
            if (site) {
                vals.push(site.id);
                conditions.push(`EXISTS (SELECT 1 FROM jsonb_array_elements(co.publish_targets) t WHERE (t->>'site_id')=$${vals.length} AND (t->>'status')='published')`);
            }
        }
        if (taxonomy_node_id) {
            const nodeIds = await getDescendantIds(pgPool, Number(taxonomy_node_id));
            if (nodeIds.length) {
                vals.push(nodeIds);
                conditions.push(`EXISTS (SELECT 1 FROM jv_content_taxonomy_map tm WHERE tm.uuid_object_id=co.id AND tm.taxonomy_node_id=ANY($${vals.length}))`);
            }
        }
        vals.push(Number(limit), Number(offset));
        const { rows } = await pgPool.query(
            `SELECT co.id, co.object_type, co.title, co.slug, co.summary, co.language,
                    co.published_at, co.meta_data, co.publish_targets
             FROM jv_content_objects co
             WHERE ${conditions.join(' AND ')}
             ORDER BY co.published_at DESC NULLS LAST
             LIMIT $${vals.length - 1} OFFSET $${vals.length}`,
            vals
        );
        const result = { items: rows, limit: Number(limit), offset: Number(offset) };
        _apiCache.content.set(cacheKey, result, 60_000);
        setCacheHeaders(res, 60, 300);
        res.json(result);
    } catch (e) {
        console.error('[GET /api/v1/content]', e.message);
        res.status(500).json({ error: e.message });
    }
});

// D2 — GET /api/v1/content/:slug — single published item with ETag
app.get('/api/v1/content/:slug', async (req, res, next) => {
    // Let admin routes registered later handle these reserved slugs
    if (['pending-review'].includes(req.params.slug)) return next();
    const key = await requireApiKey(req, res); if (!key) return;
    try {
        // Derive channel from slug context (best-effort; callers may pass ?channel=articles)
        const channel = req.query.channel || 'articles';
        const { rows: [co] } = await pgPool.query(
            `SELECT co.*,
               COALESCE(json_agg(json_build_object(
                 'author_id', cam.author_id,
                 'role', cam.role,
                 'display_order', cam.display_order,
                 'display_name', (a.extension_data->>'display_name'),
                 'canonical_slug', (a.extension_data->>'canonical_slug'),
                 'avatar_asset_id', (a.extension_data->>'avatar_asset_id'),
                 'channel_bio', (SELECT row_to_json(ab) FROM jv_author_bios ab
                                 WHERE ab.author_id=cam.author_id AND ab.channel=$2
                                 AND ab.language=co.language LIMIT 1),
                 'primary_bio', (SELECT row_to_json(ab) FROM jv_author_bios ab
                                 WHERE ab.author_id=cam.author_id AND ab.is_primary=true LIMIT 1)
               ) ORDER BY cam.display_order) FILTER (WHERE cam.author_id IS NOT NULL), '[]'::json)
               AS authors
             FROM jv_content_objects co
             LEFT JOIN jv_content_author_map cam ON cam.content_object_id=co.id
             LEFT JOIN jv_content_objects a ON a.id=cam.author_id AND a.object_type='author'
             WHERE co.slug=$1 AND co.status='published' AND co.object_type != 'site'
             GROUP BY co.id`,
            [req.params.slug, channel]
        );
        if (!co) return res.status(404).json({ error: 'Not found' });
        setCacheHeaders(res, 120, 600);
        res.json(co);
    } catch (e) {
        console.error('[GET /api/v1/content/:slug]', e.message);
        res.status(500).json({ error: e.message });
    }
});

