// D5 — GET /api/v1/sites/:domain/nav — site navigation tree
app.get('/api/v1/sites/:domain/nav', async (req, res) => {
    const key = await requireApiKey(req, res); if (!key) return;
    const { domain } = req.params;
    const cached = _apiCache.nav.get(domain);
    if (cached) { setCacheHeaders(res, 300, 600); return res.json(cached); }
    try {
        const { rows: [site] } = await pgPool.query(
            `SELECT extension_data FROM jv_content_objects
             WHERE object_type='site' AND extension_data->>'domain'=$1`,
            [domain]
        );
        if (!site) return res.status(404).json({ error: 'Site not found' });
        const rootIds = site.extension_data?.taxonomy_mapping?.root_ids || [];
        if (!rootIds.length) { setCacheHeaders(res, 300, 600); return res.json({ nav: [] }); }
        const { rows: navNodes } = await pgPool.query(
            `WITH RECURSIVE tree AS (
               SELECT id, name, slug, parent_id, level FROM categories WHERE id=ANY($1::int[])
               UNION ALL
               SELECT c.id, c.name, c.slug, c.parent_id, c.level
               FROM categories c JOIN tree t ON c.parent_id=t.id
               WHERE c.level <= t.level+1
             ) SELECT * FROM tree ORDER BY level, name`,
            [rootIds]
        );
        const result = { nav: navNodes };
        _apiCache.nav.set(domain, result);
        setCacheHeaders(res, 300, 600);
        res.json(result);
    } catch (e) {
        console.error('[GET /api/v1/sites/:domain/nav]', e.message);
        res.status(500).json({ error: e.message });
    }
});

