// D7 — GET /api/v1/search — full-text search
app.get('/api/v1/search', async (req, res) => {
    const key = await requireApiKey(req, res); if (!key) return;
    const { q, site_domain, limit = 20, offset = 0 } = req.query;
    if (!q || String(q).trim().length < 2)
        return res.status(400).json({ error: 'Query too short' });
    try {
        const vals = [String(q)];
        const conditions = [`status='published'`, `object_type != 'site'`, `search_vector @@ plainto_tsquery('english',$1)`];
        if (site_domain) {
            const { rows: [site] } = await pgPool.query(
                `SELECT id FROM jv_content_objects WHERE object_type='site' AND extension_data->>'domain'=$1`,
                [site_domain]
            );
            if (site) {
                vals.push(site.id);
                conditions.push(`EXISTS (SELECT 1 FROM jsonb_array_elements(publish_targets) t WHERE (t->>'site_id')=$${vals.length} AND (t->>'status')='published')`);
            }
        }
        vals.push(Number(limit), Number(offset));
        const { rows } = await pgPool.query(
            `SELECT id, object_type, title, slug, summary, published_at,
                    ts_rank(search_vector, plainto_tsquery('english',$1)) AS rank
             FROM jv_content_objects
             WHERE ${conditions.join(' AND ')}
             ORDER BY rank DESC
             LIMIT $${vals.length - 1} OFFSET $${vals.length}`,
            vals
        );
        setCacheHeaders(res, 30, 120);
        res.json({ items: rows, query: q });
    } catch (e) {
        console.error('[GET /api/v1/search]', e.message);
        res.status(500).json({ error: e.message });
    }
});

// D8 — POST /api/v1/search/semantic — pgvector cosine similarity search
app.post('/api/v1/search/semantic', async (req, res) => {
    const key = await requireApiKey(req, res); if (!key) return;
    const { q, site_domain, limit = 10 } = req.body || {};
    if (!q) return res.status(400).json({ error: 'q is required' });
    const icBase = process.env.IC_API_BASE;
    const icKey  = process.env.IC_API_KEY || process.env.IC_JWT_TOKEN;
    if (!icBase || !icKey) return res.status(503).json({ error: 'Semantic search not configured' });
    try {
        const embResp = await fetch(`${icBase}/v1/embeddings`, {
            method: 'POST',
            headers: { 'Authorization': `Bearer ${icKey}`, 'Content-Type': 'application/json' },
            body: JSON.stringify({ model: 'text-embedding-3-small', input: String(q) }),
        });
        if (!embResp.ok) return res.status(502).json({ error: 'Embedding generation failed' });
        const { data } = await embResp.json();
        const vec = data?.[0]?.embedding;
        if (!vec) return res.status(502).json({ error: 'No embedding returned' });

        const vals = [JSON.stringify(vec)];
        const conditions = [`status='published'`, `object_type != 'site'`, `embedding IS NOT NULL`];
        if (site_domain) {
            const { rows: [site] } = await pgPool.query(
                `SELECT id FROM jv_content_objects WHERE object_type='site' AND extension_data->>'domain'=$1`,
                [site_domain]
            );
            if (site) {
                vals.push(site.id);
                conditions.push(`EXISTS (SELECT 1 FROM jsonb_array_elements(publish_targets) t WHERE (t->>'site_id')=$${vals.length} AND (t->>'status')='published')`);
            }
        }
        vals.push(Number(limit));
        const { rows } = await pgPool.query(
            `SELECT id, object_type, title, slug, summary, published_at,
                    1-(embedding<=>$1::vector) AS similarity
             FROM jv_content_objects
             WHERE ${conditions.join(' AND ')}
             ORDER BY embedding<=>$1::vector
             LIMIT $${vals.length}`,
            vals
        );
        res.json({ items: rows, query: q });
    } catch (e) {
        console.error('[POST /api/v1/search/semantic]', e.message);
        res.status(500).json({ error: e.message });
    }
});

