app.put('/api/webhooks/:id', async (req, res) => {
    const actor = await requirePrivileged(req, res); if (!actor) return;
    if (actor.role !== 'admin') return res.status(403).json({ error: 'admin required' });
    const { name, url, events, active } = req.body || {};
    const sets = []; const vals = [req.params.id];
    if (name   !== undefined) { vals.push(name);                   sets.push(`name=$${vals.length}`); }
    if (url    !== undefined) { vals.push(url);                    sets.push(`url=$${vals.length}`); }
    if (events !== undefined) { vals.push(JSON.stringify(events)); sets.push(`events=$${vals.length}`); }
    if (active !== undefined) { vals.push(active);                 sets.push(`active=$${vals.length}`); }
    if (!sets.length) return res.status(400).json({ error: 'No fields to update' });
    sets.push(`updated_at=NOW()`);
    try {
        const { rows: [wh] } = await pgPool.query(
            `UPDATE jv_webhooks SET ${sets.join(',')} WHERE id=$1 RETURNING id, name, url, events, active`, vals
        );
        if (!wh) return res.status(404).json({ error: 'Webhook not found' });
        res.json(wh);
    } catch (e) {
        res.status(500).json({ error: e.message });
    }
});

