// GET /api/admin/current-events?status=pending|approved|rejected&limit=100&offset=0
// Reviewer-only: list portal articles by approval status
app.get('/api/admin/current-events', async (req, res) => {
    const payload = requireReviewer(req, res);
    if (!payload) return;

    const status = req.query.status || 'pending';
    const limit = Math.min(parseInt(req.query.limit) || 100, 500);
    const offset = parseInt(req.query.offset) || 0;

    let whereClause;
    if (status === 'approved') {
        whereClause = `WHERE approved = TRUE`;
    } else if (status === 'rejected') {
        whereClause = `WHERE approved = FALSE AND approval_reason IS NOT NULL`;
    } else {
        // pending = approved=FALSE and no rejection reason (never touched)
        whereClause = `WHERE approved = FALSE AND approval_reason IS NULL`;
    }

    try {
        const rows = await pgPool.query(`
            SELECT id, headline, excerpt, topic, source_name,
                   full_article, image_url, cached_image_path,
                   approval_reason, approved, pub_date,
                   array_length(regexp_split_to_array(trim(coalesce(full_article,'')), E'\\s+'), 1) AS word_count
            FROM current_events
            ${whereClause}
            ORDER BY id DESC
            LIMIT $1 OFFSET $2
        `, [limit, offset]);

        const countResult = await pgPool.query(
            `SELECT COUNT(*) FROM current_events ${whereClause}`
        );

        res.json({
            success: true,
            status,
            total: parseInt(countResult.rows[0].count),
            articles: rows.rows
        });
    } catch (err) {
        console.error('[PortalArticles] Error fetching articles:', err.message);
        res.status(500).json({ error: 'Failed to fetch articles', message: err.message });
    }
});

// POST /api/current-events/:id/approve — Reviewer-only: manually approve a portal article
app.post('/api/current-events/:id/approve', async (req, res) => {
    const payload = requireReviewer(req, res);
    if (!payload) return;

    const articleId = parseInt(req.params.id);
    if (!articleId) return res.status(400).json({ error: 'Invalid article ID' });

    try {
        const result = await pgPool.query(
            `UPDATE current_events SET approved = TRUE, approval_reason = 'Manually approved'
             WHERE id = $1 RETURNING id, headline`,
            [articleId]
        );
        if (!result.rowCount) return res.status(404).json({ error: 'Article not found' });

        logReviewerActivity({
            email: payload.email,
            action: 'approve',
            summary: 'Article Manually Approved',
            articleId,
            articleHeadline: result.rows[0].headline,
        });

        // Refresh today's portal layout so newly approved article can appear
        try { await generatePortalLayout(getPstDateString()); } catch (_) {}

        res.json({ success: true, articleId, headline: result.rows[0].headline });
    } catch (err) {
        console.error('[PortalApprove] Error:', err.message);
        res.status(500).json({ error: 'Failed to approve article', message: err.message });
    }
});

// POST /api/current-events/:id/reject — Reviewer-only: manually reject a portal article
app.post('/api/current-events/:id/reject', async (req, res) => {
    const payload = requireReviewer(req, res);
    if (!payload) return;

    const articleId = parseInt(req.params.id);
    const reason = (req.body?.reason || 'Manually rejected').slice(0, 500);
    if (!articleId) return res.status(400).json({ error: 'Invalid article ID' });

    try {
        const result = await pgPool.query(
            `UPDATE current_events SET approved = FALSE, approval_reason = $1
             WHERE id = $2 RETURNING id, headline`,
            [reason, articleId]
        );
        if (!result.rowCount) return res.status(404).json({ error: 'Article not found' });

        logReviewerActivity({
            email: payload.email,
            action: 'reject',
            summary: `Article Manually Rejected: ${reason}`,
            articleId,
            articleHeadline: result.rows[0].headline,
        });

        // Refresh portal layout to remove rejected article if it was shown
        try { await generatePortalLayout(getPstDateString()); } catch (_) {}

        res.json({ success: true, articleId, headline: result.rows[0].headline });
    } catch (err) {
        console.error('[PortalReject] Error:', err.message);
        res.status(500).json({ error: 'Failed to reject article', message: err.message });
    }
});

// =============================================================================
// PART 4 SECTION 4: PORTAL GENERATION ENGINE — Seeded PRNG + Weighted Sampling
// =============================================================================

/**
 * djb2 hash of "${siteId}:${taxonomyNodeId ?? 'null'}:${portalDate}" → unsigned 32-bit seed.
 * Same inputs always produce the same seed, ensuring deterministic portal generation.
 */
function _portalHashSeed(siteId, taxonomyNodeId, portalDate) {
    const str = `${siteId}:${taxonomyNodeId ?? 'null'}:${portalDate}`;
    let h = 5381;
    for (let i = 0; i < str.length; i++) h = ((h * 33) ^ str.charCodeAt(i)) >>> 0;
    return h;
}

/**
 * Linear Congruential Generator seeded from _portalHashSeed.
 * Returns a closure () => [0, 1) that produces the same sequence for the same seed.
 */
function _makeSeededRng(seed) {
    let s = seed >>> 0;
    return function () {
        s = ((Math.imul(1664525, s) + 1013904223) >>> 0);
        return s / 0x100000000;
    };
}

/**
 * Efraimidis-Spirakis weighted sampling without replacement.
 * Each item must have a _weight property (> 0). Returns top-k items by key = rng()^(1/weight).
 */
function _weightedSample(items, k, rng) {
    if (items.length <= k) return [...items];
    const keyed = items.map(item => ({
        item,
        key: Math.pow(rng(), 1 / Math.max(item._weight ?? 1, 0.0001)),
    }));
    keyed.sort((a, b) => b.key - a.key);
    return keyed.slice(0, k).map(x => x.item);
}

/**
 * Resolves portal selection rules for a given site + taxonomy node.
 * Falls back to site-level default rule, then built-in defaults.
 */
async function _resolveSelectionRules(siteId, nodeId) {
    const DEFAULT_RULES = {
        min_items: 5,
        max_items: 20,
        boost_recent_days: 7,
        boost_editorial: 1,
        exclude_if_older_than_days: null,
        content_type_filter: [],
        percentage: 100,
    };
    try {
        const r = await pgPool.query(
            `SELECT * FROM portal_selection_rules
             WHERE site_id=$1 AND (taxonomy_node_id=$2 OR taxonomy_node_id IS NULL)
             ORDER BY taxonomy_node_id NULLS LAST LIMIT 1`,
            [siteId, nodeId]
        );
        if (!r.rows[0]) return DEFAULT_RULES;
        const row = r.rows[0];
        return {
            ...DEFAULT_RULES,
            ...row,
            content_type_filter: Array.isArray(row.content_type_filter)
                ? row.content_type_filter
                : (row.content_type_filter || []),
        };
    } catch (e) {
        console.error('[portal:resolveRules]', e.message);
        return DEFAULT_RULES;
    }
}

/**
 * Full portal page generation pipeline:
 *   1. Resolve selection rules for site+node
 *   2. Fetch inclusive taxonomy subtree IDs
 *   3. Query candidate content pool (up to 500 items)
 *   4. Load yesterday's portal for anti-repetition
 *   5. Assign weights (recency × editorial × anti-repetition)
 *   6. Seeded weighted sample → upsert portal_pages
 *
 * Homepage portals are stubbed as empty (deferred to Section 10 Websites module).
 */
async function _generatePortalPage(siteId, portalType, taxonomyNodeId, portalDate, generatedBy, generationMethod = 'manual') {
    // Homepage: aggregate content from all root category descendants for this site
    if (portalType === 'homepage') {
        const siteRes = await pgPool.query(
            `SELECT extensions FROM jv_sites WHERE id=$1`, [siteId]
        );
        const rootCatIds = siteRes.rows[0]?.extensions?.root_category_ids ?? [];
        if (!rootCatIds.length) {
            return { portal_type: 'homepage', content_ids: [], item_count: 0, status: 'active', generation_method: generationMethod };
        }
        // Gather all descendant node IDs across all root categories
        let allNodeIds = [];
        for (const rootId of rootCatIds) {
            const ids = await getDescendantIds(pgPool, Number(rootId));
            allNodeIds = allNodeIds.concat(ids);
        }
        allNodeIds = [...new Set(allNodeIds)];
        if (!allNodeIds.length) {
            return { portal_type: 'homepage', content_ids: [], item_count: 0, status: 'active', generation_method: generationMethod };
        }
        const typeFilter = ['article', 'devotional', 'scripture', 'story'];
        const poolRes = await pgPool.query(
            `SELECT co.id, co.updated_at,
                    COALESCE((co.extension_data->>'editorial_rank')::int, 0) AS editorial_rank
             FROM jv_content_objects co
             JOIN jv_content_taxonomy_map ctm
               ON ctm.uuid_object_id = co.id AND ctm.taxonomy_node_id = ANY($1)
             WHERE co.object_type = ANY($2)
             ORDER BY co.updated_at DESC
             LIMIT 500`,
            [allNodeIds, typeFilter]
        );
        const pool = poolRes.rows;
        // Seeded shuffle with anti-repetition
        const yesterday = new Date(portalDate);
        yesterday.setDate(yesterday.getDate() - 1);
        const ydRes = await pgPool.query(
            `SELECT content_ids FROM portal_pages
             WHERE site_id=$1 AND portal_type='homepage' AND portal_date=$2 AND status='active'`,
            [siteId, yesterday.toISOString().slice(0, 10)]
        );
        const yesterdayIds = new Set((ydRes.rows[0]?.content_ids ?? []).map(String));
        const boostCutoff = new Date(Date.now() - 7 * 86400000);
        for (const item of pool) {
            let w = 1.0;
            if (new Date(item.updated_at) >= boostCutoff) w *= 2.0;
            if (item.editorial_rank > 0)                   w *= 1.25;
            if (!yesterdayIds.has(String(item.id)))        w *= 1.5;
            item._weight = w;
        }
        const seed = _portalHashSeed(siteId, null, portalDate);
        const rng  = _makeSeededRng(seed);
        const targetCount = Math.min(100, Math.max(10, pool.length));
        const selected = _weightedSample(pool, targetCount, rng);
        const contentIds = selected.map(r => r.id);
        await pgPool.query(
            `UPDATE portal_pages SET status='superseded', updated_at=NOW()
             WHERE site_id=$1 AND portal_type='homepage' AND taxonomy_node_id IS NULL
               AND portal_date=$2 AND status='active'`,
            [siteId, portalDate]
        );
        const { rows: [hp] } = await pgPool.query(
            `INSERT INTO portal_pages
               (site_id, portal_type, taxonomy_node_id, portal_date, status, generated_by,
                content_ids, item_count, generation_method, pool_size, selection_percentage,
                selection_config, metadata)
             VALUES ($1,'homepage',NULL,$2,'active',$3,$4,$5,$6,$7,20.0,$8,$9)
             RETURNING id`,
            [siteId, portalDate, generatedBy, contentIds, contentIds.length,
             generationMethod, pool.length, '{}', JSON.stringify({ generated_at_utc: new Date().toISOString() })]
        );
        return { id: hp?.id, portal_type: 'homepage', content_ids: contentIds, item_count: contentIds.length, status: 'active', generation_method: generationMethod };
    }

    // Resolve rules
    const rules = await _resolveSelectionRules(siteId, taxonomyNodeId);

    // Get inclusive taxonomy subtree
    const nodeIds = taxonomyNodeId ? await getDescendantIds(pgPool, Number(taxonomyNodeId)) : [];
    if (!nodeIds.length) {
        return { portal_type: portalType, content_ids: [], item_count: 0, status: 'active' };
    }

    // Build content type filter
    const typeFilter = (Array.isArray(rules.content_type_filter) && rules.content_type_filter.length)
        ? rules.content_type_filter
        : ['article', 'devotional', 'scripture', 'story'];

    // Staleness exclusion clause
    const stalenessClause = rules.exclude_if_older_than_days
        ? `AND co.updated_at >= NOW() - INTERVAL '${parseInt(rules.exclude_if_older_than_days)} days'`
        : '';

    // Fetch candidate pool (up to 500)
    const poolRes = await pgPool.query(
        `SELECT co.id, co.title, co.object_type, co.created_at, co.updated_at,
                COALESCE((co.extension_data->>'editorial_rank')::int, 0) AS editorial_rank
         FROM jv_content_objects co
         JOIN jv_content_taxonomy_map ctm
           ON ctm.uuid_object_id = co.id AND ctm.taxonomy_node_id = ANY($1)
         WHERE co.object_type = ANY($2)
         ${stalenessClause}
         ORDER BY co.updated_at DESC
         LIMIT 500`,
        [nodeIds, typeFilter]
    );
    const pool = poolRes.rows;
    if (!pool.length) {
        return { portal_type: portalType, content_ids: [], item_count: 0, status: 'active' };
    }

    // Load yesterday's portal for anti-repetition weighting
    const yesterday = new Date(portalDate);
    yesterday.setDate(yesterday.getDate() - 1);
    const yd = yesterday.toISOString().slice(0, 10);
    const ydRes = await pgPool.query(
        `SELECT content_ids FROM portal_pages
         WHERE site_id=$1 AND portal_type=$2
           AND taxonomy_node_id IS NOT DISTINCT FROM $3
           AND portal_date=$4 AND status='active'`,
        [siteId, portalType, taxonomyNodeId, yd]
    );
    const yesterdayIds = new Set((ydRes.rows[0]?.content_ids ?? []).map(String));

    // Assign weights
    const boostCutoff = new Date(Date.now() - rules.boost_recent_days * 86400000);
    for (const item of pool) {
        let w = 1.0;
        if (new Date(item.updated_at) >= boostCutoff)           w *= 2.0;   // recency boost
        if (item.editorial_rank > 0)                             w *= 1.25;  // editorial boost
        if (!yesterdayIds.has(String(item.id)))                  w *= 1.5;   // anti-repetition
        item._weight = w;
    }

    // Seeded weighted sample
    const seed = _portalHashSeed(siteId, taxonomyNodeId, portalDate);
    const rng  = _makeSeededRng(seed);
    const targetCount = Math.min(
        rules.max_items,
        Math.max(rules.min_items, pool.length)
    );
    const selected = _weightedSample(pool, targetCount, rng);
    const contentIds = selected.map(r => r.id);

    // Calculate selection_percentage and item count per spec algorithm
    const selPct = rules.percentage ?? 20.0;
    const rawCount = Math.ceil(pool.length * selPct / 100);
    const specCount = pool.length < (rules.min_items ?? 5)
        ? pool.length
        : Math.max(rules.min_items ?? 5, Math.min(rules.max_items ?? 100, rawCount));

    const selectionConfig = {
        percentage: selPct,
        min_items: rules.min_items ?? 5,
        max_items: rules.max_items ?? 100,
        boost_recent_days: rules.boost_recent_days ?? 7,
        content_type_filter: typeFilter,
        require_featured_image: rules.require_featured_image ?? false,
    };

    // Build generation metadata for inspector panel
    const portalMetadata = {
        pool_size: pool.length,
        item_count: contentIds.length,
        generation_method: generationMethod,
        rules_applied: rules.id ?? null,
        generated_at_utc: new Date().toISOString(),
    };

    // Supersede any existing active portal (preserves audit trail), then insert new row
    await pgPool.query(
        `UPDATE portal_pages SET status='superseded', updated_at=NOW()
         WHERE site_id=$1 AND portal_type=$2
           AND taxonomy_node_id IS NOT DISTINCT FROM $3
           AND portal_date=$4 AND status='active'`,
        [siteId, portalType, taxonomyNodeId, portalDate]
    );
    const { rows: [newPortal] } = await pgPool.query(
        `INSERT INTO portal_pages
             (site_id, portal_type, taxonomy_node_id, portal_date, status, generated_by,
              content_ids, item_count, generation_method,
              pool_size, selection_percentage, selection_config, metadata)
         VALUES ($1,$2,$3,$4,'active',$5,$6,$7,$8,$9,$10,$11,$12)
         RETURNING id`,
        [siteId, portalType, taxonomyNodeId, portalDate, generatedBy,
         contentIds, contentIds.length, generationMethod,
         pool.length, selPct, JSON.stringify(selectionConfig), JSON.stringify(portalMetadata)]
    );

    // Audit log for auto-generated portals
    if (generationMethod === 'auto_on_demand') {
        logAuditEvent(pgPool, {
            event_type: 'portal.taxonomy.generated',
            actor_id: 'system',
            target_type: 'portal_pages',
            target_id: String(newPortal?.id ?? ''),
            details: { site_id: siteId, taxonomy_node_id: taxonomyNodeId, portal_date: portalDate, item_count: contentIds.length, pool_size: pool.length },
        });
    } else if (generationMethod === 'auto_scheduled' && portalType === 'homepage') {
        logAuditEvent(pgPool, {
            event_type: 'portal.homepage.generated',
            actor_id: 'system',
            target_type: 'portal_pages',
            target_id: String(newPortal?.id ?? ''),
            details: { site_id: siteId, portal_date: portalDate, item_count: contentIds.length },
        });
    }

    return { id: newPortal?.id, portal_type: portalType, content_ids: contentIds, item_count: contentIds.length, status: 'active', generation_method: generationMethod };
}

// POST /api/v1/portal/generate — Trigger on-demand portal page generation (publisher+)
app.post('/api/v1/portal/generate', async (req, res) => {
    const actor = await requirePrivileged(req, res); if (!actor) return;
    if (!hasPermission(actor.role, 'portal:manage')) return res.status(403).json({ error: 'Forbidden' });
    const { site_id, portal_type = 'topic', taxonomy_node_id = null, portal_date } = req.body || {};
    if (!site_id || !portal_date) {
        return res.status(400).json({ error: 'site_id and portal_date are required' });
    }
    try {
        const result = await _generatePortalPage(
            Number(site_id), String(portal_type),
            taxonomy_node_id != null ? Number(taxonomy_node_id) : null,
            String(portal_date), actor.id, 'manual'
        );
        res.json({ success: true, ...result });
    } catch (err) {
        console.error('[portal:generate]', err.message);
        res.status(500).json({ error: 'Portal generation failed' });
    }
});

// POST /api/v1/portal/generate-site — Generate homepage + all L2 category portals for a site in one call
// Body: { site_id, portal_date? }  (portal_date defaults to today UTC)
app.post('/api/v1/portal/generate-site', async (req, res) => {
    const actor = await requirePrivileged(req, res); if (!actor) return;
    if (!hasPermission(actor.role, 'portal:view')) return res.status(403).json({ error: 'Forbidden' });
    const { site_id, portal_date: reqDate } = req.body || {};
    if (!site_id) return res.status(400).json({ error: 'site_id required' });
    const portalDate = reqDate || new Date().toISOString().slice(0, 10);
    try {
        // Load site extensions to get root_category_ids
        const { rows: [site] } = await pgPool.query(
            `SELECT domain, extensions FROM jv_sites WHERE id=$1`, [Number(site_id)]
        );
        if (!site) return res.status(404).json({ error: 'Site not found' });
        const rootCatIds = site.extensions?.root_category_ids ?? [];
        if (!rootCatIds.length) return res.status(422).json({ error: 'Site has no root_category_ids configured in extensions' });

        const results = [];
        const errors  = [];

        // 1. Generate homepage portal
        try {
            const hp = await _generatePortalPage(Number(site_id), 'homepage', null, portalDate, actor.id, 'manual');
            results.push({ portal_type: 'homepage', taxonomy_node_id: null, ...hp });
        } catch (e) {
            errors.push({ portal_type: 'homepage', error: e.message });
            console.error('[portal:generate-site] homepage error:', e.message);
        }

        // 2. Discover L2 taxonomy nodes (direct children of each root category)
        const l2Rows = await pgPool.query(
            `SELECT id, name FROM jv_taxonomy WHERE parent_id = ANY($1) ORDER BY sort_order, name`,
            [rootCatIds]
        );

        // 3. Generate a topic portal for each L2 node
        for (const node of l2Rows.rows) {
            try {
                const tp = await _generatePortalPage(Number(site_id), 'topic', node.id, portalDate, actor.id, 'manual');
                results.push({ portal_type: 'topic', taxonomy_node_id: node.id, taxonomy_name: node.name, ...tp });
            } catch (e) {
                errors.push({ portal_type: 'topic', taxonomy_node_id: node.id, taxonomy_name: node.name, error: e.message });
                console.error(`[portal:generate-site] topic node ${node.id} error:`, e.message);
            }
        }

        console.log(`[portal:generate-site] site ${site_id} (${site.domain}): ${results.length} pages generated, ${errors.length} errors`);
        return res.json({
            success: true,
            site_id: Number(site_id),
            domain: site.domain,
            portal_date: portalDate,
            generated: results.length,
            errors: errors.length,
            pages: results,
        });
    } catch (err) {
        console.error('[portal:generate-site]', err.message);
        return res.status(500).json({ error: 'Site portal generation failed' });
    }
});

// POST /api/v1/admin/portal/regenerate — Regenerate a portal, superseding the existing active one (portal:manage)
// Body: { site_id, portal_type, taxonomy_node_id?, portal_date }
app.post('/api/v1/admin/portal/regenerate', async (req, res) => {
    const actor = await requirePrivileged(req, res); if (!actor) return;
    if (!hasPermission(actor.role, 'portal:manage')) return res.status(403).json({ error: 'Forbidden' });
    const { site_id, portal_type = 'taxonomy', taxonomy_node_id = null, portal_date } = req.body || {};
    if (!site_id || !portal_date) return res.status(400).json({ error: 'site_id and portal_date are required' });
    try {
        // Find the existing active portal ID for audit trail
        const { rows: [oldPortal] } = await pgPool.query(
            `SELECT id FROM portal_pages
             WHERE site_id=$1 AND portal_type=$2
               AND taxonomy_node_id IS NOT DISTINCT FROM $3
               AND portal_date=$4 AND status='active'`,
            [Number(site_id), String(portal_type),
             taxonomy_node_id != null ? Number(taxonomy_node_id) : null, String(portal_date)]
        );

        const result = await _generatePortalPage(
            Number(site_id), String(portal_type),
            taxonomy_node_id != null ? Number(taxonomy_node_id) : null,
            String(portal_date), actor.id, 'regenerated'
        );

        logAuditEvent(pgPool, {
            event_type: 'portal.regenerated',
            actor_id: actor.email,
            target_type: 'portal_pages',
            target_id: String(result.id ?? ''),
            details: { site_id, portal_type, taxonomy_node_id, portal_date, old_portal_id: oldPortal?.id ?? null },
            ip_address: req.ip,
            user_agent: req.get('user-agent'),
        });

        return res.json({ success: true, ...result });
    } catch (err) {
        console.error('[portal:admin:regenerate]', err.message);
        return res.status(500).json({ error: 'Portal regeneration failed' });
    }
});

// GET /api/v1/portal/taxonomy — On-demand serving of taxonomy portal compositions. Public (no auth).
// Query params: site_id (INT), taxonomy_node_id (INT), portal_date (YYYY-MM-DD)
// Flow: cache → DB → lock-guarded generation → cache + serve
app.get('/api/v1/portal/taxonomy', async (req, res) => {
    const { site_id, taxonomy_node_id, portal_date } = req.query;
    if (!site_id || !taxonomy_node_id || !portal_date) {
        return res.status(400).json({ error: 'site_id, taxonomy_node_id, and portal_date are required' });
    }
    const siteId = Number(site_id);
    const nodeId = Number(taxonomy_node_id);
    const date   = String(portal_date);

    // Step 1: In-memory cache check (~0ms)
    const cacheKey = `portal:${siteId}:${nodeId}:${date}`;
    const cached = _portalPageCache.get(cacheKey);
    if (cached) return res.json({ ...cached, cache_hit: true });

    // Step 2: Database check
    const selectCols = `id, portal_type, site_id, taxonomy_node_id, portal_date, status,
                        content_ids, item_count, generated_at, generation_method, hit_count`;
    try {
        const { rows } = await pgPool.query(
            `SELECT ${selectCols} FROM portal_pages
             WHERE site_id=$1 AND portal_type='taxonomy' AND taxonomy_node_id=$2
               AND portal_date=$3 AND status='active'
             LIMIT 1`,
            [siteId, nodeId, date]
        );
        if (rows[0]) {
            _portalPageCache.set(cacheKey, rows[0]);
            return res.json({ ...rows[0], cache_hit: false });
        }
    } catch (e) {
        console.error('[portal:taxonomy] DB check error', e.message);
        return res.status(500).json({ error: 'Database error' });
    }

    // Step 3+4: Lock-guarded on-demand generation (prevents duplicate rows from concurrent requests)
    const lockKey = `portal_gen:${siteId}:${nodeId}:${date}`;
    try {
        const result = await _withPortalGenLock(lockKey, 5_000, async () => {
            // Double-check inside lock — another waiter may have already generated
            const { rows } = await pgPool.query(
                `SELECT ${selectCols} FROM portal_pages
                 WHERE site_id=$1 AND portal_type='taxonomy' AND taxonomy_node_id=$2
                   AND portal_date=$3 AND status='active' LIMIT 1`,
                [siteId, nodeId, date]
            );
            if (rows[0]) return rows[0];

            // Generate (auto_on_demand — no authenticated user)
            await _generatePortalPage(siteId, 'taxonomy', nodeId, date, null, 'auto_on_demand');

            // Fetch the newly inserted row to include id + generated_at
            const { rows: [fresh] } = await pgPool.query(
                `SELECT ${selectCols} FROM portal_pages
                 WHERE site_id=$1 AND portal_type='taxonomy' AND taxonomy_node_id=$2
                   AND portal_date=$3 AND status='active' LIMIT 1`,
                [siteId, nodeId, date]
            );
            return fresh ?? null;
        });
        if (!result) return res.status(500).json({ error: 'Portal generation returned empty' });
        _portalPageCache.set(cacheKey, result);
        return res.json({ ...result, cache_hit: false });
    } catch (e) {
        console.error('[portal:taxonomy] generation error', e.message);
        return res.status(500).json({ error: 'Portal generation failed' });
    }
});

// POST /api/v1/portal/:portalId/hit — Record a portal page view. Public (no auth). Returns 204.
app.post('/api/v1/portal/:portalId/hit', async (req, res) => {
    const { portalId } = req.params;

    // Bot filter — silently drop known automated traffic
    const ua = req.headers['user-agent'] || '';
    if (BOT_UA_RE.test(ua)) return res.status(204).end();

    // Per-IP + portal rate limit: 1 hit per 60 seconds
    const ip    = req.ip || req.connection?.remoteAddress || '';
    const rlKey = `${ip}:${portalId}`;
    const last  = _portalHitRlMap.get(rlKey) ?? 0;
    if (Date.now() - last < 60_000) return res.status(429).end();
    _portalHitRlMap.set(rlKey, Date.now());

    // Buffer the hit for batch flush
    _portalHitBuffer.set(portalId, (_portalHitBuffer.get(portalId) ?? 0) + 1);

    return res.status(204).end();
});

// GET /api/v1/portal/sites — distinct sites that have portal compositions (portal:view)
app.get('/api/v1/portal/sites', async (req, res) => {
    const actor = await requirePrivileged(req, res); if (!actor) return;
    if (!hasPermission(actor.role, 'portal:view')) return res.status(403).json({ error: 'Forbidden' });
    try {
        // Return ALL registered sites (not just those with existing portal pages)
        // so sites appear in the dropdown from day 1, before any pages are generated.
        // jv_sites has no 'name' column — use domain as the display name.
        const { rows } = await pgPool.query(
            `SELECT s.id AS site_id, s.domain AS site_name
             FROM jv_sites s
             WHERE s.status != 'archived'
             ORDER BY s.id`
        );
        return res.json(rows);
    } catch (e) {
        console.error('[portal:sites]', e.message);
        return res.status(500).json({ error: 'Database error' });
    }
});

// GET /api/v1/portal/tree?site_id=X — portals grouped year→month→day (portal:view)
app.get('/api/v1/portal/tree', async (req, res) => {
    const actor = await requirePrivileged(req, res); if (!actor) return;
    if (!hasPermission(actor.role, 'portal:view')) return res.status(403).json({ error: 'Forbidden' });
    const siteId = Number(req.query.site_id);
    if (!siteId) return res.status(400).json({ error: 'site_id required' });
    try {
        const { rows } = await pgPool.query(
            `SELECT pp.id, pp.portal_type, pp.taxonomy_node_id,
                    TO_CHAR(pp.portal_date, 'YYYY-MM-DD') AS portal_date,
                    pp.item_count, pp.hit_count, pp.status, pp.generation_method,
                    t.name AS taxonomy_name
             FROM portal_pages pp
             LEFT JOIN jv_taxonomy t ON t.id = pp.taxonomy_node_id
             WHERE pp.site_id=$1 AND pp.status='active'
             ORDER BY pp.portal_date DESC, pp.portal_type`,
            [siteId]
        );
        const tree = {};
        for (const row of rows) {
            const [year, month, day] = row.portal_date.split('-');
            if (!tree[year]) tree[year] = {};
            if (!tree[year][month]) tree[year][month] = {};
            if (!tree[year][month][day]) tree[year][month][day] = [];
            tree[year][month][day].push(row);
        }
        return res.json(tree);
    } catch (e) {
        console.error('[portal:tree]', e.message);
        return res.status(500).json({ error: 'Database error' });
    }
});

// GET /api/v1/portal/pages?site_id=X[&portal_date=YYYY-MM-DD][&portal_type=T] (portal:view)
app.get('/api/v1/portal/pages', async (req, res) => {
    const actor = await requirePrivileged(req, res); if (!actor) return;
    if (!hasPermission(actor.role, 'portal:view')) return res.status(403).json({ error: 'Forbidden' });
    const { site_id, portal_date, portal_type } = req.query;
    if (!site_id) return res.status(400).json({ error: 'site_id required' });
    const params = [Number(site_id)];
    const clauses = ['pp.site_id=$1', "pp.status='active'"];
    if (portal_date) { params.push(String(portal_date)); clauses.push(`pp.portal_date=$${params.length}`); }
    if (portal_type) { params.push(String(portal_type)); clauses.push(`pp.portal_type=$${params.length}`); }
    try {
        const { rows } = await pgPool.query(
            `SELECT pp.id, pp.site_id, pp.portal_type, pp.taxonomy_node_id,
                    TO_CHAR(pp.portal_date, 'YYYY-MM-DD') AS portal_date,
                    pp.item_count, pp.hit_count, pp.status, pp.generation_method, pp.generated_at,
                    t.name AS taxonomy_name
             FROM portal_pages pp
             LEFT JOIN jv_taxonomy t ON t.id = pp.taxonomy_node_id
             WHERE ${clauses.join(' AND ')}
             ORDER BY pp.portal_date DESC, pp.portal_type`,
            params
        );
        return res.json(rows);
    } catch (e) {
        console.error('[portal:pages]', e.message);
        return res.status(500).json({ error: 'Database error' });
    }
});

// GET /api/v1/portal/pages/:portalId — full detail: metadata + items + 24h timeseries (portal:view)
app.get('/api/v1/portal/pages/:portalId', async (req, res) => {
    const actor = await requirePrivileged(req, res); if (!actor) return;
    if (!hasPermission(actor.role, 'portal:view')) return res.status(403).json({ error: 'Forbidden' });
    const { portalId } = req.params;
    try {
        const { rows: [portal] } = await pgPool.query(
            `SELECT pp.id, pp.site_id, pp.portal_type, pp.taxonomy_node_id,
                    TO_CHAR(pp.portal_date, 'YYYY-MM-DD') AS portal_date,
                    pp.item_count, pp.hit_count, pp.status, pp.generation_method, pp.generated_at,
                    pp.content_ids, pp.pool_size, pp.selection_percentage, pp.selection_config, pp.metadata,
                    t.name AS taxonomy_name
             FROM portal_pages pp
             LEFT JOIN jv_taxonomy t ON t.id = pp.taxonomy_node_id
             WHERE pp.id=$1`,
            [portalId]
        );
        if (!portal) return res.status(404).json({ error: 'Portal not found' });

        const contentItems = (portal.content_ids && portal.content_ids.length)
            ? (await pgPool.query(
                `SELECT co.id, co.title, co.excerpt,
                        co.extension_data->>'cached_image_path' AS cached_image_path,
                        co.extension_data->>'image_url' AS image_url,
                        co.published_at
                 FROM jv_content_objects co
                 WHERE co.id = ANY($1::uuid[])`,
                [portal.content_ids]
              )).rows
            : [];

        const { rows: timeseries } = await pgPool.query(
            `SELECT hour_bucket, hit_count
             FROM portal_hit_timeseries
             WHERE portal_id=$1 AND hour_bucket >= NOW() - INTERVAL '24 hours'
             ORDER BY hour_bucket`,
            [portalId]
        );

        return res.json({ ...portal, items: contentItems, timeseries });
    } catch (e) {
        console.error('[portal:detail]', e.message);
        return res.status(500).json({ error: 'Database error' });
    }
});

// PATCH /api/v1/portal/pages/:portalId/items — manual composition override (portal:manage)
app.patch('/api/v1/portal/pages/:portalId/items', async (req, res) => {
    const actor = await requirePrivileged(req, res); if (!actor) return;
    if (!hasPermission(actor.role, 'portal:manage')) return res.status(403).json({ error: 'Forbidden' });
    const { portalId } = req.params;
    const { content_ids } = req.body || {};
    if (!Array.isArray(content_ids)) return res.status(400).json({ error: 'content_ids must be an array' });
    if (content_ids.length > 200) return res.status(400).json({ error: 'content_ids max 200 items' });
    try {
        if (content_ids.length) {
            const { rows } = await pgPool.query(
                `SELECT id FROM jv_content_objects WHERE id = ANY($1::uuid[])`,
                [content_ids]
            );
            if (rows.length !== content_ids.length) {
                return res.status(422).json({ error: 'One or more content_ids not found' });
            }
        }
        const overrideMeta = JSON.stringify({ manual_override: true, override_by: actor.id, override_at: new Date().toISOString() });
        await pgPool.query(
            `UPDATE portal_pages
             SET content_ids=$1, item_count=$2,
                 metadata = COALESCE(metadata, '{}'::jsonb) || $3::jsonb
             WHERE id=$4`,
            [JSON.stringify(content_ids), content_ids.length, overrideMeta, portalId]
        );
        return res.json({ ok: true, item_count: content_ids.length });
    } catch (e) {
        console.error('[portal:patchItems]', e.message);
        return res.status(500).json({ error: 'Database error' });
    }
});

