// POST /api/v1/websites/:siteId/taxonomy/reorder — swap display_order (website:manage)
// NOTE: must be registered BEFORE /:assignmentId to avoid route collision
app.post('/api/v1/websites/:siteId/taxonomy/reorder', async (req, res) => {
    const actor = await requirePrivileged(req, res); if (!actor) return;
    if (!hasPermission(actor.role, 'website:manage')) return res.status(403).json({ error: 'Forbidden' });
    const { siteId } = req.params;
    const { id, direction } = req.body || {};
    if (!id || !['up', 'down'].includes(direction)) return res.status(400).json({ error: 'id and direction (up|down) required' });
    try {
        const { rows } = await pgPool.query(
            `SELECT id, display_order FROM website_taxonomy_map WHERE site_id=$1 ORDER BY display_order ASC, assigned_at ASC`,
            [siteId]
        );
        const idx = rows.findIndex(r => r.id === id);
        if (idx < 0) return res.status(404).json({ error: 'Assignment not found' });
        const swapIdx = direction === 'up' ? idx - 1 : idx + 1;
        if (swapIdx < 0 || swapIdx >= rows.length) return res.status(422).json({ error: 'Already at boundary' });

        const a = rows[idx];
        const b = rows[swapIdx];
        const orderA = a.display_order;
        const orderB = b.display_order;

        // Swap orders — if equal, use index-based values
        const newA = orderA !== orderB ? orderB : (direction === 'up' ? orderA - 1 : orderA + 1);
        const newB = orderA !== orderB ? orderA : (direction === 'up' ? orderB + 1 : orderB - 1);

        await pgPool.query(`UPDATE website_taxonomy_map SET display_order=$1 WHERE id=$2`, [newA, a.id]);
        await pgPool.query(`UPDATE website_taxonomy_map SET display_order=$1 WHERE id=$2`, [newB, b.id]);
        return res.json({ ok: true });
    } catch (e) {
        console.error('[websites:taxonomy:reorder]', e.message);
        return res.status(500).json({ error: 'Database error' });
    }
});

// POST /api/v1/websites/:siteId/taxonomy — assign taxonomy node (website:manage)
app.post('/api/v1/websites/:siteId/taxonomy', async (req, res) => {
    const actor = await requirePrivileged(req, res); if (!actor) return;
    if (!hasPermission(actor.role, 'website:manage')) return res.status(403).json({ error: 'Forbidden' });
    const { siteId } = req.params;
    const { taxonomy_node_id, nav_position = 'primary_nav', custom_label = null, is_featured = false } = req.body || {};
    if (!taxonomy_node_id) return res.status(400).json({ error: 'taxonomy_node_id required' });

    try {
        // Check site exists and get max_taxonomy_assignments config
        const { rows: [site] } = await pgPool.query(
            `SELECT id, extension_data FROM jv_content_objects WHERE id=$1 AND object_type='site'`,
            [siteId]
        );
        if (!site) return res.status(404).json({ error: 'Site not found' });

        const maxAssignments = parseInt((site.extension_data || {}).max_taxonomy_assignments, 10) || 12;

        // Count current assignments
        const { rows: [{ count }] } = await pgPool.query(
            `SELECT COUNT(*) FROM website_taxonomy_map WHERE site_id=$1`,
            [siteId]
        );
        if (parseInt(count, 10) >= maxAssignments) {
            return res.status(422).json({ error: `Maximum ${maxAssignments} taxonomy assignments allowed for this site` });
        }

        // Get next display_order
        const { rows: [{ max_order }] } = await pgPool.query(
            `SELECT COALESCE(MAX(display_order), -1) AS max_order FROM website_taxonomy_map WHERE site_id=$1`,
            [siteId]
        );
        const display_order = parseInt(max_order, 10) + 1;

        const { rows: [assignment] } = await pgPool.query(
            `INSERT INTO website_taxonomy_map
                 (site_id, taxonomy_node_id, display_order, is_featured, custom_label, nav_position, assigned_by)
             VALUES ($1,$2,$3,$4,$5,$6,$7)
             RETURNING *`,
            [siteId, Number(taxonomy_node_id), display_order, Boolean(is_featured), custom_label, nav_position, actor.id ?? null]
        );

        // Join taxonomy name
        const { rows: [taxRow] } = await pgPool.query(
            `SELECT name, slug FROM jv_taxonomy WHERE id=$1`,
            [Number(taxonomy_node_id)]
        );
        logAuditEvent(pgPool, {
            event_type: 'site.taxonomy_assigned',
            actor_id: actor.email,
            target_type: 'website_taxonomy_map',
            target_id: String(siteId),
            details: { site_id: siteId, taxonomy_node_id, taxonomy_name: taxRow?.name ?? '', assigned_by: actor.email },
            ip_address: req.ip,
            user_agent: req.get('user-agent'),
        });
        return res.status(201).json({ ...assignment, name: taxRow?.name ?? '', slug: taxRow?.slug ?? '' });
    } catch (e) {
        if (e.code === '23505') return res.status(409).json({ error: 'Taxonomy node already assigned to this site' });
        console.error('[websites:taxonomy:assign]', e.message);
        return res.status(500).json({ error: 'Database error' });
    }
});

// PATCH /api/v1/websites/:siteId/taxonomy/:assignmentId — update assignment (website:manage)
app.patch('/api/v1/websites/:siteId/taxonomy/:assignmentId', async (req, res) => {
    const actor = await requirePrivileged(req, res); if (!actor) return;
    if (!hasPermission(actor.role, 'website:manage')) return res.status(403).json({ error: 'Forbidden' });
    const { siteId, assignmentId } = req.params;
    const { custom_label, nav_position, is_featured } = req.body || {};

    const sets = [];
    const params = [];
    if (custom_label !== undefined) { params.push(custom_label); sets.push(`custom_label=$${params.length}`); }
    if (nav_position !== undefined) { params.push(nav_position); sets.push(`nav_position=$${params.length}`); }
    if (is_featured !== undefined)  { params.push(Boolean(is_featured)); sets.push(`is_featured=$${params.length}`); }
    if (!sets.length) return res.status(400).json({ error: 'No fields to update' });

    params.push(assignmentId);
    params.push(siteId);
    try {
        const { rows: [row] } = await pgPool.query(
            `UPDATE website_taxonomy_map SET ${sets.join(', ')} WHERE id=$${params.length - 1} AND site_id=$${params.length} RETURNING *`,
            params
        );
        if (!row) return res.status(404).json({ error: 'Assignment not found' });
        return res.json(row);
    } catch (e) {
        console.error('[websites:taxonomy:update]', e.message);
        return res.status(500).json({ error: 'Database error' });
    }
});

