// PUT /api/v1/websites/:siteId/pages/:pageId — update page (website:manage)
app.put('/api/v1/websites/:siteId/pages/:pageId', async (req, res) => {
    const actor = await requirePrivileged(req, res); if (!actor) return;
    if (!hasPermission(actor.role, 'website:manage')) return res.status(403).json({ error: 'Forbidden' });
    const { siteId, pageId } = req.params;
    const { page_slug, page_title, body_html, body_markdown, nav_position, display_order, status, seo_metadata } = req.body || {};
    const sets = ['updated_at=NOW()', 'version=version+1'];
    const params = [];
    const push = (v) => { params.push(v); return `$${params.length}`; };
    if (page_slug    !== undefined) sets.push(`page_slug=${push(page_slug)}`);
    if (page_title   !== undefined) sets.push(`page_title=${push(page_title)}`);
    if (body_html    !== undefined) sets.push(`body_html=${push(body_html)}`);
    if (body_markdown !== undefined) sets.push(`body_markdown=${push(body_markdown)}`);
    if (nav_position !== undefined) sets.push(`nav_position=${push(nav_position)}`);
    if (display_order !== undefined) sets.push(`display_order=${push(display_order)}`);
    if (status       !== undefined) sets.push(`status=${push(status)}`);
    if (seo_metadata !== undefined) sets.push(`seo_metadata=${push(JSON.stringify(seo_metadata))}`);
    params.push(pageId);
    params.push(siteId);
    try {
        const { rows: [page] } = await pgPool.query(
            `UPDATE website_pages SET ${sets.join(', ')} WHERE id=$${params.length - 1} AND site_id=$${params.length} RETURNING *`,
            params
        );
        if (!page) return res.status(404).json({ error: 'Page not found' });
        logAuditEvent(pgPool, {
            event_type: 'site.page_updated',
            actor_id: actor.email,
            target_type: 'website_pages',
            target_id: String(siteId),
            details: { site_id: siteId, page_slug: page.page_slug, page_id: pageId, version: page.version },
            ip_address: req.ip,
            user_agent: req.get('user-agent'),
        });
        return res.json(page);
    } catch (e) {
        if (e.code === '23505') return res.status(409).json({ error: 'A page with this slug already exists on this site' });
        console.error('[websites:pages:update]', e.message);
        return res.status(500).json({ error: 'Database error' });
    }
});

