// GET /api/v1/sites/:domain/portal — active portal for today (API key required)
app.get('/api/v1/sites/:domain/portal', async (req, res) => {
    const key = await requireApiKey(req, res); if (!key) return;
    const { domain } = req.params;
    const { date, type = 'homepage', taxonomy_slug } = req.query;
    try {
        const portalDate = date || getPstDateString();
        const { rows: [site] } = await pgPool.query(
            `SELECT id FROM jv_content_objects
             WHERE object_type='site' AND extension_data->>'domain'=$1 AND status='published'`,
            [domain]
        );
        if (!site) return res.status(404).json({ error: 'Site not found' });

        const params = [site.id, portalDate, type];
        let q = `SELECT pp.*, t.name AS taxonomy_name
                 FROM portal_pages pp
                 LEFT JOIN jv_taxonomy t ON t.id = pp.taxonomy_node_id
                 WHERE pp.site_id=$1 AND pp.portal_date=$2 AND pp.portal_type=$3 AND pp.status='active'`;
        if (taxonomy_slug) {
            q += ` AND EXISTS (SELECT 1 FROM jv_taxonomy tx WHERE tx.id=pp.taxonomy_node_id AND tx.slug=$4)`;
            params.push(taxonomy_slug);
        }
        const { rows: [portal] } = await pgPool.query(q, params);
        if (!portal) return res.status(404).json({ error: 'No active portal found' });

        const { rows: items } = portal.content_ids && portal.content_ids.length
            ? await pgPool.query(
                `SELECT id, title, excerpt, cached_image_path, image_url, published_at
                 FROM jv_content_objects WHERE id = ANY($1::uuid[])`,
                [portal.content_ids])
            : { rows: [] };

        return res.json({ ...portal, items });
    } catch (e) {
        console.error('[sites:portal]', e.message);
        return res.status(500).json({ error: 'Database error' });
    }
});

