// POST /api/v1/sites/:siteId/sync/report — satellite reports sync status (requireApiKey)
app.post('/api/v1/sites/:siteId/sync/report', requireApiKey, async (req, res) => {
    const { siteId } = req.params;
    const { satellite_version, current_package_version, current_update_version, sync_status,
            updates_applied, sync_timestamp, error_message } = req.body;
    try {
        const ip = req.ip;
        // Upsert satellite_sync_status
        await pgPool.query(
            `INSERT INTO satellite_sync_status
               (site_id, last_check_at, last_sync_at, current_package_version, current_update_version,
                sync_status, consecutive_failures, last_error, ip_address, updated_at)
             VALUES ($1, NOW(), CASE WHEN $2='in_sync' THEN NOW() ELSE NULL END, $3, $4, $5,
                     CASE WHEN $2='error' THEN COALESCE((SELECT consecutive_failures FROM satellite_sync_status WHERE site_id=$1)+1, 1) ELSE 0 END,
                     $6, $7::inet, NOW())
             ON CONFLICT (site_id) DO UPDATE SET
               last_check_at = NOW(),
               last_sync_at = CASE WHEN $2='in_sync' THEN NOW() ELSE satellite_sync_status.last_sync_at END,
               current_package_version = COALESCE($3, satellite_sync_status.current_package_version),
               current_update_version = COALESCE($4, satellite_sync_status.current_update_version),
               sync_status = $5,
               consecutive_failures = CASE WHEN $2='error' THEN satellite_sync_status.consecutive_failures+1 ELSE 0 END,
               last_error = CASE WHEN $2='error' THEN $6 ELSE NULL END,
               ip_address = $7::inet,
               updated_at = NOW()`,
            [siteId, sync_status ?? 'in_sync', current_package_version ?? null,
             current_update_version ?? null, sync_status ?? 'in_sync',
             error_message ?? null, ip ?? null]
        );
        logAuditEvent(pgPool, {
            event_type: 'satellite.sync_reported',
            actor_id: 'satellite',
            target_type: 'jv_content_objects',
            target_id: siteId,
            details: { site_id: siteId, updates_applied, sync_status, current_package_version, current_update_version },
            ip_address: req.ip,
            user_agent: req.get('user-agent'),
        });
        return res.json({ ok: true });
    } catch (e) {
        console.error('[satellite:sync:report]', e.message);
        return res.status(500).json({ error: 'Database error' });
    }
});

// GET /api/v1/admin/satellite/sync-status/:siteId — view satellite sync status (satellite:view_status)
app.get('/api/v1/admin/satellite/sync-status/:siteId', async (req, res) => {
    const actor = await requirePrivileged(req, res); if (!actor) return;
    if (!hasPermission(actor.role, 'satellite:view_status')) return res.status(403).json({ error: 'Forbidden' });
    const { siteId } = req.params;
    try {
        const { rows: [status] } = await pgPool.query(
            `SELECT sss.*,
                (SELECT COUNT(*) FROM satellite_updates su WHERE su.site_id=$1 AND su.status='ready') AS pending_updates
             FROM satellite_sync_status sss WHERE sss.site_id=$1`,
            [siteId]
        );
        if (!status) return res.json({ sync_status: 'unknown', site_id: siteId, pending_updates: 0 });
        // Mark as unknown if no check-in for 24h
        if (status.last_check_at) {
            const hoursSinceCheck = (Date.now() - new Date(status.last_check_at).getTime()) / 3600000;
            if (hoursSinceCheck > 24 && status.sync_status !== 'error') {
                status.sync_status = 'unknown';
            }
        }
        return res.json(status);
    } catch (e) {
        console.error('[satellite:sync-status]', e.message);
        return res.status(500).json({ error: 'Database error' });
    }
});

