// POST /api/v1/images/studio/:jobId/ingest — store a studio-generated image (image:generate)
//
// Takes the raw bytes as application/octet-stream, not base64 JSON: the global
// express.json() cap is 100kb, well under a hero image, and raw bytes also skip
// base64's 33% overhead. The larger cap stays scoped to this one route.
app.post('/api/v1/images/studio/:jobId/ingest',
    express.raw({ type: 'application/octet-stream', limit: '25mb' }),
    async (req, res) => {
        const actor = await requirePrivileged(req, res); if (!actor) return;
        if (!hasPermission(actor.role, 'image:generate')) return res.status(403).json({ error: 'Forbidden' });
        const { jobId } = req.params;

        const buf = Buffer.isBuffer(req.body) ? req.body : null;
        if (!buf || buf.length === 0) {
            return res.status(400).json({ error: 'Empty body — POST raw image bytes as application/octet-stream' });
        }
        // Same blank-render guard the local GPU worker uses (gen_image_worker.py).
        if (buf.length < 10 * 1024) {
            return res.status(400).json({ error: `Image too small (${buf.length} bytes) — likely a blank or partial render` });
        }
        const ext = _sniffImageExt(buf);
        if (!ext) return res.status(415).json({ error: 'Unrecognised image data (expected webp, png or jpeg)' });

        try {
            const { rows: [job] } = await pgPool.query(
                `SELECT id, content_object_id, image_status FROM image_generation_jobs WHERE id=$1`, [jobId]
            );
            if (!job) return res.status(404).json({ error: 'Job not found' });
            if (job.image_status === 'approved') {
                return res.status(409).json({ error: 'Job is already approved — requeue it before replacing the image' });
            }

            const slug = String(job.content_object_id || jobId).replace(/-/g, '').slice(0, 12);
            const filename = `studio-${slug}-${Date.now()}.${ext}`;
            const publicPath = `/images/generated/${filename}`;
            const destDir = path.join(__dirname, 'public', 'images', 'generated');
            fs.mkdirSync(destDir, { recursive: true });
            fs.writeFileSync(path.join(destDir, filename), buf);

            await pgPool.query(
                `UPDATE image_generation_jobs SET
                   gpu_job_status='completed', image_url=$2, image_status='in_review',
                   gpu_response=$3, updated_at=NOW()
                 WHERE id=$1`,
                [jobId, publicPath, JSON.stringify({
                    source: 'article-image-studio', operator: actor.email, bytes: buf.length, format: ext,
                })]
            );

            console.log(`[images:studio:ingest] ${jobId} → ${publicPath} (${buf.length} bytes, by ${actor.email})`);
            logAuditEvent(pgPool, {
                event_type: 'image.generation_completed',
                actor_id: actor.email,
                target_type: 'image_generation_jobs',
                target_id: jobId,
                details: { job_id: jobId, model: 'article-image-studio', image_path: publicPath, bytes: buf.length },
                ip_address: req.ip,
                user_agent: req.get('user-agent'),
            });

            return res.status(201).json({
                id: jobId, image_url: publicPath, bytes: buf.length, format: ext, image_status: 'in_review',
            });
        } catch (e) {
            console.error('[images:studio:ingest]', e.message);
            return res.status(500).json({ error: 'Could not store the image' });
        }
    });

/**
 * Analyze article using Mistral-7B to extract 9 visual dimensions.
 * Returns: { sentiment, metaphors, thesis, climactic_moment, human_action, environment, era_tone, biblical_scene, biblical_character }
 */
async function _analyzeArticleForVisuals(title, bodyText, taxonomyName) {
    const systemMsg = `You are an expert in visual storytelling and cinematic composition. Analyze the article and extract nine key dimensions that will guide image generation. Return a valid JSON object with exactly these keys: sentiment, dominant_metaphors, thesis, climactic_moment, human_action, environment, era_tone, biblical_scene, biblical_character. All values should be brief strings (under 50 words each). Be specific to the article content.`;
    const userMsg = `Article Title: "${title}"\n\nCategory: ${taxonomyName || 'General'}\n\nContent excerpt:\n${bodyText.substring(0, 1000)}`;
    try {
        const response = await callICLLMChat([{ role: 'user', content: userMsg }], { maxTokens: 900, temperature: 0.5 });
        if (response?.choices?.[0]?.message?.content) {
            const content = response.choices[0].message.content;
            const jsonMatch = content.match(/\{[\s\S]*\}/);
            if (jsonMatch) {
                const analysis = JSON.parse(jsonMatch[0]);
                return analysis;
            }
        }
    } catch (err) {
        console.warn('[analyzeArticleForVisuals] Mistral analysis failed:', err.message);
    }
    return null;
}

/**
 * Build cinematic image prompt with diversity constraints.
 * Uses 9-dimension analysis + rolling diversity history to prevent repetition.
 */
async function _buildMidjourneyPrompt(analysis, title, taxonomyName, recentPrompts = [], demographicHistory = []) {
    const sentiment = analysis?.sentiment || 'uplifting, hopeful';
    const metaphors = analysis?.dominant_metaphors || 'light, faith, restoration';
    const humanAction = analysis?.human_action || 'standing firm in faith';
    const environment = analysis?.environment || 'peaceful natural setting';
    const era = analysis?.era_tone || 'timeless';
    const biblicalScene = analysis?.biblical_scene;

    // Rotate demographics to prevent repetition
    const demographics = [
        'Black man, mid-30s', 'White woman, mid-40s', 'Asian woman, mid-20s', 'Hispanic man, early 40s',
        'Middle Eastern woman, elderly', 'South Asian man, young adult', 'Indigenous woman, mid-30s', 'African man, mid-50s'
    ];
    const lastDemo = demographicHistory[demographicHistory.length - 1] || '';
    const nextDemo = demographics.find(d => !demographicHistory.includes(d)) || demographics[Math.floor(Math.random() * demographics.length)];

    // Rotate environments to prevent repetition
    const environments = [
        'modern urban street', 'mountain wilderness', 'beach at sunrise', 'forest clearing',
        'simple home interior', 'ancient temple ruins', 'desert landscape', 'peaceful garden',
        'riverbank', 'marketplace', 'countryside farm', 'candlelit room'
    ];
    const lastEnv = recentPrompts[recentPrompts.length - 1]?.match(/in a (.+?)(?:\.|,)/)?.[1] || '';
    const nextEnv = environments.find(e => !lastEnv.includes(e)) || environments[Math.floor(Math.random() * environments.length)];

    // Rotate viewpoints
    const viewpoints = [
        'wide establishing shot, expansive landscape',
        'medium shot, subject prominent, detailed expressions',
        'close portrait, emotional intensity',
        'three-quarter figure shot, full body language',
        'environmental portrait, subject in context'
    ];
    const nextViewpoint = viewpoints[recentPrompts.length % viewpoints.length];

    // Build the prompt - focus on positive visual qualities only
    let prompt = `Create a photorealistic cinematic image in 16:9 landscape format. `;

    if (biblicalScene) {
        prompt += `Biblical historical scene: ${biblicalScene}. `;
        prompt += `Period-accurate clothing and architecture. No modern elements. `;
    } else {
        prompt += `Subject: ${nextDemo}, ${humanAction}. `;
        prompt += `Setting: ${nextEnv}. `;
    }

    prompt += `Mood: ${sentiment}. `;
    prompt += `Style: editorial photography, DSLR, museum-quality, highly detailed. `;
    prompt += `Composition: ${nextViewpoint}. `;
    prompt += `Lighting: natural, cinematic, warm tones. `;

    return prompt;
}

/**
 * Negative prompt to prevent common artifacts and unwanted elements.
 * NOTE: DO NOT mention text, watermarks, logos, or writing — these mentions CAUSE text to appear.
 * Focus only on visual quality issues and unwanted styles.
 */
function _buildMidjourneyNegativePrompt() {
    return 'extra limbs, deformed hands, mutated anatomy, distorted joints, duplicate body parts, artificial render, painting, illustration, drawing, sketch, stock photo, blurry, low quality, oversaturated, flat lighting, generic, clichéd, cartoon, anime, 3d render, digital art, fake, artificial, low res, pixelated';
}

// POST /api/v1/images/generate — submit generation request(s) using Jubilee MidJourney API (image:generate)
app.post('/api/v1/images/generate', async (req, res) => {
    const actor = await requirePrivileged(req, res); if (!actor) return;
    if (!hasPermission(actor.role, 'image:generate')) return res.status(403).json({ error: 'Forbidden' });
    const { content_object_ids, aspect_ratio = '16:9', style_constraints, site_id } = req.body;
    if (!Array.isArray(content_object_ids) || !content_object_ids.length) {
        return res.status(400).json({ error: 'content_object_ids array required' });
    }
    if (content_object_ids.length > 50) return res.status(422).json({ error: 'Max 50 items per batch' });

    // Track visual diversity globally
    if (!global._imageGenerationHistory) global._imageGenerationHistory = { recentPrompts: [], demographicHistory: [] };

    const created = [];
    for (const contentObjectId of content_object_ids) {
        try {
            // Fetch content for prompt extraction
            const { rows: [obj] } = await pgPool.query(
                `SELECT co.id, co.title, co.body_html, co.extension_data,
                   t.name AS taxonomy_name
                 FROM jv_content_objects co
                 LEFT JOIN jv_content_taxonomy_map ctm ON ctm.object_id::text = co.id::text
                 LEFT JOIN jv_taxonomy t ON t.id = ctm.taxonomy_node_id
                 WHERE co.id = $1 LIMIT 1`,
                [contentObjectId]
            );
            if (!obj) continue;

            // Extract body text for analysis
            const bodyText = (obj.body_html || '').replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim();

            // Stage 1: Analyze article using Mistral to extract 9 dimensions
            console.log(`[images:generate] Analyzing article "${obj.title}" for visual dimensions...`);
            const analysis = await _analyzeArticleForVisuals(obj.title, bodyText, obj.taxonomy_name);

            // Stage 2: Build cinematic prompt with diversity constraints
            const prompt = await _buildMidjourneyPrompt(
                analysis,
                obj.title,
                obj.taxonomy_name,
                global._imageGenerationHistory.recentPrompts,
                global._imageGenerationHistory.demographicHistory
            );
            const negativePrompt = _buildMidjourneyNegativePrompt();

            const jobId = require('crypto').randomUUID();
            const callbackUrl = `${process.env.APP_BASE_URL || 'https://jubileeverse.com'}/api/v1/images/webhook`;

            // Insert job record
            const { rows: [job] } = await pgPool.query(
                `INSERT INTO image_generation_jobs
                   (id, content_object_id, site_id, prompt_context, style_constraints, aspect_ratio,
                    gpu_job_status, image_status, requested_by, created_at, updated_at)
                 VALUES ($1, $2, $3, $4, $5, $6, 'submitted', 'generating', $7, NOW(), NOW())
                 RETURNING *`,
                [jobId, contentObjectId, site_id ?? null, prompt,
                 JSON.stringify(analysis || {}), aspect_ratio, actor.email]
            );
            created.push(job);

            // Submit to Jubilee MidJourney API asynchronously
            (async () => {
                try {
                    console.log(`[images:generate] ========== STARTING IMAGE GENERATION ==========`);
                    console.log(`[images:generate] Job ID: ${jobId}`);
                    console.log(`[images:generate] Content Object ID: ${contentObjectId}`);
                    console.log(`[images:generate] Positive Prompt (first 300 chars):\n${prompt.slice(0, 300)}`);
                    console.log(`[images:generate] Negative Prompt:\n${negativePrompt}`);

                    console.log(`[images:generate] Calling MidJourney API...`);
                    const mjResult = await callMidjourneyGenerate(prompt, negativePrompt);
                    console.log(`[images:generate] MidJourney response received:`, JSON.stringify(mjResult).slice(0, 500));

                    if (!mjResult?.job_id) {
                        throw new Error(`Invalid MidJourney response: missing job_id. Got: ${JSON.stringify(mjResult).slice(0, 200)}`);
                    }

                    // Download the generated image from IC API using the job_id
                    const slug = contentObjectId.replace(/-/g, '').slice(0, 12);
                    const filename = `jubilee-generated-${slug}-${Date.now()}.jpg`;
                    const publicPath = `/images/generated/${filename}`;
                    const destPath = require('path').join(__dirname, 'public', 'images', 'generated', filename);

                    console.log(`[images:generate] Downloading image for job ${mjResult.job_id} to ${destPath}`);

                    // Poll job status until complete or timeout (up to 5 minutes)
                    let jobStatus;
                    let attempts = 0;
                    const maxAttempts = 60; // 5 minutes at 5-second intervals

                    console.log(`[images:generate] Starting job polling loop (max ${maxAttempts} attempts)...`);

                    while (attempts < maxAttempts) {
                        try {
                            console.log(`[images:generate] Polling attempt ${attempts + 1}/${maxAttempts}...`);
                            jobStatus = await checkICJobStatus(mjResult.job_id);
                            console.log(`[images:generate] Job ${mjResult.job_id} status: ${jobStatus?.status}`);
                            console.log(`[images:generate] Full job status:`, JSON.stringify(jobStatus).slice(0, 300));

                            if (jobStatus?.status === 'completed' && jobStatus?.output_urls?.length > 0) {
                                // Download the first output image
                                const imageUrl = jobStatus.output_urls[0];
                                console.log(`[images:generate] ✓ Image ready at: ${imageUrl}`);
                                console.log(`[images:generate] Downloading to: ${destPath}`);

                                // Download to local file
                                try {
                                    await downloadICImage(imageUrl, destPath);
                                    console.log(`[images:generate] ✓ Image downloaded successfully`);
                                } catch (dlErr) {
                                    console.error(`[images:generate] ✗ Download failed: ${dlErr.message}`);
                                    throw dlErr;
                                }

                                // Success: Update job with generated image URL
                                console.log(`[images:generate] Updating database with image_url: ${publicPath}`);
                                const updateResult = await pgPool.query(
                                    `UPDATE image_generation_jobs SET
                                       gpu_job_status='completed', gpu_response=$2, image_url=$3,
                                       image_status='in_review', updated_at=NOW()
                                     WHERE id=$1`,
                                    [jobId, JSON.stringify(jobStatus), publicPath]
                                );
                                console.log(`[images:generate] ✓ Database updated: ${updateResult.rowCount} row(s) affected`);

                                // Track diversity (keep last 8)
                                global._imageGenerationHistory.recentPrompts.push(prompt);
                                if (global._imageGenerationHistory.recentPrompts.length > 8) {
                                    global._imageGenerationHistory.recentPrompts.shift();
                                }
                                const demoMatch = prompt.match(/\b(Black|White|Asian|Hispanic|Middle Eastern|South Asian|Indigenous|African)\s+(man|woman|person)\b/i);
                                if (demoMatch) {
                                    global._imageGenerationHistory.demographicHistory.push(demoMatch[0]);
                                    if (global._imageGenerationHistory.demographicHistory.length > 8) {
                                        global._imageGenerationHistory.demographicHistory.shift();
                                    }
                                }

                                console.log(`[images:generate] ✓ MidJourney completed: ${jobId} → ${publicPath}`);
                                logAuditEvent(pgPool, {
                                    event_type: 'image.generation_completed',
                                    actor_id: 'system',
                                    target_type: 'image_generation_jobs',
                                    target_id: jobId,
                                    details: { job_id: jobId, model: 'jubilee-midjourney', image_path: publicPath },
                                    ip_address: '127.0.0.1',
                                    user_agent: 'MidJourney API'
                                });
                                return; // Success - exit
                            } else if (jobStatus?.status === 'failed' || jobStatus?.status === 'error') {
                                console.error(`[images:generate] ✗ Job failed with status: ${jobStatus?.status}`);
                                throw new Error(`MidJourney job failed: ${jobStatus?.status}`);
                            }
                        } catch (statusErr) {
                            console.warn(`[images:generate] ⚠ Status check error (attempt ${attempts + 1}): ${statusErr.message}`);
                        }

                        attempts++;
                        if (attempts < maxAttempts) {
                            console.log(`[images:generate] Waiting 5 seconds before retry...`);
                            await new Promise(resolve => setTimeout(resolve, 5000)); // Wait 5 seconds before retry
                        }
                    }

                    console.error(`[images:generate] ✗ TIMEOUT: Job ${mjResult.job_id} did not complete within 5 minutes`);
                    throw new Error(`MidJourney job ${mjResult.job_id} did not complete within 5 minutes`);

                } catch (mjErr) {
                    console.error(`[images:generate] ========== GENERATION FAILED ==========`);
                    console.error(`[images:generate] Job ID: ${jobId}`);
                    console.error(`[images:generate] Error: ${mjErr.message}`);
                    console.error(`[images:generate] Stack:`, mjErr.stack?.split('\n').slice(0, 5).join('\n'));

                    try {
                        await pgPool.query(
                            `UPDATE image_generation_jobs SET gpu_job_status='failed', image_status='pending', updated_at=NOW() WHERE id=$1`,
                            [jobId]
                        );
                        console.log(`[images:generate] ✓ Marked job as failed in database`);
                    } catch (dbErr) {
                        console.error(`[images:generate] ✗ Could not mark job as failed: ${dbErr.message}`);
                    }
                    logAuditEvent(pgPool, {
                        event_type: 'image.generation_failed',
                        actor_id: 'system',
                        target_type: 'image_generation_jobs',
                        target_id: jobId,
                        details: { job_id: jobId, error: mjErr.message },
                        ip_address: '127.0.0.1',
                        user_agent: 'MidJourney API'
                    });
                }
            })();

            logAuditEvent(pgPool, {
                event_type: 'image.generation_requested',
                actor_id: actor.email,
                target_type: 'image_generation_jobs',
                target_id: jobId,
                details: { job_id: jobId, content_object_id: contentObjectId, requested_by: actor.email, model: 'jubilee-midjourney' },
                ip_address: req.ip,
                user_agent: req.get('user-agent'),
            });
        } catch (err) {
            console.error('[images:generate] item error:', err.message);
        }
    }
    return res.status(201).json({ created: created.length, jobs: created });
});

// POST /api/v1/images/webhook — IC callback when generation completes (no auth — uses job_id validation)
app.post('/api/v1/images/webhook', async (req, res) => {
    const { job_id, status, image_url, image_width, image_height,
            file_size_bytes, generation_duration_ms, model_used, seed, error_message } = req.body;
    if (!job_id) return res.status(400).json({ error: 'job_id required' });
    try {
        const { rows: [job] } = await pgPool.query(
            `SELECT * FROM image_generation_jobs WHERE id=$1`, [job_id]
        );
        if (!job) return res.status(404).json({ error: 'Job not found' });

        if (status === 'completed' && image_url) {
            const gpuResponse = { model_used, seed, generation_duration_ms, image_width, image_height, file_size_bytes };
            await pgPool.query(
                `UPDATE image_generation_jobs SET
                   gpu_job_status='completed', gpu_response=$2, image_url=$3,
                   image_status='in_review', updated_at=NOW()
                 WHERE id=$1`,
                [job_id, JSON.stringify(gpuResponse), image_url]
            );
            logAuditEvent(pgPool, {
                event_type: 'image.generation_completed',
                actor_id: 'system',
                target_type: 'image_generation_jobs',
                target_id: job_id,
                details: { job_id, gpu_duration_ms: generation_duration_ms, image_url },
                ip_address: req.ip,
                user_agent: req.get('user-agent'),
            });
        } else {
            await pgPool.query(
                `UPDATE image_generation_jobs SET
                   gpu_job_status='failed', image_status='pending', updated_at=NOW()
                 WHERE id=$1`,
                [job_id]
            );
            logAuditEvent(pgPool, {
                event_type: 'image.generation_failed',
                actor_id: 'system',
                target_type: 'image_generation_jobs',
                target_id: job_id,
                details: { job_id, error_message },
                ip_address: req.ip,
                user_agent: req.get('user-agent'),
            });
        }
        return res.json({ ok: true });
    } catch (e) {
        console.error('[images:webhook]', e.message);
        return res.status(500).json({ error: 'Database error' });
    }
});

// POST /api/v1/images/checkout — assign 10 unassigned in-review items to requesting reviewer (image:review)
app.post('/api/v1/images/checkout', async (req, res) => {
    const actor = await requirePrivileged(req, res); if (!actor) return;
    if (!hasPermission(actor.role, 'image:review')) return res.status(403).json({ error: 'Forbidden' });
    const reviewerId = actor.email;
    try {
        // SELECT FOR UPDATE SKIP LOCKED — concurrency-safe assignment of exactly 10 items
        await pgPool.query('BEGIN');
        const { rows: items } = await pgPool.query(
            `SELECT id FROM image_generation_jobs
             WHERE image_status='in_review' AND reviewer_id IS NULL
             ORDER BY created_at ASC
             LIMIT 10
             FOR UPDATE SKIP LOCKED`
        );
        if (!items.length) {
            await pgPool.query('ROLLBACK');
            return res.json({ assigned: 0, job_ids: [] });
        }
        const ids = items.map(r => r.id);
        await pgPool.query(
            `UPDATE image_generation_jobs SET reviewer_id=$1, checked_out_at=NOW(), updated_at=NOW()
             WHERE id = ANY($2::uuid[])`,
            [reviewerId, ids]
        );
        await pgPool.query('COMMIT');
        logAuditEvent(pgPool, {
            event_type: 'image.checked_out',
            actor_id: reviewerId,
            target_type: 'image_generation_jobs',
            target_id: ids[0],
            details: { reviewer_id: reviewerId, item_count: ids.length, job_ids: ids },
            ip_address: req.ip,
            user_agent: req.get('user-agent'),
        });
        const { rows: jobs } = await pgPool.query(
            `SELECT ij.*, co.title AS content_title
             FROM image_generation_jobs ij
             LEFT JOIN jv_content_objects co ON co.id = ij.content_object_id
             WHERE ij.id = ANY($1::uuid[])`,
            [ids]
        );
        return res.json({ assigned: ids.length, job_ids: ids, jobs });
    } catch (e) {
        await pgPool.query('ROLLBACK').catch(() => {});
        console.error('[images:checkout]', e.message);
        return res.status(500).json({ error: 'Database error' });
    }
});

// POST /api/v1/images/:jobId/approve — approve a single image (image:review)
app.post('/api/v1/images/:jobId/approve', async (req, res) => {
    const actor = await requirePrivileged(req, res); if (!actor) return;
    if (!hasPermission(actor.role, 'image:review')) return res.status(403).json({ error: 'Forbidden' });
    const { jobId } = req.params;
    try {
        // Optimistic lock: only update if still in_review
        const { rowCount, rows } = await pgPool.query(
            `UPDATE image_generation_jobs SET
               image_status='approved', approved_by=$2, approved_at=NOW(),
               reviewer_id=NULL, checked_out_at=NULL, updated_at=NOW()
             WHERE id=$1 AND image_status='in_review' AND (reviewer_id=$2 OR $3)
             RETURNING *`,
            [jobId, actor.email, hasPermission(actor.role, 'image:admin')]
        );
        if (rowCount === 0) return res.status(409).json({ error: 'Image not available for approval (already acted on or not checked out by you)' });
        const job = rows[0];
        // Link approved image as featured_image_id on content object and update hero_image_path
        if (job.content_object_id && job.image_url) {
            await pgPool.query(
                `UPDATE jv_content_objects
                 SET featured_image_id=$1,
                     extension_data = jsonb_set(COALESCE(extension_data,'{}'), '{hero_image_path}', $3::jsonb),
                     updated_at=NOW()
                 WHERE id=$2`,
                [jobId, job.content_object_id, JSON.stringify(job.image_url)]
            );
        } else if (job.content_object_id) {
            await pgPool.query(
                `UPDATE jv_content_objects SET featured_image_id=$1, updated_at=NOW() WHERE id=$2`,
                [jobId, job.content_object_id]
            );
        }
        logAuditEvent(pgPool, {
            event_type: 'image.approved',
            actor_id: actor.email,
            target_type: 'image_generation_jobs',
            target_id: jobId,
            details: { job_id: jobId, approved_by: actor.email, content_object_id: job.content_object_id },
            ip_address: req.ip,
            user_agent: req.get('user-agent'),
        });
        return res.json(job);
    } catch (e) {
        console.error('[images:approve]', e.message);
        return res.status(500).json({ error: 'Database error' });
    }
});

// POST /api/v1/images/approve-all — batch-approve all checked-out items for requesting user (image:review)
app.post('/api/v1/images/approve-all', async (req, res) => {
    const actor = await requirePrivileged(req, res); if (!actor) return;
    if (!hasPermission(actor.role, 'image:review')) return res.status(403).json({ error: 'Forbidden' });
    try {
        const { rows: items } = await pgPool.query(
            `SELECT id, content_object_id, image_url FROM image_generation_jobs
             WHERE image_status='in_review' AND reviewer_id=$1`,
            [actor.email]
        );
        if (!items.length) return res.json({ approved: 0, errors: [] });
        const approved = [];
        const errors = [];
        for (const item of items) {
            try {
                await pgPool.query(
                    `UPDATE image_generation_jobs SET
                       image_status='approved', approved_by=$2, approved_at=NOW(),
                       reviewer_id=NULL, checked_out_at=NULL, updated_at=NOW()
                     WHERE id=$1 AND image_status='in_review'`,
                    [item.id, actor.email]
                );
                if (item.content_object_id && item.image_url) {
                    await pgPool.query(
                        `UPDATE jv_content_objects
                         SET featured_image_id=$1,
                             extension_data = jsonb_set(COALESCE(extension_data,'{}'), '{hero_image_path}', $3::jsonb),
                             updated_at=NOW()
                         WHERE id=$2`,
                        [item.id, item.content_object_id, JSON.stringify(item.image_url)]
                    );
                } else if (item.content_object_id) {
                    await pgPool.query(
                        `UPDATE jv_content_objects SET featured_image_id=$1, updated_at=NOW() WHERE id=$2`,
                        [item.id, item.content_object_id]
                    );
                }
                logAuditEvent(pgPool, {
                    event_type: 'image.approved',
                    actor_id: actor.email,
                    target_type: 'image_generation_jobs',
                    target_id: item.id,
                    details: { job_id: item.id, approved_by: actor.email, content_object_id: item.content_object_id },
                    ip_address: req.ip,
                    user_agent: req.get('user-agent'),
                });
                approved.push(item.id);
            } catch (err) {
                errors.push({ id: item.id, error: err.message });
            }
        }
        logAuditEvent(pgPool, {
            event_type: 'image.batch_approved',
            actor_id: actor.email,
            target_type: 'image_generation_jobs',
            target_id: approved[0] ?? null,
            details: { reviewer_id: actor.email, item_count: approved.length, job_ids: approved },
            ip_address: req.ip,
            user_agent: req.get('user-agent'),
        });
        return res.json({ approved: approved.length, errors });
    } catch (e) {
        console.error('[images:approve-all]', e.message);
        return res.status(500).json({ error: 'Database error' });
    }
});

