// POST /api/v1/images/:jobId/requeue — admin requeues a rejected image for regeneration (image:admin)
app.post('/api/v1/images/:jobId/requeue', async (req, res) => {
    const actor = await requirePrivileged(req, res); if (!actor) return;
    if (!hasPermission(actor.role, 'image:admin')) return res.status(403).json({ error: 'Forbidden' });
    const { jobId } = req.params;
    try {
        const { rows: [oldJob] } = await pgPool.query(
            `SELECT * FROM image_generation_jobs WHERE id=$1 AND image_status='rejected'`,
            [jobId]
        );
        if (!oldJob) return res.status(404).json({ error: 'Rejected job not found' });
        // Archive the old job
        await pgPool.query(
            `UPDATE image_generation_jobs SET image_status='archived', updated_at=NOW() WHERE id=$1`,
            [jobId]
        );
        // Create new job referencing the old one
        const newJobId = require('crypto').randomUUID();
        const { rows: [newJob] } = await pgPool.query(
            `INSERT INTO image_generation_jobs
               (id, content_object_id, site_id, prompt_context, style_constraints, aspect_ratio,
                gpu_job_status, image_status, requested_by, retry_count, previous_job_id, created_at, updated_at)
             VALUES ($1, $2, $3, $4, $5, $6, 'submitted', 'generating', $7, $8, $9, NOW(), NOW())
             RETURNING *`,
            [newJobId, oldJob.content_object_id, oldJob.site_id, oldJob.prompt_context,
             JSON.stringify(oldJob.style_constraints), oldJob.aspect_ratio,
             actor.email, (oldJob.retry_count || 0) + 1, jobId]
        );
        logAuditEvent(pgPool, {
            event_type: 'image.requeued',
            actor_id: actor.email,
            target_type: 'image_generation_jobs',
            target_id: newJobId,
            details: { old_job_id: jobId, new_job_id: newJobId, admin_id: actor.email },
            ip_address: req.ip,
            user_agent: req.get('user-agent'),
        });
        return res.status(201).json(newJob);
    } catch (e) {
        console.error('[images:requeue]', e.message);
        return res.status(500).json({ error: 'Database error' });
    }
});

// PATCH /api/v1/images/:jobId/prompt — admin edits prompt before requeue (image:admin)
app.patch('/api/v1/images/:jobId/prompt', async (req, res) => {
    const actor = await requirePrivileged(req, res); if (!actor) return;
    if (!hasPermission(actor.role, 'image:admin')) return res.status(403).json({ error: 'Forbidden' });
    const { jobId } = req.params;
    const { prompt_context, style_constraints, aspect_ratio } = req.body;
    try {
        const updates = [];
        const params = [jobId];
        if (prompt_context !== undefined) { updates.push(`prompt_context=$${params.push(prompt_context)}`); }
        if (style_constraints !== undefined) { updates.push(`style_constraints=$${params.push(JSON.stringify(style_constraints))}`); }
        if (aspect_ratio !== undefined) { updates.push(`aspect_ratio=$${params.push(aspect_ratio)}`); }
        if (!updates.length) return res.status(400).json({ error: 'No fields to update' });
        updates.push('updated_at=NOW()');
        const { rows: [job] } = await pgPool.query(
            `UPDATE image_generation_jobs SET ${updates.join(',')} WHERE id=$1 RETURNING *`,
            params
        );
        if (!job) return res.status(404).json({ error: 'Job not found' });
        logAuditEvent(pgPool, {
            event_type: 'image.prompt_edited',
            actor_id: actor.email,
            target_type: 'image_generation_jobs',
            target_id: jobId,
            details: { job_id: jobId, changed_fields: Object.keys(req.body), admin_id: actor.email },
            ip_address: req.ip,
            user_agent: req.get('user-agent'),
        });
        return res.json(job);
    } catch (e) {
        console.error('[images:prompt]', e.message);
        return res.status(500).json({ error: 'Database error' });
    }
});

// POST /api/v1/images/:jobId/archive — admin permanently archives a rejected image (image:admin)
app.post('/api/v1/images/:jobId/archive', async (req, res) => {
    const actor = await requirePrivileged(req, res); if (!actor) return;
    if (!hasPermission(actor.role, 'image:admin')) return res.status(403).json({ error: 'Forbidden' });
    const { jobId } = req.params;
    try {
        const { rowCount, rows } = await pgPool.query(
            `UPDATE image_generation_jobs SET image_status='archived', updated_at=NOW()
             WHERE id=$1 AND image_status='rejected' RETURNING *`,
            [jobId]
        );
        if (rowCount === 0) return res.status(404).json({ error: 'Rejected job not found' });
        // Return content object to pending by clearing featured_image_id
        if (rows[0].content_object_id) {
            await pgPool.query(
                `UPDATE jv_content_objects SET featured_image_id=NULL WHERE id=$1 AND featured_image_id::text=$2`,
                [rows[0].content_object_id, jobId]
            );
        }
        logAuditEvent(pgPool, {
            event_type: 'image.archived',
            actor_id: actor.email,
            target_type: 'image_generation_jobs',
            target_id: jobId,
            details: { job_id: jobId, admin_id: actor.email },
            ip_address: req.ip,
            user_agent: req.get('user-agent'),
        });
        return res.json(rows[0]);
    } catch (e) {
        console.error('[images:archive]', e.message);
        return res.status(500).json({ error: 'Database error' });
    }
});

