// =============================================================================
// PORTAL DAILY LAYOUT — Deterministic per-day ordering (resets midnight PST)
// =============================================================================

/** Returns today's date string 'YYYY-MM-DD' in PST (America/Los_Angeles) timezone. */
function getPstDateString() {
    return new Date().toLocaleDateString('en-CA', { timeZone: 'America/Los_Angeles' });
}

/**
 * Seeded Fisher-Yates shuffle derived from a date string.
 * Produces identical results for the same dateStr across all server processes/users.
 */
function seededShuffle(array, dateStr) {
    // Derive a numeric seed from the date string bytes
    let seed = 0;
    for (let i = 0; i < dateStr.length; i++) seed = (seed * 31 + dateStr.charCodeAt(i)) >>> 0;
    const rng = () => {
        seed ^= seed << 13;
        seed ^= seed >>> 17;
        seed ^= seed << 5;
        return (seed >>> 0) / 0xFFFFFFFF;
    };
    const arr = [...array];
    for (let i = arr.length - 1; i > 0; i--) {
        const j = Math.floor(rng() * (i + 1));
        [arr[i], arr[j]] = [arr[j], arr[i]];
    }
    return arr;
}

// Outdated articles (pub_date older than this many days) are filtered out of the
// feed so months-old news never appears. Override via env if needed.
const FEED_MAX_AGE_DAYS = Number(process.env.FEED_MAX_AGE_DAYS) || 14;
const PORTAL_CAPACITY = 58; // 5 hero + 3 sidebar + 50 grid slots

/**
 * Generates and persists today's portal layout.
 * Rules enforced here:
 *  - Only stories with an image (cached_image_path OR image_url) are included.
 *  - Outdated articles (pub_date older than FEED_MAX_AGE_DAYS) are filtered out, so
 *    months-old news never appears. If too few fresh articles exist to fill the
 *    portal, the freshest of the older ones backfill the remaining slots — the
 *    portal must never be left empty (see Portal Spot Business Rules).
 *  - Top 5 by blended_score → hero; next 3 → sidebar; remainder shuffled → grid.
 *  - blended_score = relevance_score + freshness bonus (decays over 72h):
 *      < 24h → +25pts,  24–48h → +15pts,  48–72h → +8pts,  > 72h → +0pts
 *    This lets a solid new article (score ~70+) displace a stale top-scorer.
 */
async function generatePortalLayout(dateStr) {
    // Candidate query: approved current events with an image, ranked by
    // relevance_score boosted by a time-decay freshness bonus. When `withCutoff`
    // is set, a hard max-age filter ($2 = days) excludes outdated articles; without
    // it, all ages are eligible (used only as a fill fallback).
    const candidateSql = (withCutoff) => `
        SELECT id, relevance_score, appeal_score, topic, cached_image_path, image_url,
               -- Faith-audience appeal (when analyzed) dominates; NULL-safe fallback to
               -- keyword relevance_score for not-yet-analyzed articles. Plus freshness bonus.
               (relevance_score * 0.4 + COALESCE(appeal_score, relevance_score) * 0.6) + CASE
                   WHEN pub_date > NOW() - INTERVAL '24 hours' THEN 25
                   WHEN pub_date > NOW() - INTERVAL '48 hours' THEN 15
                   WHEN pub_date > NOW() - INTERVAL '72 hours' THEN 8
                   ELSE 0
               END AS blended_score
        FROM current_events
        WHERE approved = TRUE
          AND topic = ANY($1)
          AND full_article IS NOT NULL AND full_article != ''
          AND ((cached_image_path IS NOT NULL AND cached_image_path != '')
               OR (image_url IS NOT NULL AND image_url != ''))
          ${withCutoff ? 'AND pub_date > NOW() - make_interval(days => $2)' : ''}
        ORDER BY blended_score DESC, pub_date DESC
        LIMIT 300
    `;

    // Deduplicate by image path (same image must never appear twice) and by id
    // across the fresh + fallback passes.
    const seenImages = new Set();
    const seenIds = new Set();
    const stories = [];
    const collect = (rows) => {
        for (const s of rows) {
            const imgKey = s.cached_image_path || s.image_url || null;
            if (!imgKey || seenImages.has(imgKey) || seenIds.has(s.id)) continue;
            seenImages.add(imgKey);
            seenIds.add(s.id);
            stories.push(s);
        }
    };

    // 1) Fresh articles within the max-age window (ranked fresh-first).
    const fresh = await pgPool.query(candidateSql(true), [JUBILEEVERSE_TOPICS, FEED_MAX_AGE_DAYS]);
    collect(fresh.rows);

    // 2) If too few fresh stories to fill the portal, backfill the deficit with the
    //    freshest of the older ones — outdated news only appears when fresh is scarce.
    if (stories.length < PORTAL_CAPACITY) {
        const all = await pgPool.query(candidateSql(false), [JUBILEEVERSE_TOPICS]);
        collect(all.rows);
    }
    if (!stories.length) return null;

    const heroIds    = stories.slice(0, 5).map(s => s.id);
    const sidebarIds = stories.slice(5, 8).map(s => s.id);
    const gridRaw    = stories.slice(8, 58).map(s => s.id);  // cap at 50 grid slots
    const gridIds    = seededShuffle(gridRaw, dateStr);

    await pgPool.query(`
        INSERT INTO portal_daily_layout (layout_date, hero_ids, sidebar_ids, grid_ids)
        VALUES ($1, $2, $3, $4)
        ON CONFLICT (layout_date) DO UPDATE
            SET hero_ids = $2, sidebar_ids = $3, grid_ids = $4, created_at = NOW()
    `, [dateStr, heroIds, sidebarIds, gridIds]);

    console.log(`[Portal] Layout generated for ${dateStr}: hero=${heroIds.length} sidebar=${sidebarIds.length} grid=${gridIds.length}`);
    return { heroIds, sidebarIds, gridIds };
}

/**
 * Returns today's portal layout from DB, generating it if not yet created.
 */
async function getDailyPortalLayout() {
    const dateStr = getPstDateString();
    const row = await pgPool.query(
        `SELECT hero_ids, sidebar_ids, grid_ids FROM portal_daily_layout WHERE layout_date = $1`,
        [dateStr]
    );
    if (row.rows.length) {
        return { heroIds: row.rows[0].hero_ids, sidebarIds: row.rows[0].sidebar_ids, gridIds: row.rows[0].grid_ids };
    }
    return generatePortalLayout(dateStr);
}

// Cross-category homepage placement — returns locked daily portal layout
app.get('/api/homepage-placement', async (req, res) => {
    try {
        const layout = await getDailyPortalLayout();

        if (!layout) {
            // No stories with images available yet — return empty (never show error messages)
            return res.json({ success: true, hero: [], sidebar: [], topicCards: [] });
        }

        const { heroIds, sidebarIds, gridIds } = layout;

        // Fetch full story data for each slot, preserving stored order via array_position.
        // Re-checks approved=TRUE and image existence so stale cache IDs never serve
        // rejected, refusal, or imageless articles — even if their ID is in the cached layout.
        async function fetchByIds(ids) {
            if (!ids || !ids.length) return [];
            const result = await pgPool.query(`
                SELECT id, headline, excerpt, faith_reflection, full_article, source_name, source_url,
                       pub_date, image_url, cached_image_path, relevance_score, topic, category_id
                FROM current_events
                WHERE id = ANY($1::integer[])
                  AND approved = TRUE
                  AND ((cached_image_path IS NOT NULL AND cached_image_path != '')
                       OR (image_url IS NOT NULL AND image_url != ''))
                ORDER BY array_position($1::integer[], id)
            `, [ids]);
            // Validate that cached_image_path files actually exist on disk.
            // If a cached path points to a missing file (e.g. generated on another server),
            // null it out in the response so the frontend falls back to image_url.
            // Also asynchronously schedule regeneration for phantom paths with no fallback.
            const fs = require('fs');
            const rows = result.rows.map(row => {
                if (row.cached_image_path) {
                    const localPath = path.join(__dirname, 'public', row.cached_image_path);
                    if (!fs.existsSync(localPath)) {
                        if (!row.image_url) {
                            // No fallback — schedule async regeneration
                            setImmediate(() => {
                                generateImageForCurrentEvent(row).catch(() => {});
                            });
                            return null; // exclude from results entirely
                        }
                        // Has image_url fallback — clear phantom path in response only
                        return { ...row, cached_image_path: null };
                    }
                }
                return row;
            }).filter(Boolean);
            return rows;
        }

        const [heroStories, sidebarStories, gridStories] = await Promise.all([
            fetchByIds(heroIds),
            fetchByIds(sidebarIds),
            fetchByIds(gridIds),
        ]);

        res.json({
            success: true,
            hero: heroStories,
            sidebar: sidebarStories,
            topicCards: gridStories,   // flat array in locked portal order
        });
    } catch (err) {
        console.error('[HomePlacement] Error:', err.message);
        res.status(500).json({ error: 'Failed to build homepage placement', message: err.message });
    }
});

/**
 * Finds articles sharing the same source image_url (duplicate RSS images) and regenerates
 * a unique AI image for each duplicate using that article's own headline + content as the prompt.
 * The highest-relevance article in each duplicate group keeps its image; the rest get new ones.
 * Returns counts: { groups, regenerated, failed }.
 */
async function deduplicatePortalImages() {
    // Find groups of articles sharing the same source image URL
    const dupeResult = await pgPool.query(`
        SELECT image_url, array_agg(id ORDER BY relevance_score DESC, id ASC) AS ids
        FROM current_events
        WHERE image_url IS NOT NULL AND image_url != ''
          AND approved = TRUE
        GROUP BY image_url
        HAVING count(*) > 1
    `);

    if (!dupeResult.rows.length) {
        console.log('[ImageDedup] No duplicate source images found.');
        return { groups: 0, regenerated: 0, failed: 0 };
    }

    console.log(`[ImageDedup] Found ${dupeResult.rows.length} duplicate image group(s) — regenerating…`);
    let regenerated = 0, failed = 0;

    for (const { image_url, ids } of dupeResult.rows) {
        // ids[0] is the winner (highest relevance) — skip it, regenerate the rest
        const losers = ids.slice(1);
        for (const loserId of losers) {
            try {
                // Fetch full article data for content-driven image prompt
                const r = await pgPool.query(
                    `SELECT id, headline, excerpt, full_article, cached_image_path, year, month, day, topic
                     FROM current_events WHERE id = $1`, [loserId]
                );
                if (!r.rows.length) continue;
                const article = r.rows[0];

                // Delete stale cached file so it's not left orphaned on disk
                if (article.cached_image_path) {
                    const absPath = path.join(__dirname, 'public', article.cached_image_path);
                    if (fs.existsSync(absPath)) {
                        try { fs.unlinkSync(absPath); } catch (_) {}
                    }
                }

                // Clear cached_image_path — signals that this article needs a new image
                await pgPool.query(
                    `UPDATE current_events SET cached_image_path = NULL, approved = FALSE WHERE id = $1`,
                    [loserId]
                );

                // Generate a new unique AI image using article content as the prompt
                console.log(`[ImageDedup] Regenerating image for article ${loserId}: "${(article.headline || '').slice(0, 60)}"`);
                const newPath = await generateImageForCurrentEvent(article);
                if (newPath) {
                    await autoApproveIfReady(loserId);
                    regenerated++;
                    console.log(`[ImageDedup] Article ${loserId} → new image: ${newPath}`);
                } else {
                    failed++;
                    console.warn(`[ImageDedup] Image generation failed for article ${loserId}`);
                }

                await new Promise(r => setTimeout(r, 3000)); // 3s between generations
            } catch (e) {
                console.warn(`[ImageDedup] Error on article ${loserId}: ${e.message}`);
                failed++;
            }
        }
    }

    // Regenerate portal layout to reflect updated image assignments
    if (regenerated > 0) {
        try { await generatePortalLayout(getPstDateString()); } catch (_) {}
    }

    console.log(`[ImageDedup] Complete — ${regenerated} regenerated, ${failed} failed.`);
    return { groups: dupeResult.rows.length, regenerated, failed };
}

/**
 * repairPhantomImagePaths — finds approved articles whose cached_image_path points
 * to a file that no longer exists on disk, clears the DB record, and schedules
 * image regeneration so the portal never shows broken image placeholders.
 */
async function repairPhantomImagePaths() {
    const result = await pgPool.query(
        `SELECT id, headline, cached_image_path, image_url, excerpt, full_article, topic
         FROM current_events
         WHERE approved = TRUE
           AND cached_image_path IS NOT NULL
           AND cached_image_path != ''`
    );

    const phantom = result.rows.filter(r => {
        const localPath = path.join(__dirname, 'public', r.cached_image_path);
        return !fs.existsSync(localPath);
    });

    if (!phantom.length) {
        console.log('[PhantomRepair] No phantom cached paths found — all good.');
        return { fixed: 0, regenerating: 0 };
    }

    console.log(`[PhantomRepair] Found ${phantom.length} articles with phantom cached_image_path — clearing DB records…`);

    // Clear phantom paths in DB so generatePortalLayout() uses image_url fallback
    const phantomIds = phantom.map(r => r.id);
    await pgPool.query(
        `UPDATE current_events SET cached_image_path = NULL WHERE id = ANY($1)`,
        [phantomIds]
    );

    // Articles with no image_url at all need regeneration; those with image_url are fixed
    const needRegen = phantom.filter(r => !r.image_url);
    const hasUrlFallback = phantom.length - needRegen.length;
    console.log(`[PhantomRepair] ${hasUrlFallback} cleared (have image_url fallback), ${needRegen.length} queued for regeneration.`);

    // Regenerate images asynchronously (don't block startup)
    if (needRegen.length > 0 && process.env.LEONARDO_API_KEY_PRIMARY) {
        setTimeout(async () => {
            for (const article of needRegen) {
                try {
                    const newPath = await generateImageForCurrentEvent(article);
                    if (newPath) {
                        await autoApproveIfReady(article.id);
                        console.log(`[PhantomRepair] Regenerated image for article ${article.id}`);
                    }
                    await new Promise(r => setTimeout(r, 4000));
                } catch (e) {
                    console.warn(`[PhantomRepair] Regen failed for article ${article.id}: ${e.message}`);
                }
            }
            // Refresh portal layout after regeneration
            try { await generatePortalLayout(getPstDateString()); } catch (_) {}
        }, 2000);
    }

    // Force portal layout regeneration so phantom-cleared articles get correct slots
    try { await generatePortalLayout(getPstDateString()); } catch (_) {}

    return { fixed: phantom.length, regenerating: needRegen.length };
}

