// Backfill images for existing current_events records that have no cached_image_path
app.post('/api/admin/backfill-images', async (req, res) => {
    const limit = Math.min(parseInt(req.query.limit) || 50, 200);
    try {
        // Include: records with no image path, AND records with old-format paths that lack a local file
        const rows = await pgPool.query(`
            SELECT id, source_url, image_url, cached_image_path, year, month, day
            FROM current_events
            WHERE cached_image_path IS NULL
               OR cached_image_path NOT LIKE '/images/JubileeVerse.com/%'
            ORDER BY id DESC
            LIMIT $1
        `, [limit]);

        // Filter: keep only those where the local file truly doesn't exist
        const records = rows.rows.filter(rec => {
            if (!rec.cached_image_path) return true; // no path at all
            // Check if the file actually exists on disk
            const absPath = path.join(__dirname, 'public', rec.cached_image_path);
            return !fs.existsSync(absPath);
        });

        console.log(`[Backfill] Processing ${records.length} records with missing/phantom images`);
        let saved = 0, failed = 0;

        for (const rec of records) {
            try {
                // Clear stale cached_image_path before we attempt to re-download
                if (rec.cached_image_path) {
                    await pgPool.query(`UPDATE current_events SET cached_image_path = NULL WHERE id = $1`, [rec.id]);
                }

                let imageUrl = rec.image_url;
                if (!imageUrl && rec.source_url) {
                    imageUrl = await scrapeArticleImage(rec.source_url);
                    if (imageUrl) {
                        await pgPool.query(`UPDATE current_events SET image_url = $1 WHERE id = $2`, [imageUrl, rec.id]);
                    }
                }
                if (!imageUrl) { failed++; continue; }

                const mm = String(rec.month).padStart(2, '0');
                const dd = String(rec.day).padStart(2, '0');
                const dateDir = path.join(CE_IMAGE_DIR, String(rec.year), mm, dd);
                if (!fs.existsSync(dateDir)) fs.mkdirSync(dateDir, { recursive: true });
                const localPath = path.join(dateDir, `${rec.id}.jpg`);
                const buf = await downloadImageBuffer(imageUrl);
                fs.writeFileSync(localPath, buf);
                const webPath = `/images/JubileeVerse.com/current_events/${rec.year}/${mm}/${dd}/${rec.id}.jpg`;
                await pgPool.query(`UPDATE current_events SET cached_image_path = $1 WHERE id = $2`, [webPath, rec.id]);
                saved++;
            } catch (e) {
                console.warn(`[Backfill] id=${rec.id} failed: ${e.message}`);
                failed++;
            }
        }

        res.json({ success: true, processed: records.length, saved, failed });
    } catch (err) {
        res.status(500).json({ error: 'Backfill failed', message: err.message });
    }
});

// Manually trigger topic ingestion pipeline (admin)
app.post('/api/scanner/run-topic-pipeline', async (req, res) => {
    try {
        const { topic } = req.body || {};
        if (topic) {
            if (!TOPIC_FEEDS[topic]) {
                return res.status(400).json({ error: 'Unknown topic' });
            }
            const result = await ingestTopicStories(topic);
            return res.json({ success: true, topic, ...result });
        }
        const results = {};
        for (const t of Object.keys(TOPIC_FEEDS)) {
            results[t] = await ingestTopicStories(t);
            await new Promise(r => setTimeout(r, 2000));
        }
        res.json({ success: true, results });
    } catch (err) {
        res.status(500).json({ error: 'Pipeline failed', message: err.message });
    }
});

