// Export subscribers as Excel
app.get('/api/newsletter/export', async (req, res) => {
    try {
        const { rows: subscribers } = await pgPool.query('SELECT id, email, subscribed_at, active FROM jv_newsletter_subscribers ORDER BY subscribed_at DESC');

        const workbook = new ExcelJS.Workbook();
        workbook.creator = 'JubileeVerse';
        workbook.created = new Date();

        const sheet = workbook.addWorksheet('Newsletter Subscribers');

        sheet.columns = [
            { header: 'ID', key: 'id', width: 8 },
            { header: 'Email', key: 'email', width: 35 },
            { header: 'Subscribed At', key: 'subscribed_at', width: 22 },
            { header: 'Active', key: 'active', width: 10 }
        ];

        // Style header row
        sheet.getRow(1).font = { bold: true };
        sheet.getRow(1).fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: 'FFE6AC00' } };

        subscribers.forEach(sub => {
            sheet.addRow({
                id: sub.id,
                email: sub.email,
                subscribed_at: sub.subscribed_at,
                active: sub.active ? 'Yes' : 'No'
            });
        });

        res.setHeader('Content-Type', 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet');
        res.setHeader('Content-Disposition', `attachment; filename=jubileeverse-subscribers-${new Date().toISOString().slice(0, 10)}.xlsx`);

        await workbook.xlsx.write(res);
        res.end();
    } catch (err) {
        console.error('[Newsletter] Export error:', err.message);
        res.status(500).json({ error: 'Failed to export subscribers' });
    }
});

