// POST /api/reactions — toggle like/dislike for an article
app.post('/api/reactions', async (req, res) => {
    const token = (req.headers.authorization || '').replace('Bearer ', '');
    const payload = authVerifyJWT(token);
    if (!payload) return res.status(401).json({ error: 'Unauthorized' });

    const { article_id, article_type, reaction_type } = req.body;
    if (!article_id || !reaction_type) return res.status(400).json({ error: 'article_id and reaction_type required' });
    if (!['like', 'dislike'].includes(reaction_type)) return res.status(400).json({ error: 'reaction_type must be like or dislike' });

    const aType = article_type || 'article';
    const { rows: [existing] } = await pgPool.query(
        `SELECT reaction_type FROM article_reactions WHERE user_id=$1 AND article_id=$2 AND article_type=$3`,
        [payload.userId, article_id, aType]
    );

    let finalReaction = null;
    if (existing) {
        if (existing.reaction_type === reaction_type) {
            await pgPool.query(
                `DELETE FROM article_reactions WHERE user_id=$1 AND article_id=$2 AND article_type=$3`,
                [payload.userId, article_id, aType]
            );
        } else {
            await pgPool.query(
                `UPDATE article_reactions SET reaction_type=$1 WHERE user_id=$2 AND article_id=$3 AND article_type=$4`,
                [reaction_type, payload.userId, article_id, aType]
            );
            finalReaction = reaction_type;
        }
    } else {
        await pgPool.query(
            `INSERT INTO article_reactions (user_id, article_id, article_type, reaction_type) VALUES ($1,$2,$3,$4)`,
            [payload.userId, article_id, aType, reaction_type]
        );
        finalReaction = reaction_type;
    }

    const { rows: counts } = await pgPool.query(
        `SELECT reaction_type, COUNT(*) AS c FROM article_reactions WHERE article_id=$1 AND article_type=$2 GROUP BY reaction_type`,
        [article_id, aType]
    );
    const likes    = Number(counts.find(r => r.reaction_type === 'like')?.c    ?? 0);
    const dislikes = Number(counts.find(r => r.reaction_type === 'dislike')?.c ?? 0);

    res.json({ success: true, reaction: finalReaction, counts: { likes, dislikes } });
});

// Shared helper: parse article key "ce:123" → { article_type: "current_event", article_id: 123 }
const REACTION_PREFIX_MAP = { ce:'current_event', a:'article', enc:'content', dev:'devotional', mus:'music', rad:'radio', pra:'prayer', ms:'moreStories' };
function parseArticleKey(key) {
    const [prefix, idStr] = (key || '').split(':');
    return { article_type: REACTION_PREFIX_MAP[prefix] || prefix, article_id: parseInt(idStr) || 0 };
}

// GET /api/reactions/counts — public like/dislike counts for a list of article keys
app.get('/api/reactions/counts', async (req, res) => {
    const ids = req.query.ids;
    if (!ids) return res.json({ success: true, counts: {} });

    const keys = ids.split(',').slice(0, 100);
    const parsed = keys.map(k => ({ key: k, ...parseArticleKey(k) })).filter(p => p.article_id);
    if (!parsed.length) return res.json({ success: true, counts: {} });

    const articleIds   = parsed.map(p => p.article_id);
    const articleTypes = [...new Set(parsed.map(p => p.article_type))];
    const { rows } = await pgPool.query(
        `SELECT article_id, article_type, reaction_type, COUNT(*) AS c
         FROM article_reactions WHERE article_id=ANY($1) AND article_type=ANY($2)
         GROUP BY article_id, article_type, reaction_type`,
        [articleIds, articleTypes]
    );
    const counts = {};
    for (const p of parsed) {
        const likes    = Number(rows.find(r => r.article_id == p.article_id && r.article_type === p.article_type && r.reaction_type === 'like')?.c    ?? 0);
        const dislikes = Number(rows.find(r => r.article_id == p.article_id && r.article_type === p.article_type && r.reaction_type === 'dislike')?.c ?? 0);
        counts[p.key] = { likes, dislikes };
    }
    res.json({ success: true, counts });
});

// GET /api/reactions/user — authenticated user's reactions for a list of article keys
app.get('/api/reactions/user', async (req, res) => {
    const token = (req.headers.authorization || '').replace('Bearer ', '');
    const payload = authVerifyJWT(token);
    if (!payload) return res.json({ success: true, reactions: {} });

    const ids = req.query.ids;
    if (!ids) return res.json({ success: true, reactions: {} });

    const keys = ids.split(',').slice(0, 100);
    const parsed = keys.map(k => ({ key: k, ...parseArticleKey(k) })).filter(p => p.article_id);
    if (!parsed.length) return res.json({ success: true, reactions: {} });

    const articleIds   = parsed.map(p => p.article_id);
    const articleTypes = [...new Set(parsed.map(p => p.article_type))];
    const { rows } = await pgPool.query(
        `SELECT article_id, article_type, reaction_type FROM article_reactions
         WHERE user_id=$1 AND article_id=ANY($2) AND article_type=ANY($3)`,
        [payload.userId, articleIds, articleTypes]
    );
    const reactions = {};
    for (const p of parsed) {
        const row = rows.find(r => r.article_id == p.article_id && r.article_type === p.article_type);
        if (row) reactions[p.key] = row.reaction_type;
    }
    res.json({ success: true, reactions });
});

// -----------------------------------------------------------------------------
// Reactions keyed by article SLUG (jv_article_slug_reactions).
//
// The three endpoints above key on an INTEGER article_id, which CDN news
// articles do not have — the feed had to hash each slug into a synthetic integer
// to store anything at all. These keep the slug itself, which is what the site
// already routes on. The rules live in lib/slug-reactions.js so they can be
// tested without a database; the handlers below only do HTTP.
//
// The older endpoints stay exactly as they are: they still serve the prayer,
// music, radio and devotional namespaces, which are genuinely integer-keyed.
// -----------------------------------------------------------------------------

// POST /api/reactions/slug — set (or withdraw) this reader's reaction. Auth required.
app.post('/api/reactions/slug', async (req, res) => {
    const token = (req.headers.authorization || '').replace('Bearer ', '');
    const payload = authVerifyJWT(token);
    if (!payload) return res.status(401).json({ error: 'Unauthorized' });

    const { slug, reaction } = req.body || {};
    if (!slugReactions.isValidSlug(slug)) {
        return res.status(400).json({ error: 'A valid article slug is required' });
    }
    if (!slugReactions.isValidReaction(reaction)) {
        return res.status(400).json({ error: "reaction must be 'like' or 'dislike'" });
    }

    try {
        const result = await slugReactions.setReaction(pgPool, {
            userId: payload.userId,
            slug,
            reaction,
        });
        res.json({ success: true, ...result });
    } catch (err) {
        console.error('[reactions/slug] set failed:', err.message);
        res.status(500).json({ error: 'Could not save your reaction' });
    }
});

// GET /api/reactions/slug/counts?slugs=a,b — public totals for a page of cards.
app.get('/api/reactions/slug/counts', async (req, res) => {
    try {
        const counts = await slugReactions.countsForSlugs(pgPool, req.query.slugs);
        res.json({ success: true, counts });
    } catch (err) {
        console.error('[reactions/slug] counts failed:', err.message);
        res.status(500).json({ error: 'Could not load reaction counts' });
    }
});

// GET /api/reactions/slug/user?slugs=a,b — this reader's own reactions.
// A signed-out reader gets an empty map rather than a 401: the card grid asks
// for this on every page load, and "nobody is signed in" is not an error.
app.get('/api/reactions/slug/user', async (req, res) => {
    const token = (req.headers.authorization || '').replace('Bearer ', '');
    const payload = authVerifyJWT(token);
    if (!payload) return res.json({ success: true, reactions: {} });

    try {
        const reactions = await slugReactions.userReactionsForSlugs(
            pgPool, payload.userId, req.query.slugs
        );
        res.json({ success: true, reactions });
    } catch (err) {
        console.error('[reactions/slug] user lookup failed:', err.message);
        res.status(500).json({ error: 'Could not load your reactions' });
    }
});

