// POST /api/track/view — Public: track article view or click
app.post('/api/track/view', async (req, res) => {
    const { article_id, article_type, event_type, session_id } = req.body;
    if (!article_id || !article_type || !event_type) return res.status(400).json({ error: 'article_id, article_type, event_type required' });
    if (!['article', 'current_event'].includes(article_type)) return res.status(400).json({ error: 'Invalid article_type' });
    if (!['view', 'click'].includes(event_type)) return res.status(400).json({ error: 'Invalid event_type' });

    if (session_id) {
        const { rows: [existing] } = await pgPool.query(
            `SELECT id FROM article_views WHERE session_id=$1 AND article_id=$2 AND article_type=$3
             AND event_type=$4 AND created_at > NOW() - INTERVAL '30 minutes'`,
            [session_id, article_id, article_type, event_type]
        );
        if (existing) return res.json({ ok: true, duplicate: true });
    }

    let userId = null;
    const token = (req.headers.authorization || '').replace('Bearer ', '').trim();
    if (token) { const p = authVerifyJWT(token); if (p) userId = p.userId; }

    await pgPool.query(
        `INSERT INTO article_views (article_id, article_type, event_type, session_id, user_id) VALUES ($1,$2,$3,$4,$5)`,
        [article_id, article_type, event_type, session_id || null, userId]
    );
    res.json({ ok: true });
});

// GET /api/admin/articles-mgmt — Reviewer-only: combined articles + current_events list
app.get('/api/admin/articles-mgmt', async (req, res) => {
    const payload = requireReviewer(req, res);
    if (!payload) return;

    const categoryId = parseInt(req.query.category_id);
    const aggregate = req.query.aggregate === 'true';

    if (!categoryId) return res.status(400).json({ error: 'category_id required' });

    try {
        let articleIds = [];
        let ceIds = [];

        // Get articles for this category (and descendants if aggregate)
        if (aggregate) {
            const artResult = await pgPool.query(`
                WITH RECURSIVE cat_tree AS (
                    SELECT id FROM categories WHERE id = $1
                    UNION ALL
                    SELECT c.id FROM categories c JOIN cat_tree ct ON c.parent_id = ct.id
                )
                SELECT a.id, a.title, a.status, a.content_type, a.author, a.hero_image_path,
                       a.created_at, a.updated_at, c.name AS category_name
                FROM articles a
                JOIN categories c ON a.category_id = c.id
                WHERE a.category_id IN (SELECT id FROM cat_tree)
                ORDER BY a.created_at DESC
                LIMIT 500
            `, [categoryId]);
            articleIds = artResult.rows.map(r => ({ ...r, source_type: 'article', image: r.hero_image_path }));
        } else {
            const artResult = await pgPool.query(`
                SELECT a.id, a.title, a.status, a.content_type, a.author, a.hero_image_path,
                       a.created_at, a.updated_at, c.name AS category_name
                FROM articles a
                JOIN categories c ON a.category_id = c.id
                WHERE a.category_id = $1
                ORDER BY a.created_at DESC
                LIMIT 500
            `, [categoryId]);
            articleIds = artResult.rows.map(r => ({ ...r, source_type: 'article', image: r.hero_image_path }));
        }

        // Get current_events for this category
        const ceResult = await pgPool.query(`
            SELECT ce.id, ce.headline AS title, ce.topic, ce.source_name AS author,
                   ce.cached_image_path, ce.image_url, ce.approved, ce.approval_reason,
                   ce.pub_date, ce.created_at
            FROM current_events ce
            WHERE ce.category_id = $1 AND ce.topic = ANY($2)
            ORDER BY ce.created_at DESC
            LIMIT 500
        `, [categoryId, JUBILEEVERSE_TOPICS]);
        ceIds = ceResult.rows.map(r => ({
            ...r,
            source_type: 'current_event',
            status: r.approved ? 'approved' : 'unapproved',
            image: r.cached_image_path || r.image_url,
            updated_at: r.pub_date
        }));

        const combined = [...articleIds, ...ceIds].sort((a, b) => new Date(b.created_at) - new Date(a.created_at));
        res.json({ success: true, articles: combined });
    } catch (err) {
        console.error('[ArticleMgmt] Error:', err.message);
        res.status(500).json({ error: 'Failed to fetch articles', message: err.message });
    }
});

// GET /api/admin/article-stats — Reviewer-only: views/clicks/likes/dislikes for article keys
app.get('/api/admin/article-stats', async (req, res) => {
    const payload = requireReviewer(req, res);
    if (!payload) return;

    const ids = req.query.ids; // comma-separated "a:123,ce:456"
    if (!ids) return res.json({ success: true, stats: {} });

    const keys = ids.split(',').slice(0, 500);
    const parsed = keys.map(k => ({ key: k, ...parseArticleKey(k) })).filter(p => p.article_id);
    if (parsed.length === 0) return res.json({ success: true, stats: {} });

    try {
        const articleIds = parsed.map(p => p.article_id);
        const articleTypes = parsed.map(p => p.article_type);

        const [viewsResult, reactionsResult] = await Promise.all([
            pgPool.query(`
                SELECT article_id, article_type, event_type, COUNT(*) AS c
                FROM article_views
                WHERE (article_id, article_type) IN (SELECT UNNEST($1::int[]), UNNEST($2::text[]))
                  AND event_type IN ('view', 'click')
                GROUP BY article_id, article_type, event_type
            `, [articleIds, articleTypes]),
            pgPool.query(`
                SELECT article_id, article_type, reaction_type, COUNT(*) AS c
                FROM article_reactions
                WHERE (article_id, article_type) IN (SELECT UNNEST($1::int[]), UNNEST($2::text[]))
                  AND reaction_type IN ('like', 'dislike')
                GROUP BY article_id, article_type, reaction_type
            `, [articleIds, articleTypes]),
        ]);

        const viewsMap = {};
        for (const row of viewsResult.rows) {
            viewsMap[`${row.article_id}:${row.article_type}:${row.event_type}`] = parseInt(row.c, 10);
        }
        const reactionsMap = {};
        for (const row of reactionsResult.rows) {
            reactionsMap[`${row.article_id}:${row.article_type}:${row.reaction_type}`] = parseInt(row.c, 10);
        }

        const stats = {};
        for (const p of parsed) {
            const vk = `${p.article_id}:${p.article_type}`;
            stats[p.key] = {
                views:    viewsMap[`${vk}:view`]       || 0,
                clicks:   viewsMap[`${vk}:click`]      || 0,
                likes:    reactionsMap[`${vk}:like`]    || 0,
                dislikes: reactionsMap[`${vk}:dislike`] || 0,
            };
        }

        res.json({ success: true, stats });
    } catch (err) {
        console.error('[ArticleStats] Error:', err.message);
        res.status(500).json({ error: 'Failed to fetch article stats', message: err.message });
    }
});

// PATCH /api/admin/articles-mgmt/bulk-status — Reviewer-only: bulk activate/deactivate
app.patch('/api/admin/articles-mgmt/bulk-status', async (req, res) => {
    const payload = requireReviewer(req, res);
    if (!payload) return;

    const { items, action } = req.body;
    if (!items || !Array.isArray(items) || !action) return res.status(400).json({ error: 'items array and action required' });
    if (!['activate', 'deactivate'].includes(action)) return res.status(400).json({ error: 'action must be activate or deactivate' });

    const articleItems = items.filter(i => i.source_type === 'article').map(i => parseInt(i.id));
    const ceItems = items.filter(i => i.source_type === 'current_event').map(i => parseInt(i.id));

    let updatedArticles = 0, updatedCE = 0;

    try {
        if (articleItems.length > 0) {
            const status = action === 'activate' ? 'published' : 'unpublished';
            const result = await pgPool.query(
                `UPDATE articles SET status = $1, updated_at = NOW() WHERE id = ANY($2::int[])`,
                [status, articleItems]
            );
            updatedArticles = result.rowCount;
        }

        if (ceItems.length > 0) {
            const approved = action === 'activate';
            const result = await pgPool.query(
                `UPDATE current_events SET approved = $1 WHERE id = ANY($2::int[]) AND topic = ANY($3)`,
                [approved, ceItems, JUBILEEVERSE_TOPICS]
            );
            updatedCE = result.rowCount;
        }

        res.json({ success: true, updated: { articles: updatedArticles, current_events: updatedCE } });
    } catch (err) {
        console.error('[BulkStatus] Error:', err.message);
        res.status(500).json({ error: 'Bulk update failed', message: err.message });
    }
});

// PATCH /api/admin/articles-mgmt/:sourceType/:id/status — Reviewer-only: individual toggle
app.patch('/api/admin/articles-mgmt/:sourceType/:id/status', async (req, res) => {
    const payload = requireReviewer(req, res);
    if (!payload) return;

    const { sourceType, id } = req.params;
    const { action } = req.body;
    if (!['activate', 'deactivate'].includes(action)) return res.status(400).json({ error: 'action must be activate or deactivate' });

    try {
        if (sourceType === 'article') {
            const status = action === 'activate' ? 'published' : 'unpublished';
            await pgPool.query(`UPDATE articles SET status = $1, updated_at = NOW() WHERE id = $2`, [status, parseInt(id)]);
        } else if (sourceType === 'current_event') {
            const approved = action === 'activate';
            await pgPool.query(
                `UPDATE current_events SET approved = $1 WHERE id = $2 AND topic = ANY($3)`,
                [approved, parseInt(id), JUBILEEVERSE_TOPICS]
            );
        } else {
            return res.status(400).json({ error: 'Invalid sourceType' });
        }
        res.json({ success: true });
    } catch (err) {
        console.error('[StatusToggle] Error:', err.message);
        res.status(500).json({ error: 'Status update failed', message: err.message });
    }
});

// GET /api/admin/current-events/:id — Reviewer-only: single current_event by ID
app.get('/api/admin/current-events/:id', async (req, res) => {
    const payload = requireReviewer(req, res);
    if (!payload) return;

    const id = parseInt(req.params.id, 10);
    if (!id) return res.status(400).json({ error: 'Invalid ID' });

    try {
        const result = await pgPool.query(
            `SELECT id, headline, excerpt, faith_reflection, full_article, source_name, source_url,
                    pub_date, image_url, cached_image_path, topic, category_id, approved, approval_reason, created_at
             FROM current_events WHERE id = $1 AND topic = ANY($2)`,
            [id, JUBILEEVERSE_TOPICS]
        );
        if (!result.rows.length) return res.status(404).json({ error: 'Not found' });
        res.json({ success: true, article: result.rows[0] });
    } catch (err) {
        res.status(500).json({ error: 'Failed to fetch article', message: err.message });
    }
});

