const { Pool } = require('pg');

// PostgreSQL connection pool (connects to UAT database)
const pgPool = new Pool({
    host:     process.env.DB_HOST || '207.244.228.8',
    port:     parseInt(process.env.DB_PORT  || '5432', 10),
    database: process.env.DB_NAME || 'jubileeverse',
    user:     process.env.DB_USER || 'postgres',
    password: process.env.DB_PASSWORD || '',
    ssl: false,
    // Robustness: hard limits so a dead tunnel can never freeze the process
    connectionTimeoutMillis: 5_000,   // fail fast if tunnel/server unreachable
    idleTimeoutMillis:      30_000,   // release idle clients after 30 s
    query_timeout:          15_000,   // node-postgres client-side query deadline
    statement_timeout:      15_000,   // PostgreSQL server-side statement deadline (ms)
    max: 10,                           // cap pool size
});

// inspirePool — alias for pgPool (jubileeverse DB used across all environments)
const inspirePool = pgPool;

// Test database connection
pgPool.on('connect', () => {
    console.log('✓ Connected to PostgreSQL database');
});

pgPool.on('error', (err) => {
    console.error('PostgreSQL pool error:', err.message);
});

// Give taskExecutor access to PostgreSQL for database operations
taskExecutor.pgPool = pgPool;

