// =============================================================================
// PHASE 8: CROSS-SITE PUBLISHING HELPERS
// =============================================================================

async function _evaluatePublishTargets(pgPool, objectId, actorEmail, req) {
    const { rows: [co] } = await pgPool.query(
        `SELECT id, object_type, title, publish_targets FROM jv_content_objects WHERE id=$1::uuid`,
        [objectId]
    );
    if (!co || !Array.isArray(co.publish_targets) || co.publish_targets.length === 0) return;

    const updatedTargets = [...co.publish_targets];

    for (let i = 0; i < updatedTargets.length; i++) {
        const target = updatedTargets[i];
        if (target.status === 'published') continue;

        const { rows: [site] } = await pgPool.query(
            `SELECT id, title, extension_data FROM jv_content_objects WHERE id=$1::uuid AND object_type='site'`,
            [target.site_id]
        );
        if (!site) continue;
        const siteExt = site.extension_data || {};
        const rules = siteExt.publishing_rules || {};

        const whitelist = rules.content_type_whitelist || [];
        if (whitelist.length > 0 && !whitelist.includes(co.object_type)) {
            updatedTargets[i] = { ...target, status: 'unpublished' };
            continue;
        }

        const today = getPstDateString();
        if ((rules.blackout_dates || []).includes(today)) {
            updatedTargets[i] = { ...target, status: 'pending' };
            continue;
        }

        const newStatus = rules.require_site_owner_approval ? 'pending' : 'published';
        const publishedAt = newStatus === 'published' ? new Date().toISOString() : null;
        const titleSlug = (target.overrides?.title || co.title || '')
            .toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '');
        const domain = siteExt.domain || '';
        const publishedUrl = newStatus === 'published' ? `https://${domain}/content/${titleSlug}` : null;

        updatedTargets[i] = { ...target, status: newStatus, published_at: publishedAt, published_url: publishedUrl };

        if (newStatus === 'published') {
            pgPool.query(
                `INSERT INTO jv_site_content_map (site_id, object_table, object_id, title_override, published_at)
                 SELECT s.id, 'jv_content_objects', 0, $2, NOW()
                 FROM jv_sites s WHERE s.domain=$1
                 ON CONFLICT DO NOTHING`,
                [domain, target.overrides?.title || null]
            ).catch(() => {});

            logAuditEvent(pgPool, {
                event_type: 'content.site_published',
                actor_id: actorEmail,
                target_type: 'jv_content_objects',
                target_id: objectId,
                details: { site_id: target.site_id, site_domain: domain, published_url: publishedUrl },
                ip_address: req?.ip,
                user_agent: req?.get?.('user-agent'),
            });
        }
    }

    await pgPool.query(
        `UPDATE jv_content_objects SET publish_targets=$2, updated_at=NOW() WHERE id=$1::uuid`,
        [objectId, JSON.stringify(updatedTargets)]
    );
}

