// B1 — In-memory TTL cache (follows sports cache pattern)
function createTTLCache(defaultTtlMs = 60_000) {
    const store = new Map();
    return {
        get(key) {
            const entry = store.get(key);
            if (!entry) return undefined;
            if (Date.now() > entry.expiresAt) { store.delete(key); return undefined; }
            return entry.value;
        },
        set(key, value, ttlMs = defaultTtlMs) {
            store.set(key, { value, expiresAt: Date.now() + ttlMs });
        },
        del(key) { store.delete(key); },
        clear() { store.clear(); },
    };
}

const _apiCache = {
    taxonomy: createTTLCache(5 * 60_000),
    nav:      createTTLCache(5 * 60_000),
    feed:     createTTLCache(2 * 60_000),
    content:  createTTLCache(60_000),
};

// ── Part 4 S5: Portal page cache (5-minute TTL) ───────────────────────────────
const _portalPageCache = createTTLCache(5 * 60_000);

// ── Part 4 S5: In-process generation lock ────────────────────────────────────
// Map<lockKey, Promise<result>> — first requester runs generator; all others await same Promise.
const _portalGenLocks = new Map();

/**
 * Deduplicates concurrent portal generation requests.
 * First call to _withPortalGenLock for a given key runs `generator()` and stores its Promise.
 * Subsequent calls with the same key await that Promise (up to `timeoutMs`).
 */
async function _withPortalGenLock(lockKey, timeoutMs, generator) {
    if (_portalGenLocks.has(lockKey)) {
        try {
            return await Promise.race([
                _portalGenLocks.get(lockKey),
                new Promise((_, rej) => setTimeout(
                    () => rej(Object.assign(new Error('Lock timeout'), { isTimeout: true })),
                    timeoutMs
                )),
            ]);
        } catch (e) {
            if (!e.isTimeout) throw e;
            // Timed out — fall through and generate independently
        }
    }
    let lockResolve, lockReject;
    const lockPromise = new Promise((res, rej) => { lockResolve = res; lockReject = rej; });
    _portalGenLocks.set(lockKey, lockPromise);
    try {
        const result = await generator();
        lockResolve(result);
        return result;
    } catch (e) {
        lockReject(e);
        throw e;
    } finally {
        _portalGenLocks.delete(lockKey);
    }
}

// ── Part 4 S6: Hit tracking — in-memory buffer + per-IP rate limiter ─────────

const _portalHitBuffer = new Map();  // portalId → buffered hit count
const _portalHitRlMap  = new Map();  // `${ip}:${portalId}` → last hit timestamp (ms)

const BOT_UA_RE = /bot|crawler|spider|crawl|slurp|googlebot|bingbot|facebookexternalhit|Twitterbot|LinkedInBot/i;

// Purge stale rate-limit entries every 5 minutes
setInterval(() => {
    const cutoff = Date.now() - 60_000;
    for (const [k, ts] of _portalHitRlMap) {
        if (ts < cutoff) _portalHitRlMap.delete(k);
    }
}, 5 * 60_000);

// Flush hit buffer to portal_pages + portal_hit_timeseries every 60 seconds
setInterval(async () => {
    if (!_portalHitBuffer.size) return;
    const snapshot = new Map(_portalHitBuffer);
    _portalHitBuffer.clear();

    const hourBucket = new Date();
    hourBucket.setMinutes(0, 0, 0);
    hourBucket.setMilliseconds(0);

    for (const [portalId, count] of snapshot) {
        try {
            // Size cap: stop incrementing at 1,000,000 hits
            const { rows: [row] } = await pgPool.query(
                `SELECT hit_count FROM portal_pages WHERE id=$1`, [portalId]
            );
            if (!row || row.hit_count >= 1_000_000) continue;

            await pgPool.query(
                `UPDATE portal_pages SET hit_count = hit_count + $1 WHERE id=$2`,
                [count, portalId]
            );
            await pgPool.query(
                `INSERT INTO portal_hit_timeseries (portal_id, hour_bucket, hit_count)
                 VALUES ($1, $2, $3)
                 ON CONFLICT (portal_id, hour_bucket)
                 DO UPDATE SET hit_count = portal_hit_timeseries.hit_count + EXCLUDED.hit_count`,
                [portalId, hourBucket.toISOString(), count]
            );
        } catch (e) {
            // Re-buffer on DB failure to avoid data loss
            _portalHitBuffer.set(portalId, (_portalHitBuffer.get(portalId) ?? 0) + count);
            console.error('[portal:hitFlush]', e.message);
        }
    }
}, 60_000);

// B2 — API key middleware + in-memory rate limiter
const _apiKeyRateLimits = new Map();

async function requireApiKey(req, res) {
    const raw = req.headers['x-api-key'];
    if (!raw) { res.status(401).json({ error: 'API key required' }); return null; }
    const hash = crypto.createHash('sha256').update(raw).digest('hex');
    let key;
    try {
        const { rows: [k] } = await pgPool.query(
            `SELECT * FROM jv_api_keys WHERE key_hash=$1 AND (expires_at IS NULL OR expires_at > NOW())`,
            [hash]
        );
        key = k;
    } catch (e) {
        res.status(500).json({ error: 'Service unavailable' }); return null;
    }
    if (!key) { res.status(401).json({ error: 'Invalid or expired API key' }); return null; }
    const now = Date.now();
    let rl = _apiKeyRateLimits.get(hash);
    if (!rl || now - rl.windowStart > 3_600_000) rl = { count: 0, windowStart: now };
    rl.count++;
    _apiKeyRateLimits.set(hash, rl);
    if (rl.count > key.rate_limit_rph) { res.status(429).json({ error: 'Rate limit exceeded' }); return null; }
    pgPool.query(`UPDATE jv_api_keys SET last_used_at=NOW() WHERE id=$1`, [key.id]).catch(() => {});
    return key;
}

// B3 — CDN cache headers (dev: no-cache everywhere)
function setCacheHeaders(res, _maxAge = 60, _sMaxAge = 300) {
    res.set('Cache-Control', 'no-cache, no-store, must-revalidate');
    res.set('Pragma', 'no-cache');
    res.set('Expires', '0');
}

// B4 — Cloudflare cache purge
async function invalidateCloudflarePaths(paths) {
    const zoneId = process.env.CF_ZONE_ID;
    const token  = process.env.CF_API_TOKEN;
    if (!zoneId || !token || !paths.length) return;
    try {
        await fetch(`https://api.cloudflare.com/client/v4/zones/${zoneId}/purge_cache`, {
            method: 'POST',
            headers: { 'Authorization': `Bearer ${token}`, 'Content-Type': 'application/json' },
            body: JSON.stringify({ files: paths }),
        });
    } catch (err) {
        console.error('[cloudflare] purge error:', err.message);
    }
}

// B5 — HMAC-signed webhook dispatch
async function dispatchWebhooks(eventType, payload) {
    try {
        const { rows: hooks } = await pgPool.query(
            `SELECT * FROM jv_webhooks WHERE active=TRUE AND events @> $1::jsonb`,
            [JSON.stringify([eventType])]
        );
        for (const hook of hooks) {
            const body = JSON.stringify({ event: eventType, payload, timestamp: new Date().toISOString() });
            const sig  = crypto.createHmac('sha256', hook.secret).update(body).digest('hex');
            const { rows: [delivery] } = await pgPool.query(
                `INSERT INTO jv_webhook_deliveries (webhook_id, event_type, payload, attempt_count)
                 VALUES ($1, $2, $3, 1) RETURNING id`,
                [hook.id, eventType, JSON.stringify(payload)]
            );
            try {
                const resp = await fetch(hook.url, {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json', 'X-Webhook-Signature': `sha256=${sig}` },
                    body,
                    signal: AbortSignal.timeout(10_000),
                });
                await pgPool.query(
                    `UPDATE jv_webhook_deliveries SET status=$2, response_status=$3, delivered_at=NOW() WHERE id=$1`,
                    [delivery.id, resp.ok ? 'success' : 'failed', resp.status]
                );
            } catch (err) {
                await pgPool.query(
                    `UPDATE jv_webhook_deliveries SET status='failed', response_body=$2 WHERE id=$1`,
                    [delivery.id, err.message]
                );
            }
        }
    } catch (err) {
        console.error('[dispatchWebhooks]', err.message);
    }
}

// B6 — Embedding generation via IC API
async function generateAndStoreEmbedding(pgPool, objectId, co) {
    const icBase = process.env.IC_API_BASE;
    const icKey  = process.env.IC_API_KEY || process.env.IC_JWT_TOKEN;
    if (!icBase || !icKey) return;
    try {
        const text = [co.title, co.summary, co.language].filter(Boolean).join(' ');
        const resp = await fetch(`${icBase}/v1/embeddings`, {
            method: 'POST',
            headers: { 'Authorization': `Bearer ${icKey}`, 'Content-Type': 'application/json' },
            body: JSON.stringify({ model: 'text-embedding-3-small', input: text }),
        });
        if (!resp.ok) return;
        const { data } = await resp.json();
        const vec = data?.[0]?.embedding;
        if (!vec) return;
        await pgPool.query(
            `UPDATE jv_content_objects SET embedding=$2::vector WHERE id=$1::uuid`,
            [objectId, JSON.stringify(vec)]
        );
    } catch (err) {
        console.error('[embedding] generation error:', err.message);
    }
}

// B7 — Sitemap and RSS feed generators
async function generateSitemapXml(pgPool, domain) {
    const { rows: siteRows } = await pgPool.query(
        `SELECT id FROM jv_content_objects WHERE object_type='site' AND extension_data->>'domain'=$1`,
        [domain]
    );
    if (!siteRows[0]) return null;
    const siteId = siteRows[0].id;
    const { rows } = await pgPool.query(
        `SELECT slug, title, updated_at FROM jv_content_objects
         WHERE status='published' AND object_type != 'site'
           AND EXISTS (
             SELECT 1 FROM jsonb_array_elements(publish_targets) t
             WHERE (t->>'site_id')=$1 AND (t->>'status')='published'
           )
         ORDER BY updated_at DESC LIMIT 5000`,
        [siteId]
    );
    const urls = rows.map(r => {
        const slug = r.slug || (r.title || '').toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '');
        return `  <url><loc>https://${domain}/content/${slug}</loc><lastmod>${r.updated_at.toISOString().split('T')[0]}</lastmod></url>`;
    }).join('\n');
    return `<?xml version="1.0" encoding="UTF-8"?>\n<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">\n${urls}\n</urlset>`;
}

async function generateRssFeedXml(pgPool, domain) {
    const { rows: siteRows } = await pgPool.query(
        `SELECT id, title FROM jv_content_objects WHERE object_type='site' AND extension_data->>'domain'=$1`,
        [domain]
    );
    if (!siteRows[0]) return null;
    const siteId    = siteRows[0].id;
    const siteTitle = siteRows[0].title || domain;
    const { rows } = await pgPool.query(
        `SELECT co.title, co.slug, co.summary, co.published_at,
                (SELECT t->>'published_url' FROM jsonb_array_elements(co.publish_targets) t
                 WHERE (t->>'site_id')=$1 AND (t->>'status')='published' LIMIT 1) AS published_url
         FROM jv_content_objects co
         WHERE co.status='published' AND co.object_type != 'site'
           AND EXISTS (
             SELECT 1 FROM jsonb_array_elements(co.publish_targets) t
             WHERE (t->>'site_id')=$1 AND (t->>'status')='published'
           )
         ORDER BY co.published_at DESC LIMIT 50`,
        [siteId]
    );
    const items = rows.map(r => {
        const link = r.published_url || `https://${domain}/content/${r.slug || ''}`;
        return `    <item><title><![CDATA[${r.title || ''}]]></title><link>${link}</link><description><![CDATA[${r.summary || ''}]]></description><pubDate>${new Date(r.published_at || Date.now()).toUTCString()}</pubDate></item>`;
    }).join('\n');
    return `<?xml version="1.0" encoding="UTF-8"?>\n<rss version="2.0">\n  <channel>\n    <title>${siteTitle}</title>\n    <link>https://${domain}</link>\n    <description>Latest content from ${domain}</description>\n${items}\n  </channel>\n</rss>`;
}

// B8 — Publishing pipeline orchestrator
async function runPublishingPipeline(pgPool, objectId, actorEmail, req) {
    const { rows: [co] } = await pgPool.query(
        `SELECT * FROM jv_content_objects WHERE id=$1::uuid`, [objectId]
    );
    if (!co || co.status !== 'published') return;

    // 1. Generate embedding (fire-and-forget)
    generateAndStoreEmbedding(pgPool, objectId, co).catch(err =>
        console.error('[pipeline] embedding error:', err.message));

    // 2. Regenerate sitemap + RSS + invalidate CDN per published site target
    const targets = Array.isArray(co.publish_targets) ? co.publish_targets : [];
    const publishedTargets = targets.filter(t => t.status === 'published');
    const processedDomains = new Set();
    for (const target of publishedTargets) {
        try {
            const { rows: [site] } = await pgPool.query(
                `SELECT extension_data->>'domain' AS domain FROM jv_content_objects WHERE id=$1::uuid`,
                [target.site_id]
            );
            const domain = site?.domain;
            if (!domain || processedDomains.has(domain)) continue;
            processedDomains.add(domain);

            generateSitemapXml(pgPool, domain).then(xml => {
                if (!xml) return;
                pgPool.query(
                    `INSERT INTO jv_sitemaps (site_domain, xml_content, generated_at)
                     VALUES ($1, $2, NOW()) ON CONFLICT (site_domain)
                     DO UPDATE SET xml_content=$2, generated_at=NOW()`,
                    [domain, xml]
                ).catch(() => {});
            }).catch(() => {});

            generateRssFeedXml(pgPool, domain).then(xml => {
                if (!xml) return;
                pgPool.query(
                    `INSERT INTO jv_rss_feeds (site_domain, xml_content, generated_at)
                     VALUES ($1, $2, NOW()) ON CONFLICT (site_domain)
                     DO UPDATE SET xml_content=$2, generated_at=NOW()`,
                    [domain, xml]
                ).catch(() => {});
            }).catch(() => {});

            invalidateCloudflarePaths([
                `https://${domain}/api/v1/content`,
                `https://${domain}/api/v1/sites/${domain}/feed`,
                `https://${domain}/api/v1/sitemap/${domain}.xml`,
                `https://${domain}/api/v1/feed/${domain}.rss`,
            ]).catch(() => {});
            _apiCache.content.clear();
            _apiCache.feed.del(domain);
        } catch { /* continue to next target */ }
    }

    // 3. Dispatch webhooks
    dispatchWebhooks('content.published', {
        id: co.id, object_type: co.object_type, title: co.title,
        slug: co.slug, published_at: co.published_at,
    }).catch(err => console.error('[pipeline] webhook error:', err.message));
}

