// =============================================================================
// PORTAL API — Encouragement category articles from jubileeverse DB
// =============================================================================

function hasDisplayablePortalImage(imagePath) {
    if (!imagePath || typeof imagePath !== 'string') return false;
    const trimmed = imagePath.trim();
    if (!trimmed) return false;

    // Remote images are considered displayable (cannot reliably pre-verify reachability here).
    if (/^https?:\/\//i.test(trimmed)) return true;

    // Local web paths must resolve inside /public and exist on disk.
    const publicRoot = path.resolve(__dirname, 'public');
    const relativeWebPath = trimmed.replace(/^\/+/, '');
    const resolvedPath = path.resolve(publicRoot, relativeWebPath);
    const inPublicRoot = resolvedPath === publicRoot || resolvedPath.startsWith(publicRoot + path.sep);
    if (!inPublicRoot) return false;

    return fs.existsSync(resolvedPath);
}

function filterPortalArticlesWithImages(rows) {
    if (!Array.isArray(rows)) return [];
    return rows.filter(row => hasDisplayablePortalImage(row.image));
}

app.get('/api/portal/encouragement', async (req, res) => {
    try {
        const result = await inspirePool.query(`
            WITH RECURSIVE cat_tree AS (
                SELECT id FROM categories WHERE id = 64590
                UNION ALL
                SELECT c.id FROM categories c
                INNER JOIN cat_tree ct ON c.parent_id = ct.id
            )
            SELECT
                a.id,
                a.title,
                a.slug,
                regexp_replace(
                    regexp_replace(a.summary, E'^#+[^\n]*\n+', '', 'g'),
                    E'^\\s+', '', 'g'
                ) AS summary,
                a.hero_image_path AS image,
                'encouragement' AS portal_slug,
                c.name AS category,
                c.slug AS category_slug,
                a.created_at
            FROM articles a
            JOIN categories c ON a.category_id = c.id
            WHERE a.category_id IN (SELECT id FROM cat_tree)
              AND a.hero_image_path IS NOT NULL
              AND a.hero_image_path != ''
            ORDER BY a.created_at DESC
            LIMIT 120
        `);

        const articles = filterPortalArticlesWithImages(result.rows);
        res.json({ success: true, articles });
    } catch (err) {
        // Fall back to cached export when jubileeinspire_uat is unavailable (e.g. dev)
        const cacheFile = path.join(__dirname, 'data', 'encouragement-cache.json');
        if (fs.existsSync(cacheFile)) {
            const cached = JSON.parse(fs.readFileSync(cacheFile, 'utf8'));
            const articles = filterPortalArticlesWithImages(cached);
            return res.json({ success: true, articles });
        }
        console.error('Error fetching encouragement portal articles:', err.message);
        res.status(500).json({ error: 'Failed to load encouragement articles' });
    }
});

