/**
 * API: Get single article by ID (public — used by article.html to load real content)
 */
// Fetch article by ID or slug
app.get('/api/articles/:idOrSlug', async (req, res) => {
    const { idOrSlug } = req.params;
    try {
        // Check if it's numeric ID or slug
        const isNumeric = /^\d+$/.test(idOrSlug);
        const query = isNumeric
            ? `WITH RECURSIVE cat_hierarchy AS (
                -- Start with the article's direct category
                SELECT cat.id, cat.parent_id, cat.slug, cat.name
                FROM articles a
                JOIN categories cat ON a.category_id = cat.id
                WHERE a.id = $1

                UNION ALL

                -- Traverse up the tree
                SELECT parent.id, parent.parent_id, parent.slug, parent.name
                FROM categories parent
                JOIN cat_hierarchy child ON parent.id = child.parent_id
              )
              SELECT
                a.id,
                a.title,
                a.summary,
                a.content,
                a.slug,
                a.hero_image_path AS image,
                -- Get the level-2 category slug (navigation category) as portal_slug, strip "ji-" prefix
                COALESCE(
                  (SELECT REPLACE(slug, 'ji-', '') FROM cat_hierarchy WHERE parent_id = 64148 LIMIT 1),
                  'encouragement'
                ) AS portal_slug,
                c.name AS category,
                c.slug AS category_slug,
                a.created_at
              FROM articles a
              LEFT JOIN categories c ON a.category_id = c.id
              WHERE a.id = $1`
            : `WITH RECURSIVE cat_hierarchy AS (
                -- Start with the article's direct category
                SELECT cat.id, cat.parent_id, cat.slug, cat.name
                FROM articles a
                JOIN categories cat ON a.category_id = cat.id
                WHERE a.slug = $1

                UNION ALL

                -- Traverse up the tree
                SELECT parent.id, parent.parent_id, parent.slug, parent.name
                FROM categories parent
                JOIN cat_hierarchy child ON parent.id = child.parent_id
              )
              SELECT
                a.id,
                a.title,
                a.summary,
                a.content,
                a.slug,
                a.hero_image_path AS image,
                -- Get the level-2 category slug (navigation category) as portal_slug, strip "ji-" prefix
                COALESCE(
                  (SELECT REPLACE(slug, 'ji-', '') FROM cat_hierarchy WHERE parent_id = 64148 LIMIT 1),
                  'encouragement'
                ) AS portal_slug,
                c.name AS category,
                c.slug AS category_slug,
                a.created_at
              FROM articles a
              LEFT JOIN categories c ON a.category_id = c.id
              WHERE a.slug = $1`;

        const result = await inspirePool.query(query, [isNumeric ? parseInt(idOrSlug) : idOrSlug]);

        if (result.rows.length === 0) {
            return res.status(404).json({ error: 'Article not found' });
        }

        res.json({ success: true, article: result.rows[0] });
    } catch (err) {
        console.error('Error fetching article:', err.message);
        // Fallback to cache when DB is unavailable (e.g. dev)
        const cacheFile = path.join(__dirname, 'data', 'encouragement-cache.json');
        if (fs.existsSync(cacheFile)) {
            try {
                const cached = JSON.parse(fs.readFileSync(cacheFile, 'utf8'));
                const article = cached.find(a => a.id === parseInt(idOrSlug) || a.slug === idOrSlug);
                if (article) return res.json({ success: true, article });
            } catch (_) {}
        }
        res.status(500).json({ error: 'Failed to fetch article' });
    }
});

