/**
 * API: Get all categories (Admin Dashboard)
 *
 * Returns the complete hierarchical category taxonomy from PostgreSQL database.
 * Used by the admin dashboard to display the three-level tree structure:
 *
 * Level 0: Root Categories (2)
 *   - Jubilee Ministries (20 theological domains)
 *   - Business Services (20 business domains)
 *
 * Level 1: Major Domains (40 total)
 *
 * Level 2: Subcategories (729 total)
 *
 * Response includes: id, name, slug, parent_id, level, sort_order, description, created_at
 * Sorted by: level, parent_id (nulls first), sort_order
 */
app.get('/api/admin/categories', async (req, res) => {
    try {
        const { parent_id, level } = req.query;

        let query;
        let params = [];

        if (parent_id !== undefined) {
            // Fetch children of specific parent.
            // When parent is null/empty, return jubileeverse's top-level sections
            // (direct children of JUBILEEVERSE_ROOT_CATEGORY_IDS) instead of all DB roots.
            if (parent_id === 'null' || parent_id === '') {
                query = `
                    SELECT
                        id,
                        name,
                        slug,
                        parent_id,
                        level,
                        sort_order,
                        description,
                        created_at
                    FROM categories
                    WHERE parent_id = ANY($1::int[])
                    ORDER BY name ASC
                `;
                params = [JUBILEEVERSE_ROOT_CATEGORY_IDS];
            } else {
                query = `
                    SELECT
                        id,
                        name,
                        slug,
                        parent_id,
                        level,
                        sort_order,
                        description,
                        created_at
                    FROM categories
                    WHERE parent_id = $1
                    ORDER BY name ASC
                `;
                params = [parent_id];
            }
        } else if (level !== undefined) {
            // Fetch categories at a specific level across all jubileeverse site roots
            query = `
                WITH RECURSIVE cat_tree AS (
                    SELECT id, name, slug, parent_id, level, sort_order, description, created_at
                    FROM categories WHERE id = ANY($1::int[])
                    UNION ALL
                    SELECT c.id, c.name, c.slug, c.parent_id, c.level, c.sort_order, c.description, c.created_at
                    FROM categories c JOIN cat_tree ct ON c.parent_id = ct.id
                )
                SELECT id, name, slug, parent_id, level, sort_order, description, created_at
                FROM cat_tree
                WHERE level = $2
                ORDER BY name ASC
            `;
            params = [JUBILEEVERSE_ROOT_CATEGORY_IDS, level];
        } else {
            // Default: top-level sections (direct children of all jubileeverse site roots)
            query = `
                SELECT
                    id,
                    name,
                    slug,
                    parent_id,
                    level,
                    sort_order,
                    description,
                    created_at
                FROM categories
                WHERE parent_id = ANY($1::int[])
                ORDER BY name ASC
            `;
            params = [JUBILEEVERSE_ROOT_CATEGORY_IDS];
        }

        const result = await pgPool.query(query, params);
        res.json(result.rows);
    } catch (error) {
        console.error('Error fetching categories:', error);
        res.status(500).json({ error: 'Failed to fetch categories', message: error.message });
    }
});

