/**
 * API: Delete category
 *
 * DELETE /api/admin/categories/:id
 *
 * Deletes a category and all its subcategories and articles (cascading delete)
 */
app.delete('/api/admin/categories/:id', async (req, res) => {
    try {
        const { id } = req.params;

        // Get all subcategory IDs recursively
        const subcategoriesResult = await pgPool.query(`
            WITH RECURSIVE category_tree AS (
                SELECT id FROM categories WHERE id = $1
                UNION ALL
                SELECT c.id FROM categories c
                INNER JOIN category_tree ct ON c.parent_id = ct.id
            )
            SELECT id FROM category_tree WHERE id != $1
        `, [id]);

        const allCategoryIds = [id, ...subcategoriesResult.rows.map(r => r.id)];

        // Delete articles in these categories
        await pgPool.query(
            'DELETE FROM articles WHERE category_id = ANY($1)',
            [allCategoryIds]
        );

        // Delete all categories (parent and children)
        await pgPool.query(
            'DELETE FROM categories WHERE id = ANY($1)',
            [allCategoryIds]
        );

        res.json({
            success: true,
            deletedCategoriesCount: allCategoryIds.length
        });
    } catch (error) {
        console.error('Error deleting category:', error);
        res.status(500).json({ error: 'Failed to delete category', message: error.message });
    }
});

