/**
 * API: Get articles by category (with aggregation support)
 *
 * Query Parameters:
 *   - category_id (required): The category ID to fetch articles for
 *   - aggregate (optional): If 'true', includes articles from all child subcategories
 *
 * When a Level 1 domain is selected and aggregate=true:
 *   - Fetches the category and all its Level 2 children
 *   - Returns articles from the selected category AND all child categories
 *   - Useful for showing all articles under a domain
 *
 * Response: Array of article objects with id, category_id, category_name, title, created_at
 */
app.get('/api/admin/articles', async (req, res) => {
    const authPayload = requireReviewer(req, res);
    if (!authPayload) return;
    try {
        const { category_id, aggregate } = req.query;

        if (!category_id) {
            return res.status(400).json({ error: 'category_id parameter is required' });
        }

        let categoryIds = [parseInt(category_id)];

        // If aggregation is requested, get all child categories
        if (aggregate === 'true') {
            const childrenResult = await pgPool.query(`
                SELECT id FROM categories WHERE parent_id = $1
            `, [category_id]);

            if (childrenResult.rows.length > 0) {
                categoryIds = [
                    parseInt(category_id),
                    ...childrenResult.rows.map(row => row.id)
                ];
            }
        }

        // Fetch articles for all relevant categories
        const result = await pgPool.query(`
            SELECT
                a.id,
                a.category_id,
                c.name as category_name,
                c.slug as category_slug,
                a.title,
                a.slug,
                a.author,
                a.content_type,
                a.status,
                a.music_type,
                a.created_at
            FROM articles a
            INNER JOIN categories c ON a.category_id = c.id
            WHERE a.category_id = ANY($1::int[])
            ORDER BY a.created_at DESC
        `, [categoryIds]);

        res.json({
            success: true,
            category_id: parseInt(category_id),
            aggregated: aggregate === 'true',
            count: result.rows.length,
            articles: result.rows
        });
    } catch (error) {
        console.error('Error fetching articles:', error);
        res.status(500).json({ error: 'Failed to fetch articles', message: error.message });
    }
});

