// GET /api/admin/event-logs — Retrieve event logs for debugging
app.get('/api/admin/event-logs', async (req, res) => {
    try {
        const limit = parseInt(req.query.limit) || 100;
        const jobId = req.query.jobId ? parseInt(req.query.jobId) : null;
        const severity = req.query.severity || null;

        let query = `
            SELECT id, timestamp, event_type, severity, component, job_id, article_id,
                   message, details, error_stack
            FROM event_logs
            WHERE 1=1
        `;
        const params = [];

        if (jobId) {
            params.push(jobId);
            query += ` AND job_id = $${params.length}`;
        }

        if (severity) {
            params.push(severity);
            query += ` AND severity = $${params.length}`;
        }

        params.push(limit);
        query += ` ORDER BY timestamp DESC LIMIT $${params.length}`;

        const result = await pgPool.query(query, params);

        res.json({
            count: result.rows.length,
            logs: result.rows
        });
    } catch (err) {
        res.status(500).json({ error: 'Failed to fetch event logs', message: err.message });
    }
});

