/**
 * API: Upload file attachment for article
 *
 * Automatically generates folder structure based on category hierarchy
 * Root: /content/ then nested folders using category slugs
 */

// Configure multer storage with dynamic folder generation
const storage = multer.diskStorage({
    destination: async function (req, file, cb) {
        try {
            const { articleId } = req.params;

            // Get article with category hierarchy
            const articleResult = await pgPool.query(`
                SELECT a.id, a.title, a.category_id, c.name as category_name
                FROM articles a
                INNER JOIN categories c ON a.category_id = c.id
                WHERE a.id = $1
            `, [articleId]);

            if (articleResult.rows.length === 0) {
                return cb(new Error('Article not found'));
            }

            const article = articleResult.rows[0];

            // Create slug from article title
            const titleSlug = article.title
                .toLowerCase()
                .replace(/[^a-z0-9]+/g, '-')
                .replace(/^-|-$/g, '');

            // Build category path by traversing up the hierarchy
            const categoryPath = [];
            let currentCategoryId = article.category_id;

            while (currentCategoryId) {
                const catResult = await pgPool.query(`
                    SELECT id, name, parent_id
                    FROM categories
                    WHERE id = $1
                `, [currentCategoryId]);

                if (catResult.rows.length === 0) break;

                const category = catResult.rows[0];
                // Create slug from category name
                const slug = category.name
                    .toLowerCase()
                    .replace(/[^a-z0-9]+/g, '-')
                    .replace(/^-|-$/g, '');

                categoryPath.unshift(slug);
                currentCategoryId = category.parent_id;
            }

            // Build final path: content/category1/category2/.../content-title
            const uploadPath = path.join(
                __dirname,
                'public',
                'content',
                ...categoryPath,
                titleSlug
            );

            // Create directory if it doesn't exist
            fs.mkdirSync(uploadPath, { recursive: true });

            cb(null, uploadPath);
        } catch (error) {
            console.error('Error creating upload directory:', error);
            cb(error);
        }
    },
    filename: function (req, file, cb) {
        // Keep original filename with timestamp prefix to avoid conflicts
        const timestamp = Date.now();
        const sanitizedName = file.originalname.replace(/[^a-zA-Z0-9.-]/g, '_');
        cb(null, `${timestamp}-${sanitizedName}`);
    }
});

const upload = multer({
    storage: storage,
    limits: {
        fileSize: 50 * 1024 * 1024 // 50MB limit
    }
});

app.post('/api/admin/articles/:articleId/attachments', upload.single('file'), async (req, res) => {
    try {
        if (!req.file) {
            return res.status(400).json({ error: 'No file uploaded' });
        }

        const { articleId } = req.params;

        // Return file info
        res.json({
            success: true,
            file: {
                originalName: req.file.originalname,
                filename: req.file.filename,
                path: req.file.path.replace(__dirname + path.sep + 'public', ''),
                size: req.file.size,
                mimeType: req.file.mimetype
            }
        });
    } catch (error) {
        console.error('Error uploading file:', error);
        res.status(500).json({ error: 'Failed to upload file', message: error.message });
    }
});

/**
 * API: Chat Endpoint — powered by IC LLM (Mistral-7B via InspireCortex at localhost:9001)
 */
app.post('/api/chat', async (req, res) => {
    try {
        const { message, history } = req.body;

        if (!message) {
            return res.status(400).json({ error: 'Message is required' });
        }

        const systemPrompt = `You are a helpful AI assistant for JubileeVerse, a Christian content platform.

Key information about JubileeVerse:
- We create uplifting Christian music through the "Party Giggles" collection
- We have 43 unique animal-themed music albums (Bella's Birthday Bash, Pixie's Praise Party, Flamingo Fiesta, etc.)
- Each album features 11-12 songs with Christian themes and lessons
- Our mission is to share faith, hope, and joy through creative content
- We provide devotionals, Bible-based articles, and spiritual encouragement

Please provide helpful, encouraging, and faith-centered responses. When discussing music albums, characters, or biblical topics, be enthusiastic and positive. Keep responses concise but meaningful.`;

        const priorMessages = (history || []).slice(-10).map(m => ({
            role: m.role,
            content: typeof m.content === 'string' ? m.content : (m.content?.[0]?.text || ''),
        }));

        const messages = [
            { role: 'system', content: systemPrompt },
            ...priorMessages,
        ];
        if (!priorMessages.length || priorMessages[priorMessages.length - 1].content !== message) {
            messages.push({ role: 'user', content: message });
        }

        const icResponse = await callICLLMChat(messages, { maxTokens: 1024 });
        const assistantMessage = icResponse.choices?.[0]?.message?.content?.trim() || '';

        res.json({ success: true, response: assistantMessage });

    } catch (error) {
        console.error('[Chat] IC LLM error:', error.message);
        res.status(500).json({ success: false, error: 'Failed to get AI response', message: error.message });
    }
});

