// =============================================================================
// JUBILEE CHAT API
// =============================================================================

// Credential-shape-aware client construction lives in lib/anthropic-client.js,
// shared with generation-service, persona-router and the inspire generator.
const { buildAnthropicClient, clientFor, credentialChain } = require('./lib/anthropic-client');

const anthropic = buildAnthropicClient();

/**
 * Kimi (MoonshotAI) API helper — OpenAI-compatible endpoint.
 * Used for content rewriting heartbeats (lyric scan, children's story scan,
 * paragraph QC) as primary AI backend while Anthropic credits are managed.
 *
 * Model: moonshot-v1-32k (32k context, supports long articles)
 * Endpoint: https://api.moonshot.cn/v1/chat/completions
 */
async function callKimi(systemPrompt, userContent, maxTokens = 1400) {
    const apiKey = process.env.KIMI_API_KEY;
    if (!apiKey) throw new Error('KIMI_API_KEY not set in environment');
    const axios = require('axios');
    const response = await axios.post('https://api.moonshot.cn/v1/chat/completions', {
        model: 'moonshot-v1-32k',
        max_tokens: maxTokens,
        messages: [
            { role: 'system', content: systemPrompt },
            { role: 'user',   content: userContent }
        ]
    }, {
        headers: {
            'Authorization': `Bearer ${apiKey}`,
            'Content-Type': 'application/json'
        },
        timeout: 90000
    });
    return response.data.choices[0]?.message?.content?.trim() || null;
}

// Chat conversation history (in-memory for now)
const chatHistory = new Map();

app.post('/api/chat/message', async (req, res) => {
    const { message } = req.body;
    const sessionId = req.headers['x-session-id'] || 'default';

    try {
        if (!message || !message.trim()) {
            return res.status(400).json({ error: 'Message is required' });
        }

        // Get or create chat history for this session
        if (!chatHistory.has(sessionId)) {
            chatHistory.set(sessionId, []);
        }

        const history = chatHistory.get(sessionId);

        // Add user message to history (always as string for user messages)
        history.push({
            role: 'user',
            content: message.trim()
        });

        // Keep only last 20 messages to manage context
        // Important: trim pairs to avoid breaking tool_use sequences
        while (history.length > 20) {
            history.shift();
        }

        // Get task context for Jubilee
        const { rows: recentTasks } = await pgPool.query(`
            SELECT id, title, status, created_at, started_at, completed_at
            FROM jv_pulse_tasks
            ORDER BY created_at DESC
            LIMIT 10
        `);

        const taskContext = recentTasks.length > 0
            ? `\n\nCurrent task context:\n${recentTasks.map(t =>
                `- Task #${t.id}: "${t.title}" - Status: ${t.status}`
              ).join('\n')}`
            : '';

        // Create system message for Jubilee
        const systemMessage = `You are Jubilee, an intelligent AI assistant for the JubileeVerse content management system. You help users manage their tasks, monitor progress, and answer questions about their content.

You have access to the following capabilities:
- Task management system with heartbeat execution
- Content categories and articles
- User can create tasks with delivery scheduling (one-time, recurring, etc.)
- You can create and execute tasks using the create_task tool

When a user asks you to do something (like "create articles", "update database", "run a script", "generate content", etc.), use the create_task tool to create a task that will be executed automatically. Be helpful, concise, and professional. When discussing tasks, refer to them by their ID number.${taskContext}

Current date: ${new Date().toLocaleDateString()}`;

        // Define tools in OpenAI format (supported by IC LLM / Mistral-7B)
        const tools = [{
            type: 'function',
            function: {
                name: 'create_task',
                description: 'Creates a new task in the JubileeVerse task management system. Use this when the user asks you to perform an action, create content, run commands, or do anything that requires execution. The task will be automatically executed by an AI-powered task executor that can run CLI commands, scripts, and database operations.',
                parameters: {
                    type: 'object',
                    properties: {
                        title: {
                            type: 'string',
                            description: 'A short, descriptive title for the task (max 100 characters)'
                        },
                        instructions: {
                            type: 'string',
                            description: 'Detailed instructions for what needs to be done. Be specific about files, paths, commands, or operations needed.'
                        },
                        category_location: {
                            type: 'string',
                            description: 'The category or area this task belongs to (optional, defaults to "Jubilee AI Tasks")'
                        }
                    },
                    required: ['title', 'instructions']
                }
            }
        }];

        // Call IC LLM with tools (OpenAI-compatible format)
        let response = await callICLLMChat(history, { maxTokens: 2048, tools });

        let assistantMessage = '';
        let createdTaskId = null;

        // Process tool calls (OpenAI format: finish_reason === 'tool_calls')
        while (response.choices?.[0]?.finish_reason === 'tool_calls') {
            const msg = response.choices[0].message;
            const toolCall = msg.tool_calls?.[0];

            if (toolCall?.function?.name === 'create_task') {
                let args;
                try { args = JSON.parse(toolCall.function.arguments); }
                catch (_) { break; }

                const { title, instructions, category_location } = args;

                // Create the task in database
                const { rows: [createdTask] } = await pgPool.query(`
                    INSERT INTO jv_pulse_tasks (
                        title, instructions, category_location, status, "user",
                        delivery_type, immediate_execution
                    )
                    VALUES ($1, $2, $3, 'pending', 'Jubilee AI', 'one-time', 1)
                    RETURNING id
                `, [title, instructions, category_location || 'Jubilee AI Tasks']);

                createdTaskId = createdTask.id;

                // Start task execution
                executeTaskHeartbeat(createdTaskId);

                // Add assistant tool-call message to history (OpenAI format)
                history.push({ role: 'assistant', content: msg.content || null, tool_calls: msg.tool_calls });

                // Add tool result to history (OpenAI format)
                history.push({
                    role: 'tool',
                    tool_call_id: toolCall.id,
                    name: 'create_task',
                    content: `Task #${createdTaskId} created successfully and execution started. Title: "${title}"`,
                });

                // Get next response from IC LLM
                response = await callICLLMChat(history, { maxTokens: 1024, tools });
            } else {
                break;
            }
        }

        // Extract text response (OpenAI format)
        assistantMessage = response.choices?.[0]?.message?.content?.trim() || '';

        // Add assistant response to history (OpenAI format — plain string)
        history.push({ role: 'assistant', content: assistantMessage });

        res.json({
            response: assistantMessage || 'Task created successfully!',
            sessionId: sessionId,
            taskId: createdTaskId
        });

    } catch (error) {
        console.error('Error processing chat message:', error.message || error);

        // Clear corrupted session history so next request starts fresh
        if (chatHistory.has(sessionId)) {
            chatHistory.delete(sessionId);
            console.log(`Cleared corrupted history for session: ${sessionId}`);
        }

        res.status(500).json({
            error: 'Failed to process message',
            response: "I encountered an error with that request. Your conversation has been reset — please try again."
        });
    }
});

