// =============================================================================
// UTILITY ENDPOINT: Remove empty category (internal use only)
// =============================================================================
app.post('/api/internal/remove-taxonomy-category', async (req, res) => {
    const { title } = req.body;
    if (!title) return res.status(400).json({ error: 'Title required' });

    try {
        // Find the category
        const categoryResult = await pgPool.query(
            "SELECT id FROM jv_taxonomy WHERE title = $1 LIMIT 1",
            [title]
        );

        if (categoryResult.rows.length === 0) {
            return res.status(404).json({ error: 'Category not found' });
        }

        const categoryId = categoryResult.rows[0].id;

        // Find articles in this category
        const articlesResult = await pgPool.query(
            "SELECT co.id, co.title FROM jv_content_objects co JOIN jv_content_taxonomy_map ctm ON co.id = ctm.uuid_object_id WHERE ctm.taxonomy_node_id = $1",
            [categoryId]
        );

        console.log(`[Category Removal] Found ${articlesResult.rows.length} articles to move`);

        // If there are articles, move them to "Covenant & Identity"
        if (articlesResult.rows.length > 0) {
            const covenantResult = await pgPool.query(
                "SELECT id FROM jv_taxonomy WHERE title = 'Covenant & Identity' LIMIT 1"
            );

            if (covenantResult.rows.length === 0) {
                return res.status(400).json({ error: 'Target category not found' });
            }

            const covenantId = covenantResult.rows[0].id;

            // Move articles
            for (const article of articlesResult.rows) {
                await pgPool.query(
                    "UPDATE jv_content_taxonomy_map SET taxonomy_node_id = $1 WHERE uuid_object_id = $2 AND taxonomy_node_id = $3",
                    [covenantId, article.id, categoryId]
                );
                console.log(`[Category Removal] Moved "${article.title}"`);
            }
        }

        // Delete the category
        await pgPool.query(
            "DELETE FROM jv_taxonomy WHERE id = $1",
            [categoryId]
        );

        res.json({ ok: true, message: `Category "${title}" deleted, ${articlesResult.rows.length} articles moved to Covenant & Identity` });
    } catch (err) {
        console.error('[Category Removal] Error:', err.message);
        res.status(500).json({ error: err.message });
    }
});

// POST /api/admin/remove-faith-work-stewardship — ADMIN ONLY: Force removal of "Faith, Work & Stewardship" taxonomy
app.post('/api/admin/remove-faith-work-stewardship', async (req, res) => {
    const actor = await requirePrivileged(req, res); if (!actor) return;
    if (actor.role !== 'admin') return res.status(403).json({ error: 'Admin only' });

    try {
        console.log('[ADMIN] Force removing "Faith, Work & Stewardship" taxonomy...');

        // Step 0: FIND IT FIRST - case-insensitive search
        const findExact = await pgPool.query(
            `SELECT id, name, title, slug FROM jv_taxonomy WHERE LOWER(name) LIKE '%faith, work%' OR LOWER(title) LIKE '%faith, work%'`
        );
        console.log(`[ADMIN] Found entries with "faith, work":`, findExact.rows);

        if (findExact.rows.length === 0) {
            return res.json({
                ok: true,
                message: 'No taxonomy found with "Faith, Work & Stewardship" pattern',
                found_count: 0,
                deleted_associations: 0,
                deleted_taxonomy_nodes: 0
            });
        }

        // Get the actual IDs we found
        const idsToDelete = findExact.rows.map(r => r.id);
        console.log(`[ADMIN] Will delete taxonomy IDs: ${idsToDelete.join(', ')}`);

        // Step 1: Delete all associations
        const delAssoc = await pgPool.query(
            `DELETE FROM jv_content_taxonomy_map
             WHERE taxonomy_node_id = ANY($1)`,
            [idsToDelete]
        );
        console.log(`[ADMIN] Deleted ${delAssoc.rowCount} taxonomy associations`);

        // Step 2: Delete the taxonomy nodes
        const delTax = await pgPool.query(
            `DELETE FROM jv_taxonomy WHERE id = ANY($1)`,
            [idsToDelete]
        );
        console.log(`[ADMIN] Deleted ${delTax.rowCount} taxonomy node(s)`);

        // Step 3: Verify it's gone
        const verify = await pgPool.query(
            `SELECT COUNT(*) as count FROM jv_taxonomy WHERE LOWER(name) LIKE '%faith, work%' OR LOWER(title) LIKE '%faith, work%'`
        );

        res.json({
            ok: true,
            message: 'Faith, Work & Stewardship taxonomy removed',
            found_entries: findExact.rows,
            deleted_associations: delAssoc.rowCount,
            deleted_taxonomy_nodes: delTax.rowCount,
            remaining_count: parseInt(verify.rows[0].count, 10)
        });
    } catch (err) {
        console.error('[ADMIN] Error removing taxonomy:', err.message);
        res.status(500).json({ error: err.message, stack: err.stack });
    }
});

// =============================================================================
// ERROR HANDLING
// =============================================================================

// Postgres connectivity failures (pool exhausted, tunnel down, host unreachable)
// are not the caller's fault and are usually transient — answer 503 so clients
// can retry, rather than a flat 500 that reads as "this request is broken".
const DB_DOWN_CODES = new Set(['ECONNREFUSED', 'ECONNRESET', 'ETIMEDOUT', 'EHOSTUNREACH', 'ENOTFOUND', 'EPIPE']);
function isDatabaseUnavailable(err) {
    if (!err) return false;
    if (DB_DOWN_CODES.has(err.code)) return true;
    return /Connection terminated|timeout exceeded when trying to connect|too many clients|server closed the connection/i
        .test(err.message || '');
}

app.use((err, req, res, next) => {
    console.error(JSON.stringify({ level: 'error', reqId: req.id, msg: err.message, stack: err.stack }));
    // Headers already flushed — hand back to Express so it can close the socket
    // instead of throwing "Cannot set headers after they are sent".
    if (res.headersSent) return next(err);

    const status = isDatabaseUnavailable(err)
        ? 503
        : (Number.isInteger(err.status) && err.status >= 400 && err.status <= 599 ? err.status : 500);

    const message = status === 503
        ? 'The service is temporarily unavailable. Please try again in a moment.'
        : NODE_ENV === 'development' ? err.message : 'Internal server error';

    res.status(status).json({ error: message, reqId: req.id });
});

