// GET /api/verse — Daily verse (deterministic by date)
app.get('/api/verse', (req, res) => {
    const dailyVerses = [
        { text: 'For God so loved the world that he gave his one and only Son, that whoever believes in him shall not perish but have eternal life.', reference: 'John 3:16' },
        { text: 'Trust in the Lord with all your heart and lean not on your own understanding; in all your ways submit to him, and he will make your paths straight.', reference: 'Proverbs 3:5-6' },
        { text: 'I have told you all this, so that in me you may have peace. In this world you will have trouble. But take heart! I have overcome the world.', reference: 'John 16:33' },
        { text: 'For it is by grace you have been saved, through faith—and this is not from yourselves, it is the gift of God—not by works, so that no one can boast.', reference: 'Ephesians 2:8-9' },
        { text: 'The Lord is my shepherd, I lack nothing. He makes me lie down in green pastures, he leads me beside quiet waters, he refreshes my soul.', reference: 'Psalm 23:1-3' },
        { text: 'Do not be anxious about anything, but in every situation, by prayer and petition, with thanksgiving, present your requests to God.', reference: 'Philippians 4:6' },
        { text: 'I can do all this through Christ who gives me strength.', reference: 'Philippians 4:13' },
        { text: 'Jesus answered, "I am the way and the truth and the life. No one comes to the Father except through me."', reference: 'John 14:6' },
        { text: 'And my God will meet all your needs according to the riches of his glory in Christ Jesus.', reference: 'Philippians 4:19' },
        { text: 'Be strong and courageous. Do not be afraid; do not be discouraged, for the Lord your God will be with you wherever you go.', reference: 'Joshua 1:9' }
    ];
    // Deterministic selection based on date (same verse for entire day)
    const today = new Date();
    const dayOfYear = Math.floor((today - new Date(today.getFullYear(), 0, 0)) / 86400000);
    const verseIndex = dayOfYear % dailyVerses.length;
    res.json(dailyVerses[verseIndex]);
});

// POST /api/tts — stream audio from Microsoft Edge Neural TTS
app.post('/api/tts', async (req, res) => {
    const { text, voice: voiceGender = 'female', lang = 'en-US' } = req.body || {};
    if (!text || text.trim().length === 0) return res.status(400).json({ error: 'Text required' });

    // Resolve voice name from map, fallback to English
    const langKey = lang.replace('_', '-');
    const voiceEntry = TTS_VOICE_MAP[langKey] || TTS_VOICE_MAP['en-US'];
    const voiceName = voiceEntry[voiceGender] || voiceEntry.female;

    // Every request opens its own WebSocket to Microsoft, and nothing used to shut
    // it again: eight requests left eight sockets established. Read Aloud makes one
    // request per paragraph, so a single reader working through an article leaked a
    // socket per paragraph and they accumulated for the life of the process — until
    // the file-descriptor limit, which takes the database pool down with it rather
    // than just the audio.
    //
    // Declared out here so the failure paths below close it too: the socket is
    // opened by setMetadata, so a throw anywhere after that leaks one exactly as
    // the success path did.
    let tts = null;
    let ttsClosed = false;
    const closeTts = () => {
        if (ttsClosed || !tts) return;
        ttsClosed = true;
        try {
            tts.close();
        } catch (e) {
            console.warn('[TTS] close failed:', e.message);
        }
    };

    try {
        tts = new MsEdgeTTS();
        await tts.setMetadata(voiceName, OUTPUT_FORMAT.AUDIO_24KHZ_48KBITRATE_MONO_MP3);
        const { audioStream } = await tts.toStream(text.substring(0, 4000));

        // Closed once, on whichever comes first: the audio finishing, the stream
        // failing, or the reader navigating away mid-paragraph.
        res.setHeader('Content-Type', 'audio/mpeg');
        res.setHeader('Cache-Control', 'no-cache');
        audioStream.pipe(res);
        audioStream.on('end', closeTts);
        audioStream.on('close', closeTts);
        audioStream.on('error', (err) => {
            console.error('[TTS] Stream error:', err.message);
            closeTts();
            if (!res.headersSent) res.status(500).json({ error: 'TTS failed' });
        });
        // A reader who skips ahead or leaves abandons the response; without this
        // the synthesis runs to completion into a socket nobody is reading.
        res.on('close', () => {
            closeTts();
            audioStream.destroy?.();
        });
    } catch (err) {
        console.error('[TTS] Error:', err.message);
        closeTts();
        if (!res.headersSent) res.status(500).json({ error: 'TTS failed', message: err.message });
    }
});

// =============================================================================
// ARTICLE TRANSLATION (Claude AI streaming + PostgreSQL cache)
// =============================================================================

// Helper function to determine if a language uses Right-to-Left (RTL) text direction
function isRTLLanguage(languageCode) {
    const rtlLanguages = [
        'ar',      // Arabic
        'he', 'he-IL',  // Hebrew
        'fa', 'fa-IR',  // Persian/Farsi
        'ur', 'ur-PK',  // Urdu
        'yi',      // Yiddish
        'arc',     // Aramaic
        'dv',      // Dhivehi/Maldivian
        'ku',      // Kurdish (Sorani)
        'ps'       // Pashto
    ];
    return rtlLanguages.includes(languageCode.toLowerCase());
}

// Ids above this floor are hashes of a non-numeric id, never a real serial.
// Matches reactionIdForSlug() in src/lib/homeFeed.ts, which already hands the
// backend hashed ids in this range for views and reactions.
const HASHED_ID_FLOOR = 1_000_000_000;

/** FNV-1a 32-bit, folded into HASHED_ID_FLOOR..2e9. Same scheme as the frontend. */
function hashIdToInt(str) {
    let hash = 2166136261;
    for (let i = 0; i < str.length; i++) {
        hash ^= str.charCodeAt(i);
        hash = Math.imul(hash, 16777619);
    }
    return HASHED_ID_FLOOR + (Math.abs(hash) % 1_000_000_000);
}

/**
 * How one article id maps onto the translation cache.
 *
 * `article_translations.article_id` is INTEGER, but a reader addresses an
 * article by three different id shapes: a backend serial, a published bundle's
 * `category__slug`, and a `jv_content_objects` UUID. The previous code ran
 * parseInt() over all of them, so the latter two became NaN — which pg sends as
 * the literal string "NaN", failing the query outright. Every lookup for those
 * articles therefore reported a cache miss, and nothing was ever written back.
 *
 * Non-numeric ids get a stable hashed key instead, which needs no schema change
 * and cannot collide with a serial id.
 *
 * `isNativeInteger` stays separate from the cache key on purpose: only a real
 * serial may be used to read the original text out of `articles`. A hashed id
 * that happened to land on an existing row would otherwise translate an
 * unrelated article.
 */
function translationIdentity(idStr) {
    const raw = String(idStr ?? '').trim();
    const numeric = /^\d+$/.test(raw) ? parseInt(raw, 10) : null;
    return {
        raw,
        isUUID: isUUID(raw),
        isNativeInteger: numeric !== null && numeric > 0 && numeric < HASHED_ID_FLOOR,
        cacheKey: numeric !== null && numeric > 0 ? numeric : hashIdToInt(raw),
    };
}

const { stripTranslationArtifacts, isImplausiblyShort } = require('./lib/translation-artifacts');

// GET /api/articles/:id/translation/:lang — check cache and increment hit_count
app.get('/api/articles/:id/translation/:lang', async (req, res) => {
    const { id, lang } = req.params;
    const ident = translationIdentity(id);
    const cacheKey = ident.cacheKey;
    // Same rule as the POST below: only ids whose original the server can read
    // are answered from the id-keyed cache. Anything else falls through to a
    // miss, and the POST path serves it from the content-addressed cache.
    if (!(ident.isNativeInteger || ident.isUUID)) {
        return res.json({ found: false });
    }
    try {
        const result = await pgPool.query(
            `SELECT translated_title, translated_content, is_rtl, translated_source_badge, translated_category FROM article_translations WHERE article_id = $1 AND language_code = $2`,
            [cacheKey, lang]
        );
        // The widget asks here before it streams, so this is the first place a
        // stored wrapper tag would reach a reader. Cleaned on read like the
        // POST's cache branches, which is what lets rows written before the
        // strip existed serve clean text.
        const cleaned = result.rows.length > 0
            ? stripTranslationArtifacts(result.rows[0].translated_content)
            : '';
        if (cleaned) {
            const row = result.rows[0];
            // Increment hit count (fire-and-forget)
            pgPool.query(
                `UPDATE article_translations SET hit_count = COALESCE(hit_count, 0) + 1 WHERE article_id = $1 AND language_code = $2`,
                [cacheKey, lang]
            ).catch(e => console.error('[Translation] hit_count update error:', e.message));
            res.json({
                found: true,
                title: row.translated_title,
                content: cleaned,
                isRtl: row.is_rtl,
                sourceBadge: row.translated_source_badge,
                category: row.translated_category
            });
        } else {
            // Reported as a miss when a row exists but holds nothing once the
            // wrapper is off, so the widget re-translates instead of showing an
            // empty article. Debris that is not empty — a row whose whole body
            // was `<budget:token_budget>200000</budget:token_budget>` — is caught
            // by the length check on the write path, which is where the original
            // is in scope to compare against.
            res.json({ found: false });
        }
    } catch (err) {
        console.error('[Translation] Cache lookup error:', err.message);
        res.json({ found: false });
    }
});

// Helper: detect if string is a UUID (RFC 4122)
function isUUID(str) {
    const uuidRegex = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
    return uuidRegex.test(str);
}

// POST /api/articles/:id/translate — stream Claude translation via SSE
app.post('/api/articles/:id/translate', async (req, res) => {
    const idStr = req.params.id;
    const ident = translationIdentity(idStr);
    const articleId = ident.cacheKey;
    const { language_code, language_name, fallback_title, fallback_content, source_badge, category_label } = req.body || {};
    if (!language_code || !language_name) {
        return res.status(400).json({ error: 'language_code and language_name required' });
    }

    res.setHeader('Content-Type', 'text/event-stream');
    res.setHeader('Cache-Control', 'no-cache');
    res.setHeader('Connection', 'keep-alive');
    // Reverse proxies buffer a streamed body by default, which holds every event
    // back until the translation finishes and loses the point of streaming.
    res.setHeader('X-Accel-Buffering', 'no');
    res.flushHeaders?.();

    // The response can already be over — the request timeout answers 503 on its
    // own, and a reader who navigates away closes the socket. Writing then
    // throws inside the stream loop, and the throw used to land in the catch
    // below, which wrote again.
    const sendEvent = (data) => {
        if (res.writableEnded) return false;
        res.write(`data: ${JSON.stringify(data)}\n\n`);
        return true;
    };

    try {
        // Race-condition guard: check the id-keyed cache first, but only for the
        // id shapes whose original text this server can read for itself. Those
        // are the only entries it can have written from a trustworthy source —
        // and rows an earlier build stored under a hashed id came from a caller's
        // request body, so they are not served again.
        const idKeyedCacheUsable = ident.isNativeInteger || ident.isUUID;
        const cached = idKeyedCacheUsable
            ? await pgPool.query(
                `SELECT translated_title, translated_content, is_rtl, translated_source_badge, translated_category FROM article_translations WHERE article_id = $1 AND language_code = $2`,
                [articleId, language_code]
            )
            : { rows: [] };
        // Cleaned on the way out as well as in. Rows written before the strip
        // existed still hold a model's wrapper tag, and a cache hit is the only
        // path most readers take — sanitizing the write alone would leave those
        // rows showing it forever. An entry that is nothing but a wrapper falls
        // through to a fresh translation rather than being served as one.
        const cachedContent = cached.rows.length > 0
            ? stripTranslationArtifacts(cached.rows[0].translated_content)
            : '';
        if (cachedContent) {
            // Increment hit count for cached translation
            pgPool.query(
                `UPDATE article_translations SET hit_count = COALESCE(hit_count, 0) + 1 WHERE article_id = $1 AND language_code = $2`,
                [articleId, language_code]
            ).catch(e => console.error('[Translation] hit_count update error:', e.message));
            sendEvent({
                type: 'cached',
                title: cached.rows[0].translated_title,
                content: cachedContent,
                isRtl: cached.rows[0].is_rtl,
                sourceBadge: cached.rows[0].translated_source_badge,
                category: cached.rows[0].translated_category
            });
            return res.end();
        }

        // Fetch original article: try DB first, fall back to client-provided content.
        // `serverSourced` decides whether the result may be written to the shared
        // cache below — see the note there.
        let title, content;
        let serverSourced = false;
        if (ident.isNativeInteger) {
            // Legacy: fetch from inspirePool articles table
            const articleResult = await inspirePool.query(
                `SELECT title, content FROM articles WHERE id = $1`,
                [articleId]
            );
            if (articleResult.rows.length > 0) {
                title = articleResult.rows[0].title;
                content = articleResult.rows[0].content;
                serverSourced = !!(title && content);
            }
        } else if (ident.isUUID) {
            // UUID-based: fetch from pgPool jv_content_objects
            const articleResult = await pgPool.query(
                `SELECT title, extension_data FROM jv_content_objects WHERE id = $1 AND status = 'published'`,
                [ident.raw]
            );
            if (articleResult.rows.length > 0) {
                title = articleResult.rows[0].title;
                const ext = articleResult.rows[0].extension_data || {};
                content = ext.body || '';
                serverSourced = !!(title && content);
            }
        }
        // Fall back to content sent by client (for articles not in DB or as override)
        if (!title && fallback_title) title = fallback_title;
        if (!content && fallback_content) content = fallback_content;
        if (!title || !content) {
            sendEvent({ type: 'error', message: 'Article not found' });
            return res.end();
        }

        // Content-addressed cache for articles the backend cannot read itself.
        //
        // Keying those by article id would be unsafe (see the note at the write
        // below), but keying them by a hash of the very text being translated is
        // not: an entry can only ever be served back to a request that supplied
        // the identical source, so the worst a forged body can do is cache a
        // translation of itself. That restores caching for CDN news and
        // published bundles, which is most of what readers open — and without it
        // every non-English reader re-translates every article on every visit.
        const sourceHash = serverSourced
            ? null
            : crypto.createHash('sha1').update(`${title}\n${content}`).digest('hex');
        if (sourceHash) {
            try {
                await pgPool.query(`
                    CREATE TABLE IF NOT EXISTS article_translation_bodies (
                        source_hash             TEXT NOT NULL,
                        language_code           TEXT NOT NULL,
                        translated_title        TEXT NOT NULL,
                        translated_content      TEXT NOT NULL,
                        is_rtl                  BOOLEAN,
                        translated_source_badge TEXT,
                        translated_category     TEXT,
                        hit_count               INTEGER DEFAULT 1,
                        created_at              TIMESTAMPTZ DEFAULT NOW(),
                        PRIMARY KEY (source_hash, language_code)
                    )
                `);
                const byBody = await pgPool.query(
                    `SELECT translated_title, translated_content, is_rtl, translated_source_badge, translated_category
                     FROM article_translation_bodies WHERE source_hash = $1 AND language_code = $2`,
                    [sourceHash, language_code]
                );
                // Cleaned on read, and skipped when nothing survives, for the
                // same reasons as the id-keyed cache above.
                const byBodyContent = byBody.rows.length > 0
                    ? stripTranslationArtifacts(byBody.rows[0].translated_content)
                    : '';
                if (byBodyContent) {
                    pgPool.query(
                        `UPDATE article_translation_bodies SET hit_count = COALESCE(hit_count, 0) + 1
                         WHERE source_hash = $1 AND language_code = $2`,
                        [sourceHash, language_code]
                    ).catch(e => console.error('[Translation] body hit_count error:', e.message));
                    sendEvent({
                        type: 'cached',
                        title: byBody.rows[0].translated_title,
                        content: byBodyContent,
                        isRtl: byBody.rows[0].is_rtl,
                        sourceBadge: byBody.rows[0].translated_source_badge,
                        category: byBody.rows[0].translated_category
                    });
                    return res.end();
                }
            } catch (e) {
                // A cache that is unavailable must never block a translation.
                console.warn('[Translation] body cache read failed:', e.message);
            }
        }

        // Try translation: Anthropic first, OpenAI fallback, then friendly error
        let accumulated = '';
        let titleExtracted = false;
        let translatedTitle = '';
        let translatedSourceBadge = '';
        let translatedCategory = '';
        let translationSucceeded = false;
        const isRtl = isRTLLanguage(language_code);

        // Build translation prompt with metadata
        const userPrompt = [];
        userPrompt.push(`TITLE:${title}`);
        if (source_badge) userPrompt.push(`SOURCE:${source_badge}`);
        if (category_label) userPrompt.push(`CATEGORY:${category_label}`);
        userPrompt.push(''); // blank line
        if (!isRtl) userPrompt.push('CONTENT:');
        userPrompt.push(content);
        const promptText = userPrompt.join('\n');

        // Attempt 1: Anthropic Claude Haiku (fastest streaming)
        try {
            let systemInstr = `You are a professional translator. Translate the following article into ${language_name}. Output format:\n`;
            systemInstr += `TITLE:[translated title]\n`;
            if (source_badge) systemInstr += `SOURCE:[translated source badge]\n`;
            if (category_label) systemInstr += `CATEGORY:[translated category]\n`;
            systemInstr += `\n[translated content, preserving any HTML tags that are already in it exactly as-is]\n`;
            // A model wrapped a whole translation in a tag it made up
            // (<budget:token_budget>), which then rendered as a link in front of
            // the article. stripTranslationArtifacts() removes it either way;
            // asking plainly is the cheaper half of the fix.
            //
            // The body is framed as CONTENT: on the way in, and a model shown
            // that label answers with it — which is how an Arabic article came
            // to open on the word CONTENT:. Only the three header lines above
            // are wanted back, so say which.
            systemInstr += `Do not add any other commentary, and do not wrap the output in any tag of your own. `;
            systemInstr += `The translated content follows the blank line on its own, with no CONTENT: label in front of it.`;

            const stream = anthropic.messages.stream({
                model: 'claude-haiku-4-5-20251001',
                max_tokens: 8192,
                system: systemInstr,
                messages: [{ role: 'user', content: promptText }]
            });

            for await (const event of stream) {
                if (event.type === 'content_block_delta' && event.delta?.type === 'text_delta') {
                    const chunk = event.delta.text;
                    accumulated += chunk;
                    sendEvent({ type: 'chunk', text: chunk });

                    // Extract metadata (title, source, category) from first lines
                    if (!titleExtracted && accumulated.includes('\n\n')) {
                        const lines = accumulated.split('\n');
                        for (const line of lines) {
                            if (line.startsWith('TITLE:') && !translatedTitle) {
                                translatedTitle = line.replace('TITLE:', '').trim();
                            } else if (line.startsWith('SOURCE:') && !translatedSourceBadge) {
                                translatedSourceBadge = line.replace('SOURCE:', '').trim();
                            } else if (line.startsWith('CATEGORY:') && !translatedCategory) {
                                translatedCategory = line.replace('CATEGORY:', '').trim();
                            }
                        }
                        if (translatedTitle) {
                            titleExtracted = true;
                            sendEvent({
                                type: 'metadata',
                                title: translatedTitle,
                                sourceBadge: translatedSourceBadge,
                                category: translatedCategory
                            });
                        }
                    }
                }
            }
            translationSucceeded = true;
            console.log('[Translation] Anthropic succeeded');
        } catch (anthropicErr) {
            console.log(`[Translation] Anthropic failed (${anthropicErr.message}), trying OpenAI...`);

            // Attempt 2: OpenAI GPT-4 Turbo
            try {
                const OpenAI = require('openai');
                const openai = new OpenAI({
                    apiKey: process.env.OPENAI_API_KEY_PRIMARY || process.env.OPENAI_API_KEY_BACKUP
                });

                let systemInstr = `You are a professional translator. Translate the following article into ${language_name}. Output format:\n`;
                systemInstr += `TITLE:[translated title]\n`;
                if (source_badge) systemInstr += `SOURCE:[translated source badge]\n`;
                if (category_label) systemInstr += `CATEGORY:[translated category]\n`;
                systemInstr += `\n[translated content, preserving any HTML tags that are already in it exactly as-is]\n`;
                // A model wrapped a whole translation in a tag it made up
                // (<budget:token_budget>), which then rendered as a link in front
                // of the article. stripTranslationArtifacts() removes it either
                // way; asking plainly is the cheaper half of the fix. The
                // CONTENT: label the body is framed with on the way in comes
                // back the same way, so it is ruled out here too.
                systemInstr += `Do not add any other commentary, and do not wrap the output in any tag of your own. `;
                systemInstr += `The translated content follows the blank line on its own, with no CONTENT: label in front of it.`;

                const completion = await openai.chat.completions.create({
                    model: process.env.OPENAI_TRANSLATE_MODEL || 'gpt-4o',
                    messages: [{
                        role: 'system',
                        content: systemInstr
                    }, {
                        role: 'user',
                        content: promptText
                    }],
                    max_tokens: 8192,  // gpt-4o supports larger completions — avoid truncating long articles
                    stream: true
                });

                for await (const chunk of completion) {
                    const text = chunk.choices[0]?.delta?.content || '';
                    if (text) {
                        accumulated += text;
                        sendEvent({ type: 'chunk', text });

                        // Extract metadata (title, source, category) from first lines
                        if (!titleExtracted && accumulated.includes('\n\n')) {
                            const lines = accumulated.split('\n');
                            for (const line of lines) {
                                if (line.startsWith('TITLE:') && !translatedTitle) {
                                    translatedTitle = line.replace('TITLE:', '').trim();
                                } else if (line.startsWith('SOURCE:') && !translatedSourceBadge) {
                                    translatedSourceBadge = line.replace('SOURCE:', '').trim();
                                } else if (line.startsWith('CATEGORY:') && !translatedCategory) {
                                    translatedCategory = line.replace('CATEGORY:', '').trim();
                                }
                            }
                            if (translatedTitle) {
                                titleExtracted = true;
                                sendEvent({
                                    type: 'metadata',
                                    title: translatedTitle,
                                    sourceBadge: translatedSourceBadge,
                                    category: translatedCategory
                                });
                            }
                        }
                    }
                }
                translationSucceeded = true;
                console.log('[Translation] OpenAI succeeded');
            } catch (openaiErr) {
                console.error(`[Translation] Both APIs failed - Anthropic: ${anthropicErr.message}, OpenAI: ${openaiErr.message}`);
                sendEvent({ type: 'error', message: 'Unable to Translate at this Time' });
                return res.end();
            }
        }

        if (!translationSucceeded) {
            sendEvent({ type: 'error', message: 'Unable to Translate at this Time' });
            return res.end();
        }

        // Parse final content and extract any remaining metadata
        const lines = accumulated.split('\n');
        let contentStartIndex = 0;

        // Extract metadata from first lines if not already done
        for (let i = 0; i < lines.length; i++) {
            const line = lines[i].trim();
            if (line.startsWith('TITLE:') && !translatedTitle) {
                translatedTitle = line.replace('TITLE:', '').trim();
            } else if (line.startsWith('SOURCE:') && !translatedSourceBadge) {
                translatedSourceBadge = line.replace('SOURCE:', '').trim();
            } else if (line.startsWith('CATEGORY:') && !translatedCategory) {
                translatedCategory = line.replace('CATEGORY:', '').trim();
            } else if (line === '' && i > 0) {
                // First blank line after metadata marks start of content
                contentStartIndex = i + 1;
                break;
            }
        }

        // The header parse above lifts off TITLE:/SOURCE:/CATEGORY: and takes
        // the rest as content, so anything else the model volunteered — a tag it
        // wrapped its own answer in — is still in here. Strip it before the
        // caches below, which is what turned one bad response into a permanent
        // one.
        const translatedContent = stripTranslationArtifacts(
            lines.slice(contentStartIndex).join('\n').trim(),
        );
        if (!translatedTitle) translatedTitle = title; // Fallback to original
        translatedTitle = stripTranslationArtifacts(translatedTitle);

        // Two caches, and which one is written turns on where the original came
        // from.
        //
        // Text the server read out of the database is keyed by article id, as
        // before. Text the caller supplied is not: this endpoint is public, and
        // for a published bundle or a CDN news item the "original" is whatever
        // `fallback_content` was posted — that article lives on the CDN, which
        // Express cannot see. Keying that by article id would let anyone replace
        // the stored translation every later reader is served, and the reader
        // renders an HTML body verbatim (dangerouslySetInnerHTML in
        // ArticleReader), so the replacement would execute. Keyed by a hash of
        // the source text instead, a forged body can only ever collide with
        // itself.
        // A response can be debris rather than a translation, and caching that is
        // what turns a single bad response into a permanent one. Checked against
        // the original's length, which is why this sits here and not on the read
        // paths — the source is in scope only at the point it was translated.
        if (isImplausiblyShort(translatedContent, content)) {
            console.warn(
                `[Translation] implausible result for ${language_code}: ` +
                `${translatedContent.length} chars from ${content.length}; not cached`
            );
            sendEvent({ type: 'error', message: 'Unable to Translate at this Time' });
            return res.end();
        }

        if (serverSourced) {
            await pgPool.query(
                `INSERT INTO article_translations (article_id, language_code, language_name, translated_title, translated_content, is_rtl, translated_source_badge, translated_category, hit_count)
                 VALUES ($1, $2, $3, $4, $5, $6, $7, $8, 1)
                 ON CONFLICT (article_id, language_code) DO UPDATE
                 SET translated_title = EXCLUDED.translated_title,
                     translated_content = EXCLUDED.translated_content,
                     is_rtl = EXCLUDED.is_rtl,
                     translated_source_badge = EXCLUDED.translated_source_badge,
                     translated_category = EXCLUDED.translated_category`,
                [articleId, language_code, language_name, translatedTitle, translatedContent, isRtl, translatedSourceBadge || null, translatedCategory || null]
            );
        } else if (sourceHash) {
            // Best-effort: a cache write must never fail the translation the
            // reader is already receiving.
            pgPool.query(
                `INSERT INTO article_translation_bodies (source_hash, language_code, translated_title, translated_content, is_rtl, translated_source_badge, translated_category, hit_count)
                 VALUES ($1, $2, $3, $4, $5, $6, $7, 1)
                 ON CONFLICT (source_hash, language_code) DO NOTHING`,
                [sourceHash, language_code, translatedTitle, translatedContent, isRtl, translatedSourceBadge || null, translatedCategory || null]
            ).catch(e => console.warn('[Translation] body cache write failed:', e.message));
        }

        sendEvent({
            type: 'done',
            title: translatedTitle,
            content: translatedContent,
            isRtl,
            sourceBadge: translatedSourceBadge,
            category: translatedCategory
        });
        res.end();
    } catch (err) {
        console.error('[Translation] Error:', err.message);
        // sendEvent is a no-op once the response is over, so a socket that closed
        // mid-stream ends the request here instead of throwing again.
        sendEvent({ type: 'error', message: err.message });
        if (!res.writableEnded) res.end();
    }
});

// Site-wide UI string translation (batch) — same mechanism as the article
// translation above: Anthropic Claude Haiku primary, OpenAI fallback, with a
// PostgreSQL cache (ui_translations) so common UI strings are translated once.
// Request:  { texts: string[], targetLang, targetLangName }
// Response: { translations: { "<original>": "<translated>" } }
app.post('/api/translate-batch', async (req, res) => {
    try {
        const { texts, targetLang, targetLangName } = req.body || {};
        if (!Array.isArray(texts) || texts.length === 0 || !targetLang || !targetLangName) {
            return res.status(400).json({ error: 'texts, targetLang, targetLangName required' });
        }
        // English needs no translation.
        if (String(targetLang).toLowerCase().startsWith('en')) {
            return res.json({ translations: {} });
        }

        const unique = [...new Set(texts.map(t => String(t || '').trim()).filter(Boolean))].slice(0, 200);
        if (unique.length === 0) return res.json({ translations: {} });

        const translations = {};
        const hashOf = (s) => crypto.createHash('sha1').update(`${targetLang}:${s}`).digest('hex');

        // Lazily ensure the cache table exists (idempotent).
        try {
            await pgPool.query(`
                CREATE TABLE IF NOT EXISTS ui_translations (
                    language_code   TEXT NOT NULL,
                    source_hash     TEXT NOT NULL,
                    source_text     TEXT NOT NULL,
                    translated_text TEXT NOT NULL,
                    created_at      TIMESTAMPTZ DEFAULT NOW(),
                    PRIMARY KEY (language_code, source_hash)
                )
            `);
        } catch (e) {
            console.warn('[translate-batch] cache table ensure failed:', e.message);
        }

        // 1) Serve what we can from cache.
        const hashes = unique.map(hashOf);
        try {
            const cached = await pgPool.query(
                `SELECT source_text, translated_text FROM ui_translations WHERE language_code = $1 AND source_hash = ANY($2)`,
                [targetLang, hashes]
            );
            for (const row of cached.rows) translations[row.source_text] = row.translated_text;
        } catch (e) {
            console.warn('[translate-batch] cache read failed:', e.message);
        }

        // 2) Translate the misses with the LLM (Anthropic -> OpenAI fallback).
        const misses = unique.filter(t => !(t in translations));
        if (misses.length > 0) {
            const systemInstr =
                `You are a professional translator for a website UI. Translate each string in the ` +
                `given JSON array into ${targetLangName}. Return ONLY a JSON object mapping every ` +
                `original string (exactly as provided) to its ${targetLangName} translation. ` +
                `Preserve punctuation, casing style, and any placeholders. No commentary.`;
            const userPayload = JSON.stringify(misses);
            let mapText = '';

            try {
                const msg = await anthropic.messages.create({
                    model: 'claude-haiku-4-5-20251001',
                    max_tokens: 8192,
                    system: systemInstr,
                    messages: [{ role: 'user', content: userPayload }]
                });
                mapText = (msg.content || []).map(b => b.text || '').join('');
            } catch (anthropicErr) {
                console.log(`[translate-batch] Anthropic failed (${anthropicErr.message}), trying OpenAI...`);
                try {
                    const OpenAI = require('openai');
                    const openai = new OpenAI({
                        apiKey: process.env.OPENAI_API_KEY_PRIMARY || process.env.OPENAI_API_KEY_BACKUP
                    });
                    const completion = await openai.chat.completions.create({
                        model: process.env.OPENAI_TRANSLATE_MODEL || 'gpt-4o',
                        response_format: { type: 'json_object' },
                        messages: [
                            { role: 'system', content: systemInstr },
                            { role: 'user', content: userPayload }
                        ],
                        max_tokens: 4096
                    });
                    mapText = completion.choices[0]?.message?.content || '';
                } catch (openaiErr) {
                    console.error(`[translate-batch] Both APIs failed - Anthropic: ${anthropicErr.message}, OpenAI: ${openaiErr.message}`);
                }
            }

            // Parse the model's JSON map (tolerate code fences / surrounding text).
            if (mapText) {
                try {
                    const jsonStart = mapText.indexOf('{');
                    const jsonEnd = mapText.lastIndexOf('}');
                    const slice = jsonStart >= 0 && jsonEnd > jsonStart ? mapText.slice(jsonStart, jsonEnd + 1) : mapText;
                    const parsed = JSON.parse(slice);
                    const toStore = [];
                    for (const src of misses) {
                        const tr = parsed[src];
                        if (typeof tr === 'string' && tr.trim()) {
                            translations[src] = tr;
                            toStore.push({ src, tr });
                        }
                    }
                    // 3) Persist new translations (best-effort).
                    if (toStore.length > 0) {
                        const values = [];
                        const params = [];
                        let i = 1;
                        for (const { src, tr } of toStore) {
                            values.push(`($${i++}, $${i++}, $${i++}, $${i++})`);
                            params.push(targetLang, hashOf(src), src, tr);
                        }
                        pgPool.query(
                            `INSERT INTO ui_translations (language_code, source_hash, source_text, translated_text)
                             VALUES ${values.join(',')}
                             ON CONFLICT (language_code, source_hash) DO NOTHING`,
                            params
                        ).catch(e => console.warn('[translate-batch] cache write failed:', e.message));
                    }
                } catch (parseErr) {
                    console.warn('[translate-batch] parse failed:', parseErr.message);
                }
            }
        }

        // The request timeout may already have answered on our behalf; writing
        // again throws ERR_HTTP_HEADERS_SENT, and that throw used to reach the
        // catch below, which wrote a third time and took the process down.
        if (res.headersSent) return;

        // Asked to translate something and came back with nothing at all.
        //
        // This used to answer 200 with an empty map: both providers could be
        // failing — a missing key on one host, an expired token — and the client
        // would see a successful response, apply nothing, log nothing, and leave
        // the page in English. The picker looked broken with no trace anywhere,
        // which is exactly how an environment-specific outage hides. A status the
        // client already treats as a failure puts it in the browser console and
        // in this log. Partial results still answer 200, so one bad string never
        // costs a page its other translations.
        if (misses.length > 0 && Object.keys(translations).length === 0) {
            console.error(
                `[translate-batch] produced no translations for ${misses.length} string(s) ` +
                `into ${targetLang}. Both providers failed or returned nothing — check ` +
                `ANTHROPIC_API_KEY / OPENAI_API_KEY_PRIMARY on THIS host.`
            );
            return res.status(502).json({ error: 'translation_unavailable', translations: {} });
        }
        return res.json({ translations });
    } catch (err) {
        console.error('[translate-batch] error:', err.message);
        if (res.headersSent) return;
        return res.status(500).json({ error: 'Translation failed', translations: {} });
    }
});

