// Category portal pages - /:category/ or /:category/index.html
app.get(['/:category/', '/:category/index.html'], async (req, res, next) => {
    const category = req.params.category;

    // Skip known non-portal paths
    const SKIP = new Set(['api','admin','images','hope-restored','purpose-driven','live-inspired',
        'lets-celebrate','home','cockpit','backoffice','auth','idp','internal',
        'prayer','music','radio','search','review']);
    if (SKIP.has(category)) return next();

    try {
        // Check both JV taxonomy nodes (pgPool) and jubileeinspire categories (inspirePool)
        const [jvResult, inspireResult] = await Promise.all([
            pgPool.query(`SELECT id FROM jv_taxonomy WHERE slug = $1 LIMIT 1`, [category]),
            inspirePool.query(`SELECT id FROM categories WHERE slug = $1 LIMIT 1`, [category]),
        ]);

        if (jvResult.rows.length > 0 || inspireResult.rows.length > 0) {
            res.sendFile(path.join(__dirname, 'public', 'index.html'));
        } else {
            res.redirect('/');
        }
    } catch (error) {
        console.error('[Route] Error validating category slug:', error.message);
        res.sendFile(path.join(__dirname, 'public', 'index.html'));
    }
});

// Article pages - /:category/:slug.html
app.get('/:category/:slug.html', async (req, res, next) => {
    const { category, slug } = req.params;

    // Skip if it's an API route
    if (category === 'api' || category === 'admin') {
        return next();
    }

    try {
        // First try to find jv_content_objects article with this slug
        const jvResult = await pgPool.query(
            `SELECT co.id, co.title, co.slug, co.summary, co.extension_data,
                    jt.id as taxonomy_id, jt.slug as taxonomy_slug, jt.title as taxonomy_title
             FROM jv_content_objects co
             LEFT JOIN jv_content_taxonomy_map ctm ON ctm.uuid_object_id = co.id
             LEFT JOIN jv_taxonomy jt ON jt.id = ctm.taxonomy_node_id
             WHERE co.slug = $1 AND co.object_type = 'article' AND co.status = 'published'
             LIMIT 1`,
            [slug]
        );

        if (jvResult.rows.length > 0) {
            const article = jvResult.rows[0];
            const taxonomySlug = article.taxonomy_slug;

            // Validate that the category slug in the URL matches the article's taxonomy
            if (taxonomySlug === category) {
                // Article found and category matches - store in sessionStorage and serve the article page
                res.setHeader('Content-Type', 'text/html; charset=utf-8');
                const fs = require('fs');
                let html = fs.readFileSync(path.join(__dirname, 'public', 'article.html'), 'utf-8');

                // Inject article data into HTML for client-side rendering
                const articleData = {
                    id: article.id,
                    title: article.title,
                    slug: article.slug,
                    summary: article.summary,
                    imageUrl: article.extension_data?.hero_image_path || '',
                    storyCluster: article.taxonomy_title || 'Faith',
                    isJVContent: true,
                };

                // Inject script to set sessionStorage before other scripts run
                const injectionScript = `<script>
                  sessionStorage.setItem('selectedArticle', ${JSON.stringify(JSON.stringify(articleData))});
                </script>`;
                html = html.replace('</head>', injectionScript + '</head>');

                res.send(html);
            } else if (taxonomySlug) {
                // Category mismatch - redirect to correct URL
                res.redirect(`/${taxonomySlug}/${slug}.html`);
            } else {
                // No taxonomy found - serve 404
                res.status(404).sendFile(path.join(__dirname, 'public', 'index.html'));
            }
        } else {
            // Not found in jv_content_objects, try legacy articles table
            const legacyResult = await inspirePool.query(
                `SELECT a.id, a.title, a.content, a.category_id, a.created_at, c.slug AS category_slug
                 FROM articles a
                 LEFT JOIN categories c ON a.category_id = c.id
                 WHERE a.slug = $1
                 LIMIT 1`,
                [slug]
            );

            if (legacyResult.rows.length > 0) {
                const article = legacyResult.rows[0];

                // Validate that the category slug in the URL matches the article's category
                if (article.category_slug === category) {
                    // Article found and category matches - serve the article page
                    res.sendFile(path.join(__dirname, 'public', 'article.html'));
                } else {
                    // Category mismatch - redirect to correct URL
                    res.redirect(`/${article.category_slug}/${slug}.html`);
                }
            } else {
                // Article not found - serve 404 or redirect to homepage
                res.status(404).sendFile(path.join(__dirname, 'public', 'index.html'));
            }
        }
    } catch (error) {
        console.error('[Route] Error fetching article by slug:', error.message);
        next();
    }
});

