// =============================================================================

// /admin — client-side role check redirects privileged users to /backoffice/, others to /signin
app.get('/admin', async (req, res) => {
    res.send(`<!doctype html><html><head><meta charset="utf-8"><title>Redirecting…</title>
<script>
  try {
    var a = JSON.parse(localStorage.getItem('jubileeVerseAuth') || '{}');
    var PRIV = ['admin','site_owner','publisher','reviewer','editor','persona_operator'];
    if (a.authenticated && a.user && PRIV.indexOf(a.user.role) !== -1) {
      window.location.replace('/backoffice/');
    } else {
      window.location.replace('/signin.html?next=/admin');
    }
  } catch(e) { window.location.replace('/signin.html?next=/admin'); }
</script></head><body></body></html>`);
});

// /cockpit → /backoffice redirect (backward compat)
app.use('/cockpit', (req, res) => {
    res.redirect(301, '/backoffice' + req.path);
});

// Serve Back Office React SPA (production build)
// Assets (index-*.js, *.css) have content hashes — cache them for 1 year.
// index.html must never be cached so browsers always get the latest chunk references.
app.use('/backoffice/assets', express.static(path.join(__dirname, 'cockpit/dist/assets'), {
    maxAge: '1y', immutable: true,
}));
app.use('/backoffice', express.static(path.join(__dirname, 'cockpit/dist'), {
    setHeaders(res, filePath) {
        if (filePath.endsWith('index.html')) {
            res.setHeader('Cache-Control', 'no-cache, no-store, must-revalidate');
            res.setHeader('Pragma', 'no-cache');
            res.setHeader('Expires', '0');
        }
    },
}));
app.get('/backoffice/*', async (req, res) => {
    const distIndex = path.join(__dirname, 'cockpit/dist/index.html');
    const fs = require('fs');
    if (fs.existsSync(distIndex)) {
        res.setHeader('Cache-Control', 'no-cache, no-store, must-revalidate');
        res.setHeader('Pragma', 'no-cache');
        res.setHeader('Expires', '0');
        // Add CSP header to allow Cloudflare Insights beacon and essential scripts
        res.setHeader('Content-Security-Policy', "default-src 'self'; script-src 'self' 'unsafe-inline' 'unsafe-hashes' cdn.jsdelivr.net cdnjs.cloudflare.com static.cloudflareinsights.com; style-src 'self' 'unsafe-inline' fonts.googleapis.com; img-src * data: blob:; font-src fonts.googleapis.com fonts.gstatic.com; connect-src *; object-src 'none'; base-uri 'self';");
        res.sendFile(distIndex);
    } else {
        res.status(404).send('Back Office build not found. Run: cd cockpit && npm run build');
    }
});

// =============================================================================
// CATCH-ALL ROUTES (must be after all API routes)
// =============================================================================

app.get('*', (req, res, next) => {
    // Let API routes and cockpit routes fall through to their handlers below
    if (req.path.startsWith('/api/') || req.path.startsWith('/backoffice')) return next();
    res.sendFile(path.join(__dirname, 'public', 'index.html'));
});

