// ── GET /api/content ──────────────────────────────────────────────────────────
app.get('/api/content', async (req, res) => {
    // Section 12: require back-office auth; mask prompt instructions for non-admin
    const actor = await requirePrivileged(req, res); if (!actor) return;
    const { type, status, language, author_id, q, limit = 20, offset = 0 } = req.query;
    const conditions = [];
    const params = [];
    if (type)      { params.push(type);      conditions.push(`object_type = $${params.length}`); }
    if (status)    { params.push(status);    conditions.push(`status = $${params.length}`); }
    if (language)  { params.push(language);  conditions.push(`language = $${params.length}`); }
    if (author_id) { params.push(author_id); conditions.push(`EXISTS (SELECT 1 FROM jv_content_author_map cam WHERE cam.content_object_id=jv_content_objects.id AND cam.author_id=$${params.length}::uuid)`); }
    if (q) {
        params.push(q);
        conditions.push(`search_vector @@ plainto_tsquery('english', $${params.length})`);
    }
    const where = conditions.length ? `WHERE ${conditions.join(' AND ')}` : '';
    params.push(parseInt(limit) || 20, parseInt(offset) || 0);
    try {
        const { rows } = await pgPool.query(
            `SELECT * FROM jv_content_objects ${where}
             ORDER BY created_at DESC LIMIT $${params.length - 1} OFFSET $${params.length}`,
            params
        );
        const { rows: [{ count }] } = await pgPool.query(
            `SELECT COUNT(*) FROM jv_content_objects ${where}`,
            params.slice(0, -2)
        );
        res.json({
            items: rows.map(r => maskPromptExtension(r, actor.role)),
            total: parseInt(count),
            limit: parseInt(limit),
            offset: parseInt(offset),
        });
    } catch (e) {
        console.error('[GET /api/content]', e.message);
        res.status(500).json({ error: e.message });
    }
});

