// ── PUT /api/content/:id ──────────────────────────────────────────────────────
app.put('/api/content/:id', async (req, res) => {
    const actor = requireReviewer(req, res); if (!actor) return;
    const { id } = req.params;
    // NOTE: status changes must go through POST /api/content/:id/transition (Phase 5)
    const { title, slug, summary, language,
            meta_data, permissions, publish_targets, change_summary } = req.body;
    // Phase 10: sanitize body_html to prevent XSS
    const sanitizeHtml = require('sanitize-html');
    const SANITIZE_OPTS = {
        allowedTags: sanitizeHtml.defaults.allowedTags.concat(['h1','h2','h3','h4','h5','h6','img','figure','figcaption','blockquote','pre','code','mark','s','sup','sub']),
        allowedAttributes: {
            ...sanitizeHtml.defaults.allowedAttributes,
            '*': ['class', 'id'],
            'a': ['href', 'name', 'target', 'rel'],
            'img': ['src', 'alt', 'width', 'height'],
        },
    };
    let extension_data = req.body.extension_data;
    if (extension_data?.body_html) {
        extension_data = { ...extension_data, body_html: sanitizeHtml(extension_data.body_html, SANITIZE_OPTS) };
    }
    try {
        const { rows: current } = await pgPool.query(
            `SELECT * FROM jv_content_objects WHERE id = $1`, [id]
        );
        if (!current.length) return res.status(404).json({ error: 'Not found' });
        // Section 12: prompt recipe updates require prompt:manage
        if (current[0].object_type === 'prompt_recipe' && !hasPermission(actor.role, 'prompt:manage')) {
            return res.status(403).json({ error: 'prompt:manage permission required' });
        }
        // Snapshot before update
        await createRevision(pgPool, id, current[0], change_summary || null,
                             actor.email || actor.sub || 'system');
        const actorId = actor.email || actor.sub || 'system';
        const { rows } = await pgPool.query(
            `UPDATE jv_content_objects SET
               title          = COALESCE($2, title),
               slug           = COALESCE($3, slug),
               summary        = COALESCE($4, summary),
               language       = COALESCE($5, language),
               extension_data = COALESCE($6, extension_data),
               meta_data      = COALESCE($7, meta_data),
               permissions    = COALESCE($8, permissions),
               publish_targets = COALESCE($10, publish_targets),
               version        = version + 1,
               updated_by     = $9
             WHERE id = $1
             RETURNING *`,
            [id, title || null, slug || null, summary || null,
             language || null,
             extension_data    ? JSON.stringify(extension_data)    : null,
             meta_data         ? JSON.stringify(meta_data)         : null,
             permissions       ? JSON.stringify(permissions)       : null,
             actorId,
             publish_targets   ? JSON.stringify(publish_targets)   : null]
        );
        await logAuditEvent(pgPool, {
            event_type: 'content.updated', actor_id: actorId,
            target_type: 'jv_content_objects', target_id: id,
            details: { change_summary }, ip_address: req.ip, user_agent: req.get('user-agent'),
        });
        // Section 12: additional prompt-specific audit event
        if (rows[0].object_type === 'prompt_recipe') {
            logAuditEvent(pgPool, {
                event_type: 'prompt.updated', actor_id: actorId,
                target_type: 'jv_content_objects', target_id: id,
                details: { version: rows[0].version, change_summary },
                ip_address: req.ip, user_agent: req.get('user-agent'),
            });
        }
        res.json(rows[0]);
    } catch (e) {
        if (e.code === '23505') return res.status(409).json({ error: 'Slug already exists for this object type' });
        console.error('[PUT /api/content/:id]', e.message);
        res.status(500).json({ error: e.message });
    }
});

