// ── POST /api/content/:id/transition — Phase 5 state machine ──────────────────
app.post('/api/content/:id/transition', async (req, res) => {
    const actor = await requirePrivileged(req, res); if (!actor) return;
    const { id } = req.params;
    const { to_status, reason, scheduled_at } = req.body;
    if (!to_status) return res.status(400).json({ error: 'to_status is required' });
    const actorId = actor.email || actor.sub || 'system';
    try {
        const { rows: existing } = await pgPool.query(
            `SELECT * FROM jv_content_objects WHERE id = $1`, [id]
        );
        if (!existing.length) return res.status(404).json({ error: 'Not found' });
        const obj = existing[0];
        const fromStatus = obj.status;
        const key = `${fromStatus}:${to_status}`;
        // Admin emergency override: any → draft
        const isAdminOverride = actor.role === 'admin' && to_status === 'draft' && fromStatus !== 'draft';
        if (!isAdminOverride) {
            const transition = WORKFLOW_TRANSITIONS[key];
            if (!transition) return res.status(400).json({ error: `Invalid transition: ${fromStatus} → ${to_status}` });
            if (!transition.roles.includes(actor.role)) {
                return res.status(403).json({ error: `Role '${actor.role}' cannot perform this transition` });
            }
            const err = transition.validate(req.body, actor);
            if (err) return res.status(400).json({ error: err });
        }
        await createRevision(pgPool, id, obj, `Status: ${fromStatus} → ${to_status}`, actorId);
        const updateFields = ['status=$2', 'version=version+1', 'updated_by=$3'];
        const vals = [id, to_status, actorId];
        let p = 4;
        if (to_status === 'published') updateFields.push('published_at=COALESCE(published_at,NOW())');
        if (to_status === 'archived')  updateFields.push('archived_at=NOW()');
        if (to_status === 'scheduled' && scheduled_at) {
            updateFields.push(`scheduled_at=$${p++}`); vals.push(scheduled_at);
        }
        const { rows } = await pgPool.query(
            `UPDATE jv_content_objects SET ${updateFields.join(',')} WHERE id=$1 RETURNING *`, vals
        );
        // Review→Draft: auto-create comment with reason
        if (fromStatus === 'review' && to_status === 'draft' && reason) {
            await pgPool.query(
                `INSERT INTO jv_comments (object_type, object_id, author_id, body) VALUES ($1,$2,$3,$4)`,
                ['jv_content_objects', id, actorId, `[Revision requested] ${reason}`]
            );
        }
        await logAuditEvent(pgPool, {
            event_type: 'content.status_changed', actor_id: actorId,
            target_type: 'jv_content_objects', target_id: id,
            details: { from: fromStatus, to: to_status, reason: reason || null, emergency_override: isAdminOverride },
            ip_address: req.ip, user_agent: req.get('user-agent'),
        });
        if (obj.created_by && obj.created_by !== actorId) {
            await createNotification(pgPool, {
                recipient_id: obj.created_by, type: 'status_change',
                title: `"${obj.title || 'Untitled'}" moved to ${to_status}`,
                body: reason || null, object_type: 'jv_content_objects', object_id: id,
            });
        }
        if (to_status === 'published') {
            _evaluatePublishTargets(pgPool, id, actorId, req).catch(err =>
                console.error('[publish-targets] evaluation error:', err.message));
            runPublishingPipeline(pgPool, id, actorId, req).catch(err =>
                console.error('[pipeline] error:', err.message));
        }
        res.json(rows[0]);
    } catch (e) {
        console.error('[POST /api/content/:id/transition]', e.message);
        res.status(500).json({ error: e.message });
    }
});

