// ── GET /api/content/:id/diff ─────────────────────────────────────────────────
app.get('/api/content/:id/diff', async (req, res) => {
    const { from: fromVer, to: toVer } = req.query;
    if (!fromVer || !toVer) return res.status(400).json({ error: 'Query params from and to are required' });
    try {
        const { rows } = await pgPool.query(
            `SELECT version, snapshot FROM jv_content_revisions
             WHERE content_object_id = $1 AND version = ANY($2)
             ORDER BY version ASC`,
            [req.params.id, [parseInt(fromVer), parseInt(toVer)]]
        );
        if (rows.length < 2) return res.status(404).json({ error: 'One or both revisions not found' });
        const snapA = typeof rows[0].snapshot === 'string' ? JSON.parse(rows[0].snapshot) : rows[0].snapshot;
        const snapB = typeof rows[1].snapshot === 'string' ? JSON.parse(rows[1].snapshot) : rows[1].snapshot;
        res.json({ from: parseInt(fromVer), to: parseInt(toVer), diff: computeDiff(snapA, snapB) });
    } catch (e) {
        console.error('[GET /api/content/:id/diff]', e.message);
        res.status(500).json({ error: e.message });
    }
});

// ── GET /api/search ───────────────────────────────────────────────────────────
app.get('/api/search', async (req, res) => {
    const { q, type, status, language, author_id, taxonomy_node_id,
            from: dateFrom, to: dateTo, limit = 20, offset = 0, order } = req.query;
    const conditions = [];
    const params = [];

    if (q) {
        params.push(q);
        conditions.push(`search_vector @@ plainto_tsquery('english', $${params.length})`);
    }
    if (type) {
        const types = type.split(',').map(t => t.trim()).filter(Boolean);
        if (types.length === 1) {
            params.push(types[0]);
            conditions.push(`o.object_type = $${params.length}`);
        } else {
            params.push(types);
            conditions.push(`o.object_type = ANY($${params.length})`);
        }
    }
    if (status)    { params.push(status);    conditions.push(`o.status = $${params.length}`); }
    if (language)  { params.push(language);  conditions.push(`o.language = $${params.length}`); }
    if (author_id) { params.push(author_id); conditions.push(`EXISTS (SELECT 1 FROM jv_content_author_map cam WHERE cam.content_object_id=o.id AND cam.author_id=$${params.length}::uuid)`); }
    if (dateFrom)        { params.push(dateFrom);        conditions.push(`o.created_at >= $${params.length}`); }
    if (dateTo)          { params.push(dateTo);          conditions.push(`o.created_at <= $${params.length}`); }

    let join = '';
    if (taxonomy_node_id) {
        const nodeIds = await getDescendantIds(pgPool, parseInt(taxonomy_node_id));
        params.push(nodeIds);
        // uuid_object_id handles jv_content_objects (UUID PK); object_id handles legacy integer-PK tables
        join = `JOIN jv_content_taxonomy_map ctm ON ctm.object_table = 'jv_content_objects'
                  AND (ctm.uuid_object_id = o.id OR ctm.object_id::text = o.id::text)`;
        conditions.push(`ctm.taxonomy_node_id = ANY($${params.length})`);
    }

    const where    = conditions.length ? `WHERE ${conditions.join(' AND ')}` : '';
    const orderBy  = q ? `ts_rank(search_vector, plainto_tsquery('english', $1)) DESC, o.created_at DESC`
                       : (order === 'random' ? 'RANDOM()' : 'o.created_at DESC');
    const lim      = parseInt(limit)  || 20;
    const off      = parseInt(offset) || 0;
    params.push(lim, off);

    try {
        const { rows: items } = await pgPool.query(
            `SELECT o.* FROM jv_content_objects o ${join} ${where}
             ORDER BY ${orderBy}
             LIMIT $${params.length - 1} OFFSET $${params.length}`,
            params
        );
        const { rows: [{ count }] } = await pgPool.query(
            `SELECT COUNT(*) FROM jv_content_objects o ${join} ${where}`,
            params.slice(0, -2)
        );
        // Aggregate facets
        const { rows: typeFacets }   = await pgPool.query(`SELECT object_type AS value, COUNT(*) AS count FROM jv_content_objects GROUP BY 1`);
        const { rows: statusFacets } = await pgPool.query(`SELECT status AS value, COUNT(*) AS count FROM jv_content_objects GROUP BY 1`);
        const { rows: langFacets }   = await pgPool.query(`SELECT language AS value, COUNT(*) AS count FROM jv_content_objects GROUP BY 1`);
        const toMap = rows => Object.fromEntries(rows.map(r => [r.value, parseInt(r.count)]));
        res.json({
            items, total: parseInt(count), limit: lim, offset: off,
            facets: { type: toMap(typeFacets), status: toMap(statusFacets), language: toMap(langFacets) },
        });
    } catch (e) {
        console.error('[GET /api/search]', e.message);
        res.status(500).json({ error: e.message });
    }
});

