// PUT /api/tasks/:taskId
app.put('/api/tasks/:taskId', async (req, res) => {
    const actor = await requirePrivileged(req, res); if (!actor) return;
    const actorId = actor.email || actor.sub || 'system';
    const { title, description, status } = req.body;
    try {
        const { rows: existing } = await pgPool.query(`SELECT * FROM jv_content_tasks WHERE id=$1`, [req.params.taskId]);
        if (!existing.length) return res.status(404).json({ error: 'Task not found' });
        const task = existing[0];
        if (task.created_by !== actorId && task.assignee_id !== actorId) {
            return res.status(403).json({ error: 'Only author or assignee can update this task' });
        }
        const completedAt = status === 'completed' ? 'NOW()' : null;
        const { rows } = await pgPool.query(
            `UPDATE jv_content_tasks SET
               title       = COALESCE($2, title),
               description = COALESCE($3, description),
               status      = COALESCE($4, status),
               completed_at = CASE WHEN $4='completed' THEN COALESCE(completed_at, NOW()) ELSE completed_at END,
               updated_at  = NOW()
             WHERE id=$1 RETURNING *`,
            [req.params.taskId, title || null, description || null, status || null]
        );
        res.json(rows[0]);
    } catch (e) { console.error('[PUT task]', e.message); res.status(500).json({ error: e.message }); }
});

