// PUT /api/admin/users/:id/cms-roles
app.put('/api/admin/users/:id/cms-roles', express.json(), async (req, res) => {
    const actor = await requireRole(req, res, 'admin'); if (!actor) return;
    const { cms_roles } = req.body || {};
    if (!Array.isArray(cms_roles)) return res.status(400).json({ error: 'cms_roles must be an array' });
    // Validate each role
    for (const r of cms_roles) {
        if (!r.role || !PRIVILEGED_ROLES.includes(r.role)) {
            return res.status(400).json({ error: `Invalid role: ${r.role}` });
        }
    }
    try {
        const { rows: [user] } = await pgPool.query(`SELECT * FROM jv_users WHERE id=$1`, [req.params.id]);
        if (!user) return res.status(404).json({ error: 'User not found' });
        const oldRoles = Array.isArray(user.cms_roles) ? user.cms_roles : JSON.parse(user.cms_roles || '[]');
        await pgPool.query(`UPDATE jv_users SET cms_roles=$1 WHERE id=$2`, [JSON.stringify(cms_roles), user.id]);
        // Audit new role assignments
        const oldRoleSet = new Set(oldRoles.map(r => `${r.role}:${r.scope || ''}`));
        for (const r of cms_roles) {
            const key = `${r.role}:${r.scope || ''}`;
            if (!oldRoleSet.has(key)) {
                logAuditEvent(pgPool, { event_type: 'user.role_assigned', actor_id: actor.email,
                    target_type: 'users', target_id: String(user.id),
                    details: { role: r.role, scope: r.scope || null, assigned_by: actor.email },
                    ip_address: req.ip, user_agent: req.get('user-agent') });
            }
        }
        res.json({ success: true, cms_roles });
    } catch (e) { res.status(500).json({ error: e.message }); }
});

// GET /api/admin/users — list all CMS users (Part 3 Section 7, updated S12: entitlement filter)
