// PART 6: SERVERS MODULE, CACHE, AUDIT, PUBLISHING WORKFLOW
// =============================================================================

// ── Part 6 helpers ────────────────────────────────────────────────────────────

const CACHE_ROOT = process.env.CACHE_ROOT || '/var/cache/jubileeverse';

function _computeObjectChecksum(obj) {
    const fields = [
        obj.title, obj.slug, obj.summary, obj.status,
        obj.version, obj.published_at,
        JSON.stringify(obj.extension_data || {}),
        JSON.stringify(obj.seo_metadata || {}),
    ].map(v => String(v ?? '')).join('|');
    return crypto.createHash('sha256').update(fields).digest('hex');
}

function _computeImageChecksum(imageHashes) {
    if (!imageHashes || imageHashes.length === 0) return null;
    const sorted = [...imageHashes].sort().join('|');
    return crypto.createHash('sha256').update(sorted).digest('hex');
}

async function _callClaudeForAudit(systemPrompt, userContent) {
    const apiKey = process.env.ANTHROPIC_API_KEY;
    if (!apiKey) throw new Error('ANTHROPIC_API_KEY not set');
    const body = JSON.stringify({
        model: 'claude-sonnet-4-6',
        max_tokens: 2048,
        system: systemPrompt,
        messages: [{ role: 'user', content: userContent }],
    });
    const resp = await fetch('https://api.anthropic.com/v1/messages', {
        method: 'POST',
        headers: {
            'Content-Type': 'application/json',
            'x-api-key': apiKey,
            'anthropic-version': '2023-06-01',
        },
        body,
    });
    if (!resp.ok) throw new Error(`Anthropic API error: ${resp.status}`);
    const data = await resp.json();
    const text = data.content?.[0]?.text ?? '';
    const match = text.match(/\{[\s\S]*\}/);
    if (!match) throw new Error('No JSON found in audit response');
    return JSON.parse(match[0]);
}

async function _runContentAudit(objectId) {
    // Load content object
    const { rows: [obj] } = await pgPool.query(
        `SELECT id, title, object_type, status, summary, version, extension_data
         FROM jv_content_objects WHERE id=$1`, [objectId]
    );
    if (!obj) return;

    // Load global active rubric
    const { rows: [rubric] } = await pgPool.query(
        `SELECT * FROM audit_rubrics WHERE is_global=true AND is_active=true ORDER BY version DESC LIMIT 1`
    );

    const systemPrompt = rubric?.system_prompt || `You are a theological audit engine. Evaluate the content against Christian orthodox doctrine.
Return ONLY valid JSON with this structure:
{
  "scores": {
    "scriptural_accuracy": 0-100,
    "doctrinal_clarity": 0-100,
    "pastoral_tone": 0-100,
    "misinterpretation_risk": 0-100,
    "sin_promotion": 0-100
  },
  "findings": [
    {"category":"scriptural_accuracy","severity":"warning","excerpt":"...","explanation":"..."}
  ],
  "explanation": "Brief overall explanation"
}
Scores: scriptural_accuracy=accuracy of scripture references (100=perfect), doctrinal_clarity=clear doctrine (100=clear), pastoral_tone=compassionate tone (100=excellent), misinterpretation_risk=risk of being misread as false teaching (100=low risk), sin_promotion=promotion of sin (100=none detected). If sin_promotion < 50, the content fails immediately regardless of composite score.`;

    const userContent = `Audit this ${obj.object_type} content:\n\nTitle: ${obj.title}\n\nContent:\n${obj.summary || '(no content body available)'}`;

    let auditResult, auditResultRaw;
    try {
        auditResult = await _callClaudeForAudit(systemPrompt, userContent);
    } catch (e) {
        console.error(`[Audit] Claude call failed for ${objectId}:`, e.message);
        auditResult = {
            scores: { scriptural_accuracy: 0, doctrinal_clarity: 0, pastoral_tone: 0, misinterpretation_risk: 0, sin_promotion: 0 },
            findings: [{ category: 'system', severity: 'critical', excerpt: '', explanation: `Audit service error: ${e.message}` }],
            explanation: 'Audit failed due to service error',
        };
    }

    const s = auditResult.scores || {};
    const sa = s.scriptural_accuracy ?? 0;
    const dc = s.doctrinal_clarity ?? 0;
    const pt = s.pastoral_tone ?? 0;
    const rm = s.misinterpretation_risk ?? 0;
    const eps = s.sin_promotion ?? 0;
    const composite = (sa * 0.30) + (dc * 0.25) + (pt * 0.15) + (rm * 0.15) + (eps * 0.15);
    const compositeRounded = Math.round(composite * 100) / 100;

    let result;
    if (eps < 50) {
        result = 'failed';
    } else if (compositeRounded >= 80) {
        result = 'passed';
    } else if (compositeRounded >= 60) {
        result = 'passed_with_warnings';
    } else {
        result = 'failed';
    }

    // Store audit report
    const { rows: [report] } = await pgPool.query(
        `INSERT INTO audit_reports (object_id, object_version, audit_type, rubric_id, rubric_version,
            model_id, scores, findings, result)
         VALUES ($1, $2, 'doctrinal', $3, $4, 'claude-sonnet-4-6', $5, $6, $7)
         RETURNING id`,
        [objectId, obj.version, rubric?.id ?? null, rubric?.version ?? 1,
         JSON.stringify({ ...s, composite: compositeRounded }),
         JSON.stringify(auditResult.findings || []), result]
    );

    // Update content object: audit_status, audit_score, last_audit_id, and status
    const newStatus = result === 'failed' ? 'additional_work' : 'pending_review';
    await pgPool.query(
        `UPDATE jv_content_objects SET
            audit_status=$1, audit_score=$2, last_audit_id=$3,
            status=$4, updated_at=NOW()
         WHERE id=$5`,
        [result, compositeRounded, report.id, newStatus, objectId]
    );

    await logAuditEvent(pgPool, {
        event_type: 'content.audit_completed',
        actor_id: 'system',
        target_type: 'content_object',
        target_id: objectId,
        details: { composite_score: compositeRounded, result, rubric_id: rubric?.id, report_id: report.id },
        ip_address: null,
        user_agent: 'system',
    });

    if (result === 'failed') {
        await logAuditEvent(pgPool, {
            event_type: 'content.audit_failed_gate',
            actor_id: 'system',
            target_type: 'content_object',
            target_id: objectId,
            details: { score: compositeRounded, failure_reason: eps < 50 ? 'sin_promotion_threshold' : 'composite_below_60' },
            ip_address: null,
            user_agent: 'system',
        });
    }

    return { result, composite: compositeRounded, report_id: report.id };
}

async function _propagateToNodes(objectId, objectType, compositeChecksum) {
    try {
        const { rows: nodes } = await pgPool.query(
            `SELECT * FROM server_nodes WHERE is_active=true AND environment='production'`
        );
        for (const node of nodes) {
            if (!node.internal_sync_endpoint) continue;
            const { rows: [logRow] } = await pgPool.query(
                `INSERT INTO propagation_log (object_id, object_type, node_id, action, composite_checksum, status)
                 VALUES ($1, $2, $3, 'publish', $4, 'pending')
                 RETURNING id`,
                [objectId, objectType, node.id, compositeChecksum]
            );
            // Fire-and-forget — retry logic is best-effort
            _sendSyncToNode(node, objectId, objectType, compositeChecksum, logRow.id)
                .catch(e => console.error(`[Propagation] Node ${node.id} error:`, e.message));
        }
    } catch (e) {
        console.error('[Propagation] Error queuing propagation:', e.message);
    }
}

async function _sendSyncToNode(node, objectId, objectType, compositeChecksum, logId, attempt = 0) {
    const MAX_RETRIES = 3;
    try {
        const resp = await Promise.race([
            fetch(`${node.internal_sync_endpoint}/sync`, {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ object_id: objectId, object_type: objectType, action: 'publish', composite_checksum: compositeChecksum }),
            }),
            new Promise((_, reject) => setTimeout(() => reject(new Error('timeout')), 10000)),
        ]);
        const data = await resp.json().catch(() => ({}));
        await pgPool.query(
            `UPDATE propagation_log SET status='synced', response_status=$1, checksum_verified=$2, completed_at=NOW() WHERE id=$3`,
            [resp.status, data.checksum_verified ?? false, logId]
        );
        await logAuditEvent(pgPool, {
            event_type: 'propagation.push_confirmed',
            actor_id: 'system', target_type: 'propagation_log', target_id: logId,
            details: { object_id: objectId, node_id: node.id, checksum_verified: data.checksum_verified },
            ip_address: null, user_agent: 'system',
        });
    } catch (e) {
        if (attempt < MAX_RETRIES) {
            const delay = Math.pow(2, attempt) * 5000;
            setTimeout(() => _sendSyncToNode(node, objectId, objectType, compositeChecksum, logId, attempt + 1), delay);
        } else {
            await pgPool.query(
                `UPDATE propagation_log SET status='failed', error_message=$1, retry_count=$2 WHERE id=$3`,
                [e.message, attempt, logId]
            ).catch(() => {});
        }
    }
}

async function _computeTaxonomyChecksum(nodeId) {
    const { rows } = await pgPool.query(
        `SELECT co.id::text, co.version::text
         FROM jv_content_objects co
         JOIN jv_content_taxonomy_map ctm ON ctm.object_id::text = co.id::text
         WHERE ctm.taxonomy_node_id=$1 AND co.status='published'
         ORDER BY co.id`,
        [nodeId]
    );
    const ids = rows.map(r => r.id).sort();
    const pairs = rows.map(r => `${r.id}:${r.version}`).sort();
    const membership = crypto.createHash('sha256').update(ids.join(',')).digest('hex');
    const inventory = crypto.createHash('sha256').update(pairs.join(',')).digest('hex');
    await pgPool.query(
        `INSERT INTO taxonomy_checksums (taxonomy_node_id, membership_checksum, content_inventory_checksum, last_computed_at, object_count)
         VALUES ($1, $2, $3, NOW(), $4)
         ON CONFLICT (taxonomy_node_id) DO UPDATE SET
           membership_checksum=$2, content_inventory_checksum=$3, last_computed_at=NOW(), object_count=$4`,
        [nodeId, membership, inventory, rows.length]
    );
}

