// ── Part 6 S7: Cache Refresh Endpoint ────────────────────────────────────────

// POST /api/v1/cache/refresh — on-demand cache refresh (reviewer+)
app.post('/api/v1/cache/refresh', async (req, res) => {
    const actor = await requirePrivileged(req, res); if (!actor) return;
    if (!hasPermission(actor.role, 'content:refresh')) return res.status(403).json({ error: 'Forbidden' });
    const { object_id, object_type, site_id } = req.body;
    if (!object_id) return res.status(400).json({ error: 'object_id required' });
    const start = Date.now();
    try {
        const { rows: [obj] } = await pgPool.query(
            `SELECT id, title, slug, summary, status, version, extension_data, seo_metadata, published_at
             FROM jv_content_objects WHERE id=$1`, [object_id]
        );
        if (!obj) return res.status(404).json({ error: 'Object not found' });
        const newChecksum = _computeObjectChecksum(obj);
        const changesDetected = obj.composite_checksum !== newChecksum;
        if (changesDetected) {
            await pgPool.query(
                `UPDATE jv_content_objects SET composite_checksum=$1, updated_at=NOW() WHERE id=$2`,
                [newChecksum, object_id]
            );
        }
        const duration = Date.now() - start;
        await logAuditEvent(pgPool, {
            event_type: 'cache.manual_refresh',
            actor_id: actor.id, target_type: 'content_object', target_id: object_id,
            details: { object_type, changes_detected: changesDetected, duration_ms: duration },
            ip_address: req.ip, user_agent: req.headers['user-agent'],
        });
        res.json({ status: changesDetected ? 'refreshed' : 'current', changes_detected: changesDetected, duration_ms: duration });
    } catch (e) { res.status(500).json({ error: e.message }); }
});

