// GET /api/v1/audit/queue — get audit queue items
app.get('/api/v1/audit/queue', async (req, res) => {
    const actor = await requirePrivileged(req, res); if (!actor) return;
    if (!hasPermission(actor.role, 'audit:view')) return res.status(403).json({ error: 'Forbidden' });
    const { status, audit_type, limit = 50, offset = 0 } = req.query;
    try {
        let where = '1=1';
        const params = [];
        if (status) { params.push(status); where += ` AND co.status=$${params.length}`; }
        if (audit_type) { params.push(audit_type); where += ` AND ar.audit_type=$${params.length}`; }
        params.push(parseInt(limit)); params.push(parseInt(offset));
        const { rows } = await pgPool.query(
            `SELECT co.id, co.title, co.object_type, co.status, co.audit_status, co.audit_score, co.updated_at,
                    ar.id AS audit_report_id, ar.result AS audit_result, ar.scores, ar.findings, ar.audited_at,
                    ar.audit_type, ar.model_id,
                    (SELECT name FROM audit_rubrics WHERE id=ar.rubric_id) AS rubric_name
             FROM jv_content_objects co
             LEFT JOIN audit_reports ar ON ar.id=co.last_audit_id
             WHERE ${where}
             ORDER BY co.updated_at DESC
             LIMIT $${params.length - 1} OFFSET $${params.length}`,
            params
        );
        const { rows: [{ count }] } = await pgPool.query(
            `SELECT COUNT(*) FROM jv_content_objects co
             LEFT JOIN audit_reports ar ON ar.id=co.last_audit_id
             WHERE ${where}`,
            params.slice(0, -2)
        );
        res.json({ items: rows, total: parseInt(count) });
    } catch (e) { res.status(500).json({ error: e.message }); }
});

// GET /api/v1/audit/results/:objectId — get audit report for a content object
app.get('/api/v1/audit/results/:objectId', async (req, res) => {
    const actor = await requirePrivileged(req, res); if (!actor) return;
    if (!hasPermission(actor.role, 'audit:view')) return res.status(403).json({ error: 'Forbidden' });
    try {
        const { rows } = await pgPool.query(
            `SELECT ar.*, (SELECT name FROM audit_rubrics WHERE id=ar.rubric_id) AS rubric_name
             FROM audit_reports ar
             WHERE ar.object_id=$1
             ORDER BY ar.audited_at DESC LIMIT 10`,
            [req.params.objectId]
        );
        res.json({ reports: rows });
    } catch (e) { res.status(500).json({ error: e.message }); }
});

// POST /api/v1/audit/rerun/:objectId — re-run audit for a content object
app.post('/api/v1/audit/rerun/:objectId', async (req, res) => {
    const actor = await requirePrivileged(req, res); if (!actor) return;
    if (!hasPermission(actor.role, 'audit:view')) return res.status(403).json({ error: 'Forbidden' });
    try {
        const { rows: [obj] } = await pgPool.query(`SELECT id, status FROM jv_content_objects WHERE id=$1`, [req.params.objectId]);
        if (!obj) return res.status(404).json({ error: 'Object not found' });
        // Mark as internal_audit and enqueue
        await pgPool.query(`UPDATE jv_content_objects SET status='internal_audit', audit_status='pending', updated_at=NOW() WHERE id=$1`, [obj.id]);
        await logAuditEvent(pgPool, {
            event_type: 'content.audit_started',
            actor_id: actor.id, target_type: 'content_object', target_id: obj.id,
            details: { triggered_by: actor.email },
            ip_address: req.ip, user_agent: req.headers['user-agent'],
        });
        // Run audit asynchronously
        _runContentAudit(obj.id).catch(e => console.error('[Audit] Rerun failed:', e.message));
        res.json({ success: true, message: 'Audit queued' });
    } catch (e) { res.status(500).json({ error: e.message }); }
});

// POST /api/v1/audit/rewrite/:objectId — trigger AI rewrite to improve score
app.post('/api/v1/audit/rewrite/:objectId', async (req, res) => {
    const actor = await requirePrivileged(req, res); if (!actor) return;
    if (!hasPermission(actor.role, 'audit:rewrite')) return res.status(403).json({ error: 'Forbidden' });
    try {
        const { rows: [obj] } = await pgPool.query(
            `SELECT co.*, ar.scores, ar.findings
             FROM jv_content_objects co
             LEFT JOIN audit_reports ar ON ar.id=co.last_audit_id
             WHERE co.id=$1`, [req.params.objectId]
        );
        if (!obj) return res.status(404).json({ error: 'Object not found' });

        const findings = obj.findings || [];
        const originalScore = obj.audit_score;
        const findingsSummary = findings.map(f => `[${f.severity}] ${f.category}: ${f.explanation}`).join('\n');

        // Generate improved version via Claude
        let rewrittenContent;
        try {
            rewrittenContent = await _callClaudeForAudit(
                `You are a Christian content editor. Rewrite the content to address theological concerns while preserving the original topic and voice. Return JSON: {"title": "...", "summary": "..."}`,
                `Original content:\nTitle: ${obj.title}\nContent: ${obj.summary}\n\nAudit findings to address:\n${findingsSummary}`
            );
        } catch (e) {
            return res.status(500).json({ error: `Rewrite failed: ${e.message}` });
        }

        // Create revision with improved content
        await createRevision(pgPool, obj.id, actor.id, 'ai_rewrite', `AI rewrite to improve audit score from ${originalScore}`);
        const { rows: [updated] } = await pgPool.query(
            `UPDATE jv_content_objects SET
               title=COALESCE($1, title),
               summary=COALESCE($2, summary),
               status='internal_audit',
               audit_status='pending',
               version=version+1,
               updated_at=NOW()
             WHERE id=$3 RETURNING id`,
            [rewrittenContent.title, rewrittenContent.summary, obj.id]
        );

        await logAuditEvent(pgPool, {
            event_type: 'content.rewrite_requested',
            actor_id: actor.id, target_type: 'content_object', target_id: obj.id,
            details: { original_score: originalScore, triggered_by: actor.email },
            ip_address: req.ip, user_agent: req.headers['user-agent'],
        });

        // Run new audit asynchronously
        _runContentAudit(obj.id).catch(e => console.error('[Audit] Post-rewrite audit failed:', e.message));
        res.json({ success: true, object_id: obj.id });
    } catch (e) { res.status(500).json({ error: e.message }); }
});

