// POST /api/v1/audit/rubrics — create audit rubric
app.post('/api/v1/audit/rubrics', async (req, res) => {
    const actor = await requirePrivileged(req, res); if (!actor) return;
    if (!hasPermission(actor.role, 'audit:configure')) return res.status(403).json({ error: 'Forbidden' });
    const { name, rubric_type, is_global, content_types, scoring_weights, system_prompt, evaluation_prompt, pass_threshold, warning_threshold } = req.body;
    if (!name) return res.status(400).json({ error: 'name required' });
    try {
        const { rows: [rubric] } = await pgPool.query(
            `INSERT INTO audit_rubrics (name, rubric_type, is_global, content_types, scoring_weights, system_prompt, evaluation_prompt, pass_threshold, warning_threshold, created_by)
             VALUES ($1, $2, $3, $4::jsonb, $5::jsonb, $6, $7, $8, $9, $10) RETURNING *`,
            [name, rubric_type || 'doctrinal', !!is_global,
             JSON.stringify(content_types || []), JSON.stringify(scoring_weights || {}),
             system_prompt, evaluation_prompt, pass_threshold ?? 80, warning_threshold ?? 60, actor.id]
        );
        res.status(201).json(rubric);
    } catch (e) { res.status(500).json({ error: e.message }); }
});

